texts[26]="}},[\"numberField\"]={[\"bindings\"]={[\"finite\"]=\"builtin:Platform/runes.lua:finite\"},[\"code\"]=\"\\010    if not self:CanReadValue(value) then return nil,'restricted-value' end\\010    if canaccessvalue and not canaccessvalue(value) then return nil,'restricted-value' end\\010    if value==nil then return nil,missing end\\010    if not finite(value) then return nil,'invalid-api-result' end\\010    return value\\010\",[\"kind\"]=\"function\",[\"line\"]=12,[\"parameters\"]={\"self\",\"value\",\"missing\"}},[\"validIndex\"]={[\"bindings\"]={[\"finite\"]=\"builtin:Platform/runes.lua:finite\"},[\"code\"]=\"\\010    if not self:CanReadValue(index) then return nil,'restricted-value' end\\010    if not finite(index) or index%1~=0 or index<1 or index>6 then return nil,'invalid-rune-index' end\\010    return true\\010\",[\"kind\"]=\"function\",[\"line\"]=7,[\"parameters\"]={\"self\",\"index\"}}},[\"hash\"]=\"1b3d58a78948c75746073261675d39f0f3a63c42864e926b62cd4eea9770aeac\"},[\"Platform/spells.lua\"]={[\"bindings\"]={[\"Platform_GetSpellCharges\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Spell ID or client-recognized spell name whose charges should be read.\",[\"name\"]=\"spell\",[\"type\"]=\"number | string\"}},[\"bindings\"]={[\"copy\"]=\"builtin:Platform/spells.lua:copy\",[\"identifier\"]=\"builtin:Platform/spells.lua:identifier\"},[\"callName\"]=\"addon.Platform:GetSpellCharges\",[\"code\"]=\"\\010    local valid,reason=identifier(spell)\\010    if not valid then return nil,reason end\\010    local ok,record\\010    if C_Spell and type(C_Spell.GetSpellCharges)==\\\"function\\\" then\\010        ok,record=pcall(C_Spell.GetSpellCharges,spell)\\010    elseif type(GetSpellCharges)==\\\"function\\\" then\\010        local current,maximum,start,duration,rate\\010        ok,current,maximum,start,duration,rate=pcall(GetSpellCharges,spell)\\010        if not ok then return nil,\\\"api-error\\\" end\\010        record={currentCharges=current,maxCharges=maximum,cooldownStartTime=start,cooldownDuration=duration,chargeModRate=rate}\\010    else return nil,\\\"missing-api\\\" end\\010    if not ok then return nil,\\\"api-error\\\" end\\010    if not self:CanReadValue(record) then return nil,\\\"restricted-value\\\" end\\010    if record==nil then return nil,\\\"spell-charges-unavailable\\\" end\\010    local charges,why=copy(record,{currentCharges=\\\"number\\\",maxCharges=\\\"number\\\",cooldownStartTime=\\\"number\\\",\\010        cooldownDuration=\\\"number\\\",chargeModRate=\\\"number\\\",isActive=\\\"boolean\\\"})\\010    if not charges then return nil,why end\\010    if next(charges)==nil then return nil,\\\"spell-charges-unavailable\\\" end\\010    local current,maximum,start,duration=charges.currentCharges,charges.maxCharges,charges.cooldownStartTime,charges.cooldownDuration\\010    if current==nil or maximum==nil or start==nil or duration==nil or current<0 or current%1~=0\\010        or maximum<1 or maximum%1~=0 or current>maximum or start<0 or duration<0\\010        or charges.chargeModRate and charges.chargeModRate<=0 then return nil,\\\"invalid-api-result\\\" end\\010    local active=current<maximum and start>0 and duration>0\\010    if charges.isActive==nil then charges.isActive=active\\010    elseif charges.isActive and not active then return nil,\\\"invalid-api-result\\\" end\\010    charges.chargeModRate=charges.chargeModRate or 1\\010    return charges\\010\",[\"description\"]=\"Read a normalized charge record: currentCharges, maxCharges, cooldownStartTime, cooldownDuration, chargeModRate and isActive. Unsupported spells or restricted client data return nil with a reason.\",[\"kind\"]=\"function\",[\"line\"]=160,[\"parameters\"]={\"self\",\"spell\"},[\"returns\"]={{[\"description\"]=\"Readable charge record, or nil when unavailable.\",[\"type\"]=\"table | nil\"},{[\"description\"]=\"Availability or validation reason when the record is nil.\",[\"type\"]=\"string | nil\"}}},[\"Platform_GetSpellCooldown\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Spell ID or client-recognized spell name whose cooldown should be read.\",[\"name\"]=\"spell\",[\"type\"]=\"number | string\"}},[\"bindings\"]={[\"copy\"]=\"builtin:Platform/spells.lua:copy\",[\"identifier\"]=\"builtin:Platform/spells.lua:identifier\"},[\"callName\"]=\"addon.Platform:GetSpellCooldown\",[\"code\"]=\"\\010    local valid, reason = identifier(spell)\\010    if not valid then return nil, reason end\\010    local ok, record\\010    if C_Spell and type(C_Spell.GetSpellCooldown) == \\\"function\\\" then\\010        ok, record = pcall(C_Spell.GetSpellCooldown, spell)\\010    elseif type(GetSpellCooldown) == \\\"function\\\" then\\010        local start, duration, enabled, rate\\010        ok, start, duration, enabled, rate = pcall(GetSpellCooldown, spell)\\010        if not ok then return nil, \\\"api-error\\\" end\\010        for _, value in pairs({start=start, duration=duration, enabled=enabled, rate=rate}) do\\010            if not self:CanReadValue(value) then return nil, \\\"restricted-value\\\" end\\010        end\\010        if start ~= nil then\\010            if enabled ~= 0 and enabled ~= 1 then return nil, \\\"invalid-api-result\\\" end\\010            record = {startTime=start, duration=duration, isEnabled=enabled == 1, modRate=rate or 1}\\010        end\\010    else return nil, \\\"missing-api\\\" end\\010    if not ok then return nil, \\\"api-error\\\" end\\010    if not self:CanReadValue(record) then return nil, \\\"restricted-value\\\" end\\010    if record == nil then return nil, \\\"spell-data-unavailable\\\" end\\010    local cooldown, why = copy(record, {startTime=\\\"number\\\", duration=\\\"number\\\", isEnabled=\\\"boolean\\\", modRate=\\\"number\\\"})\\010    if not cooldown then return nil, why end\\010    if cooldown.startTime == nil or cooldown.duration == nil or cooldown.isEnabled == nil\\010        or cooldown.startTime < 0 or cooldown.duration < 0 or (cooldown.modRate and cooldown.modRate <= 0) then\\010        return nil, \\\"invalid-api-result\\\"\\010    end\\010    cooldown.modRate = cooldown.modRate or 1\\010    return cooldown\\010\",[\"description\"]=\"Read and normalize a spell cooldown across supported clients. The returned record contains startTime, duration, isEnabled and modRate. The timestamps and duration already describe expiration in GetTime() seconds; do not divide them by modRate.\",[\"kind\"]=\"function\",[\"line\"]=87,[\"parameters\"]={\"self\",\"spell\"},[\"returns\"]={{[\"description\"]=\"Readable cooldown record, or nil when unavailable.\",[\"type\"]=\"table | nil\"},{[\"description\"]=\"Availability or validation reason when the record is nil.\",[\"type\"]=\"string | nil\"}}},[\"Platform_IsAutoRepeatActive\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Positive integer spell ID, not a spell-book slot.\",[\"name\"]=\"spellID\",[\"type\"]=\"number\"}},[\"bindings\"]={[\"identifier\"]=\"builtin:Platform/spells.lua:identifier\"},[\"callName\"]=\"addon.Platform:IsAutoRepeatActive\",[\"code\"]=\"\\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\\010    local valid,reason=identifier(spellID,true)\\010    if not valid then return nil,reason end\\010    local native=C_Spell and C_Spell.IsAutoRepeatSpell\\010    local ok,active\\010    if type(native)=='function' then\\010        ok,active=pcall(native,spellID)\\010    else\\010        if type(IsAutoRepeatSpell)~='function' or type(FindSpellBookSlotBySpellID)~='function' then return nil,'missing-api' end\\010        local found,slot=pcall(FindSpellBookSlotBySpellID,spellID,false)\\010        if not found then return nil,'api-error' end\\010        if not self:CanReadValue(slot) then return nil,'restricted-value' end\\010        if slot==nil then return nil,'spell-not-in-book' end\\010        if type(slot)~='number' or slot<1 or slot==math.huge or slot%1~=0 then return nil,'invalid-api-result' end\\010        ok,active=pcall(IsAutoRepeatSpell,slot,BOOKTYPE_SPELL or 'spell')\\010    end\\010    if not ok then return nil,'api-error' end\\010    if not self:CanReadValue(active) then return nil,'restricted-value' end\\010    if type(native)~='function' then\\010        if active==0 then active=false elseif active==1 then active=true end\\010    end\\010    if type(active)~='boolean' then return nil,'invalid-api-result' end\\010    return active\\010\",[\"description\"]=\"Read the player auto-repeat state for a spell such as Shoot or Auto Shot. This is distinct from a current or queued cast. Modern clients receive the exact spell ID; a legacy query resolves the player spell-book slot first. Restricted client policies, unreadable results and unavailable book slots return nil with a reason. This observes state and never starts or stops a spell.\",[\"kind\"]=\"function\",[\"line\"]=209,[\"parameters\"]={\"self\",\"spellID\"},[\"returns\"]={{[\"description\"]=\"True when the client reports this spell auto-repeating; false when it reports inactive; nil when unavailable.\",[\"type\"]=\"boolean | nil\"},{[\"description\"]=\"Validation or availability reason for a nil result.\",[\"type\"]=\"string | nil\"}}},[\"Platform_IsSpellReady\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Spell ID or client-recognized spell name whose cooldown should be checked.\",[\"name\"]=\"spell\",[\"type\"]=\"number | string\"},{[\"description\"]=\"Current evaluation time in seconds from GetTime(), normally evalStart.\",[\"name\"]=\"now\",[\"type\"]=\"number\"}},[\"bindings\"]={},[\"callName\"]=\"addon.Platform:IsSpellReady\",[\"code\"]=\"\\010    if not self:CanReadValue(now) then return nil, \\\"restricted-value\\\" end\\010    if type(now)~=\\\"number\\\" or now~=now or now==math.huge or now==-math.huge then\\010        return nil, \\\"invalid-time\\\"\\010    end\\010    local cooldown,reason=self:GetSpellCooldown(spell)\\010    if not cooldown then return nil,reason end\\010    if not cooldown.isEnabled then return false end\\010    local expires=cooldown.startTime+cooldown.duration\\010    if cooldown.duration==0 or expires<=now then return true end\\010\\010    local gcd,why=self:GetGlobalCooldown()\\010    if not gcd then return nil,why end\\010    if not gcd.isEnabled or gcd.duration==0 then return false end\\010    -- modRate controls cooldown animation; API timestamps/duration already\\010    -- describe expiration in GetTime seconds, so do not divide them by it.\\010    local gcdExpires=gcd.startTime+gcd.duration\\010    return gcdExpires>now and expires<=gcdExpires+0.001\\010\",[\"description\"]=\"Check whether a spell can be recommended now, allowing a spell whose remaining cooldown ends with the current global cooldown. This checks cooldown readiness only; it does not check learned status, range or resource usability. Pass evaluation time from evalStart or GetTime().\",[\"kind\"]=\"function\",[\"line\"]=140,[\"parameters\"]={\"self\",\"spell\",\"now\"},[\"returns\"]={{[\"description\"]=\"True when ready by the end of the global cooldown; false when its own cooldown prevents recommendation; nil when the client cannot supply a readable result.\",[\"type\"]=\"boolean | nil\"},{[\"description\"]=\"Availability or validation reason when the result is nil.\",[\"type\"]=\"string | nil\"}}},[\"copy\"]={[\"bindings\"]={[\"platform\"]=\"builtin:Platform/spells.lua:platform\"},[\"code\"]=\"\\010    if not platform:CanReadValue(record) then return nil, \\\"restricted-value\\\" end\\010    if type(record) ~= \\\"table\\\" then return nil, \\\"invalid-api-result\\\" end\\010    local result = {}\\010    for key, kind in pairs(fields) do\\010        local value = record[key]\\010        if not platform:CanReadValue(value) then return nil, \\\"restricted-value\\\" end\\010        if value ~= nil then\\010            if type(value) ~= kind and not (kind == \\\"icon\\\" and (type(value) == \\\"number\\\" or type(value) == \\\"string\\\")) then\\010                return nil, \\\"invalid-api-result\\\"\\010            end\\010            if type(value) == \\\"number\\\" and (value ~= value or value == math.huge or value == -math.huge) then\\010                return nil, \\\"invalid-api-result\\\"\\010            end\\010            result[key] = value\\010        end\\010    end\\010    return result\\010\",[\"kind\"]=\"function\",[\"line\"]=11,[\"parameters\"]={\"record\",\"fields\"}},[\"identifier\"]={[\"bindings\"]={[\"platform\"]=\"builtin:Platform/spells.lua:platform\"},[\"code\"]=\"\\010    if not platform:CanReadValue(value) then return false, \\\"restricted-value\\\" end\\010    if type(value) == \\\"number\\\" and value > 0 and value < math.huge and value % 1 == 0 then return true end\\010    if not idOnly and type(value) == \\\"string\\\" and #value > 0 then return true end\\010    return false, \\\"invalid-spell\\\"\\010\",[\"kind\"]=\"function\",[\"line\"]=4,[\"parameters\"]={\"value\",\"idOnly\"}},[\"platform\"]={[\"kind\"]=\"value\"}},[\"hash\"]=\"5949b51dfd644e8e4ba37e8da81726d7a7c1aca1382d4d7ef9e99a8f6314185e\"},[\"Platform/threat.lua\"]={[\"bindings\"]={[\"Platform_GetUnitThreatObservation\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Exact unit token used for existence and as the recipient of player hostility and threat queries.\",[\"name\"]=\"unit\",[\"type\"]=\"string\"}},[\"bindings\"]={},[\"callName\"]=\"addon.Platform:GetUnitThreatObservation\",[\"code\"]=\"\\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\\010    if not self:CanReadValue(unit) then return nil,'restricted-value' end\\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\\010    if type(UnitExists)~='function' then return nil,'missing-api' end\\010    local existsOk,exists=pcall(UnitExists,unit)\\010    if not existsOk then return nil,'api-error' end\\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\\010    if exists==nil then return nil,'unit-data-unavailable' end\\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\\010    if not exists then return false end\\010    if type(UnitIsEnemy)~='function' then return nil,'missing-api' end\\010    local enemyOk,enemy=pcall(UnitIsEnemy,'player',unit)\\010    if not enemyOk then return nil,'api-error' end\\010    if not self:CanReadValue(enemy) then return nil,'restricted-value' end\\010    if enemy==nil then return nil,'unit-data-unavailable' end\\010    if type(enemy)~='boolean' then return nil,'invalid-api-result' end\\010    if not enemy then return false end\\010    if type(UnitThreatSituation)~='function' then return nil,'missing-api' end\\010    local threatOk,threat=pcall(UnitThreatSituation,'player',unit)\\010    if not threatOk then return nil,'api-error' end\\010    if not self:CanReadValue(threat) then return nil,'restricted-value' end\\010    if canaccessvalue and not canaccessvalue(threat) then return nil,'restricted-value' end\\010    if threat==nil then return false end\\010    if type(threat)~='number' or threat~=threat or threat==math.huge or threat==-math.huge then return nil,'invalid-api-result' end\\010    return threat\\010\",[\"description\"]=\"Observe ordered selected-unit existence, hostility from player, then the player threat status on that unit. Known absence, nonenemy and a successfully read nil threat status return false, preserving the no-threat predicate. Finite status numbers including zero retain their original comparison meaning. Required missing, failed, nil, restricted or malformed facts return nil with a reason. No attackability, death, combat or vehicle inference is added.\",[\"kind\"]=\"function\",[\"line\"]=6,[\"parameters\"]={\"self\",\"unit\"},[\"returns\"]={{[\"description\"]=\"Finite native threat status, false for known absence/nonenemy/no-threat, or nil for unavailable observations.\",[\"type\"]=\"number | boolean | nil\"},{[\"description\"]=\"Policy, query-validation or availability reason for a nil threat observation.\",[\"type\"]=\"string | nil\"}}}},[\"hash\"]=\"3c4876c3ad0971680e220db8d8f8ab725f8df7a152302c030d9b3d5cfc208227\"},[\"Platform/unit_attackability.lua\"]={[\"bindings\"]={[\"Platform_GetUnitAttackabilityObservation\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Exact selected unit token; the attacker remains player.\",[\"name\"]=\"unit\",[\"type\"]=\"string\"}},[\"bindings\"]={},[\"callName\"]=\"addon.Platform:GetUnitAttackabilityObservation\",[\"code\"]=\"\\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\\010    if not self:CanReadValue(unit) then return nil,'restricted-value' end\\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\\010    if type(UnitExists)~='function' then return nil,'missing-api' end\\010    local existsOk,exists=pcall(UnitExists,unit)\\010    if not existsOk then return nil,'api-error' end\\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\\010    if exists==nil then return nil,'unit-data-unavailable' end\\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\\010    if not exists then return false end\\010    if type(UnitCanAttack)~='function' then return nil,'missing-api' end\\010    local attackOk,attack=pcall(UnitCanAttack,'player',unit)\\010    if not attackOk then return nil,'api-error' end\\010    if not self:CanReadValue(attack) then return nil,'restricted-value' end\\010    if attack==nil then return nil,'attackability-data-unavailable' end\\010    if type(attack)~='boolean' then return nil,'invalid-api-result' end\\010    if not attack then return false end\\010    if type(UnitIsDead)~='function' then return nil,'missing-api' end\\010    local deadOk,dead=pcall(UnitIsDead,unit)\\010    if not deadOk then return nil,'api-error' end\\010    if not self:CanReadValue(dead) then return nil,'restricted-value' end\\010    if dead==nil then return nil,'death-data-unavailable' end\\010    if type(dead)~='boolean' then return nil,'invalid-api-result' end\\010    return not dead\\010\",[\"description\"]=\"Observe whether the player can attack a selected unit that is not dead, using the exact UnitExists, UnitCanAttack and UnitIsDead predicates. Known absence or a readable false attack result returns false without querying death. Required missing, failed, restricted or malformed observations return nil with a reason. This does not test ghosts, range, hostility or ability usability, and does not redirect unit ownership.\",[\"kind\"]=\"function\",[\"line\"]=6,[\"parameters\"]={\"self\",\"unit\"},[\"returns\"]={{[\"description\"]=\"True for a readable attackable non-dead unit, false for a conclusive negative result, or nil when a required observation is unavailable.\",[\"type\"]=\"boolean | nil\"},{[\"description\"]=\"Policy, query-validation or availability reason for nil attackability.\",[\"type\"]=\"string | nil\"}}}},[\"hash\"]=\"dc5d6660e36bff0ee37c9592782846f5ea5db15f25e71cc56c9d6c6f0c3d4bc2\"},[\"Platform/unit_flags.lua\"]={[\"bindings\"]={[\"Platform_GetUnitFlagObservation\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Exact unit token whose selected flag should be observed.\",[\"name\"]=\"unit\",[\"type\"]=\"string\"},{[\"description\"]=\"One of combat, enemy or pvp; other flag kinds are not supported.\",[\"name\"]=\"kind\",[\"type\"]=\"string\"}},[\"bindings\"]={},[\"callName\"]=\"addon.Platform:GetUnitFlagObservation\",[\"code\"]=\"\\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\\010    if not self:CanReadValue(unit) or not self:CanReadValue(kind) then return nil,'restricted-value' end\\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\\010    if kind~='combat' and kind~='enemy' and kind~='pvp' then return nil,'invalid-unit-flag-query' end\\010    if type(UnitExists)~='function' then return nil,'missing-api' end\\010    local existsOk,exists=pcall(UnitExists,unit)\\010    if not existsOk then return nil,'api-error' end\\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\\010    if exists==nil then return nil,'unit-data-unavailable' end\\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\\010    if not exists then return false end\\010    local api\\010    if kind=='combat' then api=UnitAffectingCombat\\010    elseif kind=='enemy' then api=UnitIsEnemy\\010    else api=UnitIsPVP end\\010    if type(api)~='function' then return nil,'missing-api' end\\010    local ok,result\\010    if kind=='enemy' then ok,result=pcall(api,'player',unit)\\010    else ok,result=pcall(api,unit) end\\010    if not ok then return nil,'api-error' end\\010    if not self:CanReadValue(result) then return nil,'restricted-value' end\\010    if result==nil then return nil,'unit-flag-unavailable' end\\010    if type(result)~='boolean' then return nil,'invalid-api-result' end\\010    return result\\010\",[\"description\"]=\"Observe one current unit flag: combat uses UnitAffectingCombat, enemy uses UnitIsEnemy with player as the first unit, and pvp uses UnitIsPVP. A readable absent unit returns false without querying the flag. Required missing, failed, restricted or malformed observations return nil with a reason. This preserves the exact selected unit and does not infer friendliness, attackability or other unit states.\",[\"kind\"]=\"function\",[\"line\"]=6,[\"parameters\"]={\"self\",\"unit\",\"kind\"},[\"returns\"]={{[\"description\"]=\"Readable selected flag, false for a known absent unit, or nil when a required observation is unavailable.\",[\"type\"]=\"boolean | nil\"},{[\"description\"]=\"Policy, query-validation or availability reason for a nil unit flag.\",[\"type\"]=\"string | nil\"}}}},[\"hash\"]=\"ff7421385edf6d8b85a0420e9b3c13fc61f83916736dfbb53dcc4c8ff19a8fad\"},[\"Platform/unit_health.lua\"]={[\"bindings\"]={[\"Platform_GetUnitHealthObservation\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Unit token whose current health should be observed.\",[\"name\"]=\"unit\",[\"type\"]=\"string\"},{[\"description\"]=\"True also observes maximum health; false or nil reads current health only.\",[\"name\"]=\"includeMaximum\",[\"type\"]=\"boolean | nil\"}},[\"bindings\"]={[\"finite\"]=\"builtin:Platform/unit_health.lua:finite\"},[\"callName\"]=\"addon.Platform:GetUnitHealthObservation\",[\"code\"]=\"\\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\\010    if not self:CanReadValue(unit) or not self:CanReadValue(includeMaximum) then return nil,'restricted-value' end\\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\\010    if includeMaximum~=nil and type(includeMaximum)~='boolean' then return nil,'invalid-health-query' end\\010    if type(UnitExists)~='function' then return nil,'missing-api' end\\010    local existsOk,exists=pcall(UnitExists,unit)\\010    if not existsOk then return nil,'api-error' end\\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\\010    if exists==nil then return nil,'unit-data-unavailable' end\\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\\010    if not exists then return {exists=false} end\\010    if type(UnitHealth)~='function' then return nil,'missing-api' end\\010    local currentOk,current=pcall(UnitHealth,unit)\\010    if not currentOk then return nil,'api-error' end\\010    if not self:CanReadValue(current) then return nil,'restricted-value' end\\010    -- Keep the native proof visible at the arithmetic boundary; the platform\\010    -- guard above also covers older clients and the issecretvalue predicate.\\010    if canaccessvalue and not canaccessvalue(current) then return nil,'restricted-value' end\\010    if current==nil then return nil,'health-data-unavailable' end\\010    if not finite(current) or current<0 then return nil,'invalid-api-result' end\\010    local record={exists=true,current=current}\\010    if includeMaximum then\\010        if type(UnitHealthMax)~='function' then return nil,'missing-api' end\\010        local maximumOk,maximum=pcall(UnitHealthMax,unit)\\010        if not maximumOk then return nil,'api-error' end\\010        if not self:CanReadValue(maximum) then return nil,'restricted-value' end\\010        if canaccessvalue and not canaccessvalue(maximum) then return nil,'restricted-value' end\\010        if maximum==nil then return nil,'health-data-unavailable' end\\010        if not finite(maximum) or maximum<0 then return nil,'invalid-api-result' end\\010        record.maximum=maximum\\010    end\\010    return record\\010\",[\"description\"]=\"Observe readable current health and optionally maximum health on supported clients. A readable absent unit returns exists=false. Missing, failed, restricted or malformed observations return nil with a reason; they do not establish an absent unit or a health value.\",[\"kind\"]=\"function\",[\"line\"]=10,[\"parameters\"]={\"self\",\"unit\",\"includeMaximum\"},[\"returns\"]={{[\"description\"]=\"Fresh readable record with exists and, when present, current health. Maximum health is included only when requested.\",[\"type\"]=\"table | nil\"},{[\"description\"]=\"Policy, validation or availability reason for a nil health observation.\",[\"type\"]=\"string | nil\"}}},[\"finite\"]={[\"bindings\"]={},[\"code\"]=\"\\010    return type(value)=='number' and value==value and value<math.huge and value>-math.huge\\010\",[\"kind\"]=\"function\",[\"line\"]=4,[\"parameters\"]={\"value\"}}},[\"hash\"]=\"dc2ecdf6855609a696d449494ee131246edf21fc63d4cfcbb73938602c5e15a9\"},[\"Platform/unit_identity.lua\"]={[\"bindings\"]={[\"Platform_GetUnitIdentityObservation\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"First exact unit token, checked for existence before comparison.\",[\"name\"]=\"unit\",[\"type\"]=\"string\"},{[\"description\"]=\"Second exact unit token, passed unchanged to UnitIsUnit.\",[\"name\"]=\"otherunit\",[\"type\"]=\"string\"}},[\"bindings\"]={},[\"callName\"]=\"addon.Platform:GetUnitIdentityObservation\",[\"code\"]=\"\\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\\010    if not self:CanReadValue(unit) or not self:CanReadValue(otherunit) then return nil,'restricted-value' end\\010    if type(unit)~='string' or unit=='' or type(otherunit)~='string' or otherunit=='' then return nil,'invalid-unit' end\\010    if type(UnitExists)~='function' then return nil,'missing-api' end\\010    local existsOk,exists=pcall(UnitExists,unit)\\010    if not existsOk then return nil,'api-error' end\\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\\010    if exists==nil then return nil,'unit-data-unavailable' end\\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\\010    if not exists then return false end\\010    if type(UnitIsUnit)~='function' then return nil,'missing-api' end\\010    local ok,same=pcall(UnitIsUnit,unit,otherunit)\\010    if not ok then return nil,'api-error' end\\010    if not self:CanReadValue(same) then return nil,'restricted-value' end\\010    if same==nil then return nil,'unit-identity-unavailable' end\\010    if type(same)~='boolean' then return nil,'invalid-api-result' end\\010    return same\\010\",[\"description\"]=\"Compare two exact unit tokens using UnitIsUnit after checking only the first token with UnitExists. A readable absent first unit returns false without comparing. Required missing, failed, restricted or malformed observations return nil with a reason. No second existence query, GUID lookup or inferred identity is added.\",[\"kind\"]=\"function\",[\"line\"]=6,[\"parameters\"]={\"self\",\"unit\",\"otherunit\"},[\"returns\"]={{[\"description\"]=\"Readable unit equality, false for a known absent first unit, or nil when required observations are unavailable.\",[\"type\"]=\"boolean | nil\"},{[\"description\"]=\"Policy, token-validation or availability reason for a nil identity result.\",[\"type\"]=\"string | nil\"}}}},[\"hash\"]=\"94517efae16237ad538d925dc071fdad0c68e454b372c31c810df639ddf09638\"},[\"Platform/unit_level.lua\"]={[\"bindings\"]={[\"Platform_GetUnitLevelObservation\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Unit token whose raw level should be observed.\",[\"name\"]=\"unit\",[\"type\"]=\"string\"}},[\"bindings\"]={[\"finite\"]=\"builtin:Platform/unit_level.lua:finite\"},[\"callName\"]=\"addon.Platform:GetUnitLevelObservation\",[\"code\"]=\"\\010    if not self:CanReadValue(unit) then return nil,'restricted-value' end\\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\\010    if self:GetClientInfo().family=='unknown' then return nil,'unsupported-client' end\\010    if type(UnitExists)~='function' then return nil,'missing-api' end\\010    local existsOk,exists=pcall(UnitExists,unit)\\010    if not existsOk then return nil,'api-error' end\\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\\010    if exists==nil then return nil,'unit-data-unavailable' end\\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\\010    if not exists then return {exists=false} end\\010    if type(UnitLevel)~='function' then return nil,'missing-api' end\\010    local levelOk,level=pcall(UnitLevel,unit)\\010    if not levelOk then return nil,'api-error' end\\010    if not self:CanReadValue(level) then return nil,'restricted-value' end\\010    if canaccessvalue and not canaccessvalue(level) then return nil,'restricted-value' end\\010    if level==nil then return nil,'level-data-unavailable' end\\010    if not finite(level) then return nil,'invalid-api-result' end\\010    if level<0 then return nil,'level-data-unavailable' end\\010    if level==0 or level%1~=0 then return nil,'invalid-api-result' end\\010    return {exists=true,level=level}\\010\",[\"description\"]=\"Observe a readable raw unit level on known clients. A readable absent unit returns exists=false; present units require a positive finite integer UnitLevel. Unknown boss levels, missing, failed, restricted or malformed observations return nil with a reason. This does not use effective or scaled levels.\",[\"kind\"]=\"function\",[\"line\"]=10,[\"parameters\"]={\"self\",\"unit\"},[\"returns\"]={{[\"description\"]=\"Fresh readable record with exists and, when present, a positive integer level.\",[\"type\"]=\"table | nil\"},{[\"description\"]=\"Availability or query-validation reason for a nil level observation.\",[\"type\"]=\"string | nil\"}}},[\"finite\"]={[\"bindings\"]={},[\"code\"]=\"\\010    return type(value)=='number' and value==value and value<math.huge and value>-math.huge\\010\",[\"kind\"]=\"function\",[\"line\"]=4,[\"parameters\"]={\"value\"}}},[\"hash\"]=\"b7392d1093d672499ba0f5e57afb48e4e01121699c97476e6d0e2cb2d0114c27\"},[\"Platform/unit_metadata.lua\"]={[\"bindings\"]={[\"Platform_GetUnitMetadataObservation\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Exact unit token checked for existence and passed to the selected metadata API.\",[\"name\"]=\"unit\",[\"type\"]=\"string\"},{[\"description\"]=\"One of class, creature or classification; other metadata kinds are unsupported.\",[\"name\"]=\"kind\",[\"type\"]=\"string\"}},[\"bindings\"]={},[\"callName\"]=\"addon.Platform:GetUnitMetadataObservation\",[\"code\"]=\"\\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\\010    if not self:CanReadValue(unit) or not self:CanReadValue(kind) then return nil,'restricted-value' end\\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\\010    if kind~='class' and kind~='creature' and kind~='classification' then return nil,'invalid-unit-metadata-query' end\\010    if type(UnitExists)~='function' then return nil,'missing-api' end\\010    local existsOk,exists=pcall(UnitExists,unit)\\010    if not existsOk then return nil,'api-error' end\\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\\010    if exists==nil then return nil,'unit-data-unavailable' end\\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\\010    if not exists then return false end\\010    local api\\010    if kind=='class' then api=UnitClass\\010    elseif kind=='creature' then api=UnitCreatureType\\010    else api=UnitClassification end\\010    if type(api)~='function' then return nil,'missing-api' end\\010    local ok,observed\\010    if kind=='class' then ok,observed=pcall(function() return select(2,api(unit)) end)\\010    else ok,observed=pcall(api,unit) end\\010    if not ok then return nil,'api-error' end\\010    if not self:CanReadValue(observed) then return nil,'restricted-value' end\\010    if observed==nil then return nil,'unit-metadata-unavailable' end\\010    if type(observed)~='string' or observed=='' then return nil,'invalid-api-result' end\\010    return observed\\010\",[\"description\"]=\"Observe one consumed native unit metadata field after checking UnitExists: class uses UnitClass return two, creature uses the localized UnitCreatureType name, and classification uses UnitClassification. A readable absent unit returns false without querying metadata. Unused tuple fields do not affect availability; a required missing, failed, nil, restricted or malformed value returns nil with a reason. No player class, GUID, enum or translation inference is added.\",[\"kind\"]=\"function\",[\"line\"]=6,[\"parameters\"]={\"self\",\"unit\",\"kind\"},[\"returns\"]={{[\"description\"]=\"Readable consumed metadata string, false for a known absent unit, or nil when required data is unavailable.\",[\"type\"]=\"string | boolean | nil\"},{[\"description\"]=\"Policy, query-validation or availability reason for a nil metadata observation.\",[\"type\"]=\"string | nil\"}}}},[\"hash\"]=\"81dc74908aabee0b2b376a611a7bc7215db3eaa635212d87c42969187393e7a1\"},[\"Platform/unit_power.lua\"]={[\"bindings\"]={[\"Platform_GetUnitPowerObservation\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Exact unit token whose resource should be observed; this does not redirect player or vehicle units.\",[\"name\"]=\"unit\",[\"type\"]=\"string\"},{[\"description\"]=\"mana selects the explicit live Mana enum; current reads and forwards the actual UnitPowerType identity, including Mana zero.\",[\"name\"]=\"resource\",[\"type\"]=\"string\"},{[\"description\"]=\"True also observes the selected resource maximum; false or nil reads current quantity only.\",[\"name\"]=\"includeMaximum\",[\"type\"]=\"boolean | nil\"}},[\"bindings\"]={[\"finite\"]=\"builtin:Platform/unit_power.lua:finite\"},[\"callName\"]=\"addon.Platform:GetUnitPowerObservation\",[\"code\"]=\"\\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\\010    if not self:CanReadValue(unit) or not self:CanReadValue(resource) or not self:CanReadValue(includeMaximum) then return nil,'restricted-value' end\\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\\010    if resource~='mana' and resource~='current' then return nil,'invalid-power-query' end\\010    if includeMaximum~=nil and type(includeMaximum)~='boolean' then return nil,'invalid-power-query' end\\010    if type(UnitExists)~='function' then return nil,'missing-api' end\\010    local existsOk,exists=pcall(UnitExists,unit)\\010    if not existsOk then return nil,'api-error' end\\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\\010    if exists==nil then return nil,'unit-data-unavailable' end\\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\\010    if not exists then return {exists=false} end\\010    if not self:CanReadValue(Enum) then return nil,'restricted-value' end\\010    if type(Enum)~='table' then return nil,'power-type-unavailable' end\\010    local types=Enum.PowerType\\010    if not self:CanReadValue(types) then return nil,'restricted-value' end\\010    if type(types)~='table' then return nil,'power-type-unavailable' end\\010    local powerType\\010    if resource=='mana' then\\010        powerType=types.Mana\\010    else\\010        if type(UnitPowerType)~='function' then return nil,'missing-api' end\\010        local ok\\010        ok,powerType=pcall(UnitPowerType,unit)\\010        if not ok then return nil,'api-error' end\\010    end\\010    if not self:CanReadValue(powerType) then return nil,'restricted-value' end\\010    if canaccessvalue and not canaccessvalue(powerType) then return nil,'restricted-value' end\\010    if powerType==nil then return nil,'power-type-unavailable' end\\010    if not finite(powerType) or powerType<0 or powerType%1~=0 then return nil,'invalid-api-result' end\\010    local known=false\\010    for _,id in pairs(types) do\\010        if self:CanReadValue(id) and type(id)=='number' and id==powerType then known=true;break end\\010    end\\010    if not known then return nil,'power-type-unavailable' end\\010    if type(UnitPower)~='function' then return nil,'missing-api' end\\010    local currentOk,current=pcall(UnitPower,unit,powerType)\\010    if not currentOk then return nil,'api-error' end\\010    if not self:CanReadValue(current) then return nil,'restricted-value' end\\010    if canaccessvalue and not canaccessvalue(current) then return nil,'restricted-value' end\\010    if current==nil then return nil,'power-data-unavailable' end\\010    if not finite(current) or resource=='mana' and current<0 then return nil,'invalid-api-result' end\\010    local record={exists=true,powerType=powerType,current=current}\\010    if includeMaximum then\\010        if type(UnitPowerMax)~='function' then return nil,'missing-api' end\\010        local maximumOk,maximum=pcall(UnitPowerMax,unit,powerType)\\010        if not maximumOk then return nil,'api-error' end\\010        if not self:CanReadValue(maximum) then return nil,'restricted-value' end\\010        if canaccessvalue and not canaccessvalue(maximum) then return nil,'restricted-value' end\\010        if maximum==nil then return nil,'power-data-unavailable' end\\010        if not finite(maximum) or maximum<0 then return nil,'invalid-api-result' end\\010        record.maximum=maximum\\010    end\\010    return record\\010\",[\"description\"]=\"Observe explicit mana or the current raw power resource on supported readable clients. Select resource identities from the live PowerType enum; explicit mana never falls back to the current bar. Known absence returns exists=false; missing, failed, restricted or malformed observations return nil with a reason. Current-mode quantities preserve signed native resources; explicit mana is nonnegative. Request maximum only when needed; percentage consumers must require a positive maximum.\",[\"kind\"]=\"function\",[\"line\"]=10,[\"parameters\"]={\"self\",\"unit\",\"resource\",\"includeMaximum\"},[\"returns\"]={{[\"description\"]=\"Fresh readable record with exists and, when present, powerType and finite current quantity. Requested maximum is finite and nonnegative. Quantities may be fractional; current-mode current may be signed.\",[\"type\"]=\"table | nil\"},{[\"description\"]=\"Policy, query-validation or availability reason for a nil resource observation.\",[\"type\"]=\"string | nil\"}}},[\"finite\"]={[\"bindings\"]={},[\"code\"]=\"\\010    return type(value)=='number' and value==value and value<math.huge and value>-math.huge\\010\",[\"kind\"]=\"function\",[\"line\"]=4,[\"parameters\"]={\"value\"}}},[\"hash\"]=\"76e7ed6f2f02b6f4d97a687c16289b5f952c18fcf016d357f3a106c2dd5702d2\"},[\"Platform/unit_presence.lua\"]={[\"bindings\"]={[\"Platform_GetUnitPresenceObservation\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Readable nonempty unit token, passed unchanged as the single native argument.\",[\"name\"]=\"unit\",[\"type\"]=\"string\"}},[\"bindings\"]={},[\"callName\"]=\"addon.Platform:GetUnitPresenceObservation\",[\"code\"]=\"\\010    if not self:CanReadValue(unit) then return nil,'restricted-value' end\\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\\010    if self:GetClientInfo().family=='unknown' then return nil,'unsupported-client' end\\010    if type(UnitExists)~='function' then return nil,'missing-api' end\\010    local ok,exists=pcall(UnitExists,unit)\\010    if not ok then return nil,'api-error' end\\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\\010    if exists==nil then return nil,'unit-data-unavailable' end\\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\\010    return exists\\010\",[\"description\"]=\"Observe unit presence on identified client families. Pass the selected unit unchanged to one protected UnitExists call. Preserve readable true and false; missing, failed, restricted, nil or malformed required observations return nil with a reason. No identity, visibility, range or combat-state query is added.\",[\"kind\"]=\"function\",[\"line\"]=6,[\"parameters\"]={\"self\",\"unit\"},[\"returns\"]={{[\"description\"]=\"Known unit presence or absence; nil when the required observation is unavailable.\",[\"type\"]=\"boolean | nil\"},{[\"description\"]=\"Client-family, query-validation or required-observation availability reason for a nil result.\",[\"type\"]=\"string | nil\"}}}},[\"hash\"]=\"8ef29e263e8eada22df73d361a06e7822bdbc60084493811c6aaedb6cfa72ceb\"},[\"Platform/unit_stat.lua\"]={[\"bindings\"]={[\"Platform_GetUnitStatObservation\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"},{[\"description\"]=\"Selected nonempty unit token, unchanged in native calls.\",[\"name\"]=\"unit\",[\"type\"]=\"string\"},{[\"description\"]=\"Integral RM statistic selector 1..5, or 6 for effective armor.\",[\"name\"]=\"stat\",[\"type\"]=\"number\"}},[\"bindings\"]={[\"finite\"]=\"builtin:Platform/unit_stat.lua:finite\"},[\"callName\"]=\"addon.Platform:GetUnitStatObservation\",[\"code\"]=\"\\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\\010    if not self:CanReadValue(unit) or not self:CanReadValue(stat) then return nil,'restricted-value' end\\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\\010    if not finite(stat) or stat%1~=0 or stat<1 or stat>6 then return nil,'invalid-stat-query' end\\010    if type(UnitExists)~='function' then return nil,'missing-api' end\\010    local existsOk,exists=pcall(UnitExists,unit)\\010    if not existsOk then return nil,'api-error' end\\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\\010    if exists==nil then return nil,'unit-data-unavailable' end\\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\\010    if not exists then return {exists=false} end\\010    local fn\\010    if stat==6 then fn=UnitArmor else fn=UnitStat end\\010    if type(fn)~='function' then return nil,'missing-api' end\\010    local ok,_,effective\\010    if stat==6 then ok,_,effective=pcall(fn,unit)\\010    else ok,_,effective=pcall(fn,unit,stat) end\\010    if not ok then return nil,'api-error' end\\010    if not self:CanReadValue(effective) then return nil,'restricted-value' end\\010    if canaccessvalue and not canaccessvalue(effective) then return nil,'restricted-value' end\\010    if effective==nil then return nil,'stat-data-unavailable' end\\010    if not finite(effective) then return nil,'invalid-api-result' end\\010    return {exists=true,value=effective}\\010\",[\"description\"]=\"Observe the effective statistic from native return two only. On probe-policy clients query exact UnitExists(unit), then UnitStat(unit,stat) for selector 1..5 or UnitArmor(unit) for selector 6. Known absence returns exists=false; missing, failed, restricted or nonfinite required facts return nil. Preserve finite signed, fractional and zero values; ignore all unused tuple fields. The 1..6 route is an RM selector policy, not a native value-domain limit.\",[\"kind\"]=\"function\",[\"line\"]=9,[\"parameters\"]={\"self\",\"unit\",\"stat\"},[\"returns\"]={{[\"description\"]=\"Record with exists=false, or exists=true and finite value; nil when unavailable.\",[\"type\"]=\"table | nil\"},{[\"description\"]=\"Query, policy or observation availability reason.\",[\"type\"]=\"string | nil\"}}},[\"finite\"]={[\"bindings\"]={},[\"code\"]=\"\\010    return type(value)=='number' and value==value and value~=math.huge and value~=-math.huge\\010\",[\"kind\"]=\"function\",[\"line\"]=3,[\"parameters\"]={\"value\"}}},[\"hash\"]=\"08e26273a325e377ec87ec6687c90ae7ebb1a70c34d001ac7c1f0379e063e63e\"},[\"Platform/zone_pvp.lua\"]={[\"bindings\"]={[\"Platform_GetZonePVPObservation\"]={[\"args\"]={{[\"description\"]=\"Rotation Master platform adapter (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMPlatform\"}},[\"bindings\"]={},[\"callName\"]=\"addon.Platform:GetZonePVPObservation\",[\"code\"]=\"\\010    local family=self:GetClientInfo().family\\010    if family~='retail' and family~='forever' and family~='era' and family~='tbc' and family~='progression' then return nil,'unsupported-policy' end\\010    local namespace=C_PvP\\010    if not self:CanReadValue(namespace) then return nil,'restricted-value' end\\010    if canaccessvalue and not canaccessvalue(namespace) then return nil,'restricted-value' end\\010    local api\\010    if type(namespace)=='table' then api=namespace.GetZonePVPInfo end\\010    if not self:CanReadValue(api) then return nil,'restricted-value' end\\010    if canaccessvalue and not canaccessvalue(api) then return nil,'restricted-value' end\\010    if type(api)~='function' then\\010        api=GetZonePVPInfo\\010        if not self:CanReadValue(api) then return nil,'restricted-value' end\\010        if canaccessvalue and not canaccessvalue(api) then return nil,'restricted-value' end\\010        if type(api)~='function' then return nil,'missing-api' end\\010    end\\010    local ok,pvpType=pcall(api)\\010    if not ok then return nil,'api-error' end\\010    if not self:CanReadValue(pvpType) then return nil,'restricted-value' end\\010    if canaccessvalue and not canaccessvalue(pvpType) then return nil,'restricted-value' end\\010    if pvpType==nil then return {} end\\010    if type(pvpType)~='string' then return nil,'invalid-api-result' end\\010    return {pvpType=pvpType}\\010\",[\"description\"]=\"Observe the first zone PvP classification result with one protected zero-argument dot call. Prefer callable C_PvP.GetZonePVPInfo and use the global helper only when the modern callable is absent. A successful nil or no returned values produces a known empty record; missing, failed, restricted or malformed observations remain unavailable. Readable empty and future strings retain their exact meaning, and unused return fields do not determine availability. Never switch backends after a modern result or failure.\",[\"kind\"]=\"function\",[\"line\"]=5,[\"parameters\"]={\"self\"},[\"returns\"]={{[\"description\"]=\"Successful observation record with pvpType string or nil; nil record means unavailable.\",[\"type\"]=\"table | nil\"},{[\"description\"]=\"Client-policy, capability, call or observation availability reason for a nil record.\",[\"type\"]=\"string | nil\"}}}},[\"hash\"]=\"cced093dcb695fa72e450bdb31a9ca0ef884167b1b59b98a2577eb50a65114e0\"},[\"UI/checkbox.lua\"]={[\"bindings\"]={[\"CreateConditionCheckBox\"]={[\"args\"]={{[\"description\"]=\"Rotation Master addon instance (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMAddon\"}},[\"bindings\"]={[\"constructor\"]=\"builtin:UI/checkbox.lua:constructor\"},[\"callName\"]=\"addon:CreateConditionCheckBox\",[\"code\"]=\"\\010    local widget=addon:AcquireConditionWidget('RM-CheckBox',constructor)\\010    ---@cast widget RMConditionCheckBox\\010    return widget\\010\",[\"description\"]=\"Create a native boolean condition control. Configure SetLabel, SetValue, SetDisabled and OnValueChanged; add it with parent:AddChild(widget).\",[\"kind\"]=\"function\",[\"line\"]=28,[\"parameters\"]={\"self\"},[\"returns\"]={{[\"description\"]=\"Checkbox widget with boolean value and callback methods.\",[\"type\"]=\"RMConditionCheckBox\"}}},[\"constructor\"]={[\"bindings\"]={},[\"code\"]=\"\\010    local w={type='RM-CheckBox',alive=false,disabled=false}\\010    local frame=CreateFrame('Frame',nil,UIParent);w.frame=frame;frame:SetSize(180,24)\\010    local button=addon:CreateWorkbenchCheckBox(frame,'',180);w.button=button;button:SetAllPoints(frame)\\010    function w:OnAcquire() self.alive=true;self:SetLabel('');self:SetValue(false);self:SetDisabled(false);self:SetWidth(180);self:SetHeight(24) end\\010    function w:OnRelease() self.alive=false;self:SetValue(false) end\\010    function w:SetLabel(text) button:SetText(text or '') end\\010    function w:SetValue(value) button:SetChecked(value==true) end\\010    function w:GetValue() return button:GetChecked() end\\010    function w:SetDisabled(value) self.disabled=value==true;if self.disabled then button:Disable();button:SetAlpha(.45) else button:Enable();button:SetAlpha(1) end end\\010    function w:OnWidthSet(width) button:GetFontString():SetWidth(math.max(1,width-22)) end\\010    addon:SetUIScript(button,'OnClick',function()\\010        if not w.alive or w.disabled then return end\\010        w:SetValue(not w:GetValue());w:Fire('OnValueChanged',w:GetValue())\\010    end)\\010    ---@cast w RMConditionWidget\\010    return addon:RegisterConditionWidget(w)\\010\",[\"kind\"]=\"function\",[\"line\"]=9,[\"parameters\"]={}}},[\"hash\"]=\"fbc3bbaa9d668b676860ba5a20564e5fda12f586045611e8794a3e0ae3abeba4\"},[\"UI/condition_display.lua\"]={[\"bindings\"]={[\"CreateConditionButton\"]={[\"args\"]={{[\"description\"]=\"Rotation Master addon instance (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMAddon\"}},[\"bindings\"]={[\"buttonConstructor\"]=\"builtin:UI/condition_display.lua:buttonConstructor\"},[\"callName\"]=\"addon:CreateConditionButton\",[\"code\"]=\" return self:AcquireConditionWidget('RM-ConditionButton',buttonConstructor) \",[\"description\"]=\"Create a native button using the shared condition widget lifecycle and workbench theme. SetText, SetDisabled and SetCallback configure its label and interaction; OnClick receives the mouse button. Add it to the supplied parent.\",[\"kind\"]=\"function\",[\"line\"]=120,[\"parameters\"]={\"self\"},[\"returns\"]={{[\"description\"]=\"Native button with label, disabled state and lease-protected callbacks.\",[\"type\"]=\"RMConditionButton\"}}},[\"CreateConditionLabel\"]={[\"args\"]={{[\"description\"]=\"Rotation Master addon instance (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMAddon\"}},[\"bindings\"]={[\"labelConstructor\"]=\"builtin:UI/condition_display.lua:labelConstructor\"},[\"callName\"]=\"addon:CreateConditionLabel\",[\"code\"]=\" return self:AcquireConditionWidget('RM-ConditionLabel',labelConstructor) \",[\"description\"]=\"Create native wrapping text that measures its height from its width and font. SetText, SetFont or SetFontObject configure its contents. Add it to the supplied parent so layout can track its measured height.\",[\"kind\"]=\"function\",[\"line\"]=118,[\"parameters\"]={\"self\"},[\"returns\"]={{[\"description\"]=\"Native wrapping text control with font, color and alignment methods.\",[\"type\"]=\"RMConditionLabel\"}}},[\"CreateConditionLink\"]={[\"args\"]={{[\"description\"]=\"Rotation Master addon instance (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMAddon\"}},[\"bindings\"]={[\"labelConstructor\"]=\"builtin:UI/condition_display.lua:labelConstructor\"},[\"callName\"]=\"addon:CreateConditionLink\",[\"code\"]=\" return self:AcquireConditionWidget('RM-ConditionLink',function() return labelConstructor(true) end) \",[\"description\"]=\"Create native wrapping text with optional leading image and pointer callbacks. SetImage and SetImageSize configure the image; OnEnter, OnLeave and OnClick use the condition callback contract. Add it to the supplied parent; callbacks expire when its lease is released.\",[\"kind\"]=\"function\",[\"line\"]=128,[\"parameters\"]={\"self\"},[\"returns\"]={{[\"description\"]=\"Native interactive text and image control with measured height and disabled state.\",[\"type\"]=\"RMConditionLink\"}}},[\"buttonConstructor\"]={[\"bindings\"]={[\"defaultFont\"]=\"builtin:UI/condition_display.lua:defaultFont\"},[\"code\"]=\"\\010    local w={type='RM-ConditionButton',text='',disabled=false,autoWidth=false}\\010    local frame=addon:CreateWorkbenchButton(UIParent,'',200);w.frame=frame\\010    local label=frame:GetFontString();w.label=label;label:SetWordWrap(false)\\010    local enter,leave=frame:GetScript('OnEnter'),frame:GetScript('OnLeave')\\010    function w:OnWidthSet(width) label:SetWidth(math.max(1,width-12)) end\\010    function w:SetText(text)\\010        self.text=text==nil and '' or tostring(text);frame:SetText(self.text);label:SetText(self.text)\\010        if self.autoWidth then self:SetWidth(label:GetStringWidth()+30) end\\010    end\\010    function w:SetAutoWidth(value)\\010        self.autoWidth=value==true\\010        if self.autoWidth then self:SetWidth(label:GetStringWidth()+30) end\\010    end\\010    function w:SetDisabled(value) self.disabled=value==true;if self.disabled then frame:Disable() else frame:Enable() end end\\010    function w:OnAcquire()\\010        self:SetAutoWidth(false);self:SetWidth(200);self:SetHeight(24);self:SetDisabled(false);self:SetText('')\\010        label:SetFontObject(defaultFont());frame:SetSelected(false);frame.tooltip=nil;frame:RegisterForClicks('LeftButtonUp')\\010        local lease=self.rmLease\\010        local function live() return w.rmActive and w.rmLease==lease and not w:IsReleasing() end\\010        addon:SetUIScript(frame,'OnClick',function(_,button) if live() and not w.disabled then w:Fire('OnClick',button) end end)\\010        addon:SetUIScript(frame,'OnEnter',function() if live() then if enter then enter(frame) end;w:Fire('OnEnter') end end)\\010        addon:SetUIScript(frame,'OnLeave',function() if live() then if leave then leave(frame) end;w:Fire('OnLeave') end end)\\010    end\\010    function w:OnRelease()\\010        if GameTooltip and GameTooltip:IsOwned(frame) then GameTooltip:Hide() end\\010        self.text='';frame:SetText('');label:SetText('');frame.tooltip=nil\\010    end\\010    return addon:RegisterConditionWidget(w)\\010\",[\"kind\"]=\"function\",[\"line\"]=86,[\"parameters\"]={}},[\"defaultFont\"]={[\"bindings\"]={},[\"code\"]=\" return GameFontHighlightSmall or 'GameFontHighlightSmall' \",[\"kind\"]=\"function\",[\"line\"]=2,[\"parameters\"]={}},[\"labelConstructor\"]={[\"bindings\"]={[\"defaultFont\"]=\"builtin:UI/condition_display.lua:defaultFont\"},[\"code\"]=\"\\010    local w={type=interactive and 'RM-ConditionLink' or 'RM-ConditionLabel',text=''}\\010    local frame=CreateFrame(interactive and 'Button' or 'Frame',nil,UIParent);w.frame=frame\\010    local image=interactive and frame:CreateTexture(nil,'ARTWORK');w.image=image\\010    local label=frame:CreateFontString(nil,'OVERLAY','GameFontHighlightSmall');w.label=label\\010    label:SetPoint('TOPLEFT');label:SetWordWrap(true);label:SetHeight(0)\\010    local function layoutText()\\010        local inset=image and w.imagePath and (w.imageWidth+4) or 0\\010        label:SetWidth(math.max(1,frame:GetWidth()-inset))\\010        local textHeight=math.max(1,label:GetStringHeight() or 0)\\010        local height=math.max(textHeight,image and w.imagePath and w.imageHeight or 0)\\010        label:ClearAllPoints();label:SetPoint('TOPLEFT',frame,'TOPLEFT',inset,-(height-textHeight)/2)\\010        if image then image:ClearAllPoints();image:SetPoint('TOPLEFT',frame,'TOPLEFT',0,-(height-w.imageHeight)/2) end\\010        -- Backing frame dimensions may be quantized. Compare text requests,\\010        -- not engine rounding, before notifying the parent layout.\\010        local changed=height~=w.measuredHeight\\010        w.measuredHeight=height;w:SetHeight(height)\\010        return changed\\010    end\\010    local function measure()\\010        if w.measuring then return end\\010        w.measuring=true\\010        local ok,changed=pcall(layoutText)\\010        w.measuring=false\\010        if not ok then error(changed,0) end\\010        if changed and w.parent and w.parent.DoLayout then w.parent:DoLayout() end\\010    end\\010    function w:OnWidthSet() measure() end\\010    function w:SetText(text) self.text=text==nil and '' or tostring(text);label:SetText(self.text);measure() end\\010    function w:SetFont(path,height,flags) label:SetFont(path,height,flags);measure() end\\010    function w:SetFontObject(font) label:SetFontObject(font or defaultFont());measure() end\\010    function w:SetColor(red,green,blue,alpha)\\010        if red==nil or green==nil or blue==nil then red,green,blue=1,1,1 end\\010        label:SetTextColor(red,green,blue,alpha or 1)\\010    end\\010    function w:SetJustifyH(value) label:SetJustifyH(value) end\\010    function w:SetJustifyV(value) label:SetJustifyV(value) end\\010    if interactive then\\010        function w:SetImage(path,...)\\010            self.imagePath=path;image:SetTexture(path)\\010            local count=select('#',...);if count==4 or count==8 then image:SetTexCoord(...) else image:SetTexCoord(0,1,0,1) end\\010            if path then image:Show() else image:Hide() end;measure()\\010        end\\010        function w:SetImageSize(width,height) self.imageWidth,self.imageHeight=width,height;image:SetSize(width,height);measure() end\\010        function w:SetDisabled(value) self.disabled=value==true;if self.disabled then frame:Disable() else frame:Enable() end end\\010    end\\010    function w:OnAcquire()\\010        self.measuring=false;self.measuredHeight=nil\\010        if interactive then self.imagePath=nil;self.imageWidth,self.imageHeight=24,24;image:SetTexture(nil);image:SetSize(24,24);image:Hide();self:SetDisabled(false) end\\010        self:SetText('');self:SetFontObject();self:SetColor();self:SetJustifyH('LEFT');self:SetJustifyV('TOP');self:SetWidth(200)\\010        if interactive then\\010            frame:RegisterForClicks('LeftButtonUp','RightButtonUp');local lease=self.rmLease\\010            local function live() return w.rmActive and w.rmLease==lease and not w:IsReleasing() end\\010            addon:SetUIScript(frame,'OnEnter',function() if live() then w:Fire('OnEnter') end end)\\010            addon:SetUIScript(frame,'OnLeave',function() if live() then w:Fire('OnLeave') end end)\\010            addon:SetUIScript(frame,'OnClick',function(_,button) if live() and not w.disabled then w:Fire('OnClick',button) end end)\\010        end\\010    end\\010    function w:OnRelease()\\010        self.text='';self.measuring=false;self.measuredHeight=nil;label:SetText('')\\010        if image then image:Hide();image:SetTexture(nil);self.imagePath=nil;if GameTooltip and GameTooltip:IsOwned(frame) then GameTooltip:Hide() end end\\010    end\\010    return addon:RegisterConditionWidget(w)\\010\",[\"kind\"]=\"function\",[\"line\"]=13,[\"parameters\"]={\"interactive\"}}},[\"hash\"]=\"bb3555fe6a582d07c9edb618753df59e57141c1aedddaf6b085b41d823974cfa\"},[\"UI/condition_icon.lua\"]={[\"bindings\"]={[\"CreateConditionIcon\"]={[\"args\"]={{[\"description\"]=\"Rotation Master addon instance (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMAddon\"}},[\"bindings\"]={[\"constructor\"]=\"builtin:UI/condition_icon.lua:constructor\"},[\"callName\"]=\"addon:CreateConditionIcon\",[\"code\"]=\"\\010    return self:AcquireConditionWidget('RM-ConditionIcon',constructor)\\010\",[\"description\"]=\"Create a native image control using the condition widget lifecycle. SetImage and SetImageSize choose the texture; SetText optionally adds a caption. OnClick, OnEnter and OnLeave use the shared callback contract. Add the control to the supplied parent.\",[\"kind\"]=\"function\",[\"line\"]=56,[\"parameters\"]={\"self\"},[\"returns\"]={{[\"description\"]=\"Native image control with label, texture, disabled state and callbacks.\",[\"type\"]=\"RMConditionIcon\"}}},[\"constructor\"]={[\"bindings\"]={},[\"code\"]=\"\\010    local w={type='RM-ConditionIcon',alive=false,disabled=false}\\010    local frame=CreateFrame('Button',nil,UIParent);w.frame=frame;frame:EnableMouse(true)\\010    local image=frame:CreateTexture(nil,'ARTWORK');w.image=image;image:SetPoint('TOP',0,-5)\\010    local label=frame:CreateFontString(nil,'OVERLAY','GameFontHighlightSmall');w.label=label\\010    label:SetPoint('BOTTOMLEFT');label:SetPoint('BOTTOMRIGHT');label:SetJustifyH('CENTER');label:SetJustifyV('TOP');label:SetHeight(18)\\010    function w:SetLabel(text)\\010        self.labelText=text or '';label:SetText(self.labelText)\\010        if self.labelText~='' then label:Show() else label:Hide() end\\010        self:SetHeight(image:GetHeight()+(self.labelText~='' and 25 or 10))\\010    end\\010    function w:SetText(text) self:SetLabel(text) end\\010    function w:SetImage(path,...)\\010        image:SetTexture(path)\\010        local count=select('#',...)\\010        if count==4 or count==8 then image:SetTexCoord(...) else image:SetTexCoord(0,1,0,1) end\\010    end\\010    function w:SetImageByAtlas(atlas) image:SetAtlas(atlas) end\\010    function w:SetImageSize(width,height)\\010        image:SetSize(width,height);self:SetHeight(height+(self.labelText~='' and 25 or 10))\\010    end\\010    function w:SetDisabled(value)\\010        self.disabled=value==true\\010        if self.disabled then frame:Disable();image:SetVertexColor(.5,.5,.5,.5);label:SetTextColor(.5,.5,.5)\\010        else frame:Enable();image:SetVertexColor(1,1,1,1);label:SetTextColor(1,1,1) end\\010    end\\010    function w:OnAcquire()\\010        self.alive=true;self:SetWidth(110);self:SetLabel('');self:SetImage(nil);self:SetImageSize(64,64);self:SetDisabled(false)\\010        frame:RegisterForClicks('LeftButtonUp')\\010        local lease=self.rmLease\\010        local function live() return w.alive and w.rmActive and w.rmLease==lease and not w:IsReleasing() end\\010        addon:SetUIScript(frame,'OnClick',function(_,button) if live() and not w.disabled then w:Fire('OnClick',button) end end)\\010        addon:SetUIScript(frame,'OnEnter',function() if live() then w:Fire('OnEnter') end end)\\010        addon:SetUIScript(frame,'OnLeave',function() if live() then w:Fire('OnLeave') end end)\\010    end\\010    function w:OnRelease()\\010        self.alive=false\\010        if GameTooltip and GameTooltip:IsOwned(frame) then GameTooltip:Hide() end\\010        self:SetLabel('');self:SetImage(nil)\\010    end\\010    return addon:RegisterConditionWidget(w)\\010\",[\"kind\"]=\"function\",[\"line\"]=13,[\"parameters\"]={}}},[\"hash\"]=\"51d83a3289eee7c6855f3fe2141d588b7dc4727f0efd333251afd96303b0b8ec\"},[\"UI/condition_inputs.lua\"]={[\"bindings\"]={[\"CreateConditionEditBox\"]={[\"args\"]={{[\"description\"]=\"Rotation Master addon instance (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMAddon\"}},[\"bindings\"]={[\"constructor\"]=\"builtin:UI/condition_inputs.lua:constructor\"},[\"callName\"]=\"addon:CreateConditionEditBox\",[\"code\"]=\"\\010    local w=addon:AcquireConditionWidget('RM-ConditionEditBox',function() return constructor(false) end)\\010    ---@cast w RMConditionInput\\010    return w\\010\",[\"description\"]=\"Create a native text input using the condition widget contract. SetLabel, SetText, SetDisabled and SetCallback configure it; OnEnterPressed commits text. Add it to the callback parent with parent:AddChild(widget).\",[\"kind\"]=\"function\",[\"line\"]=131,[\"parameters\"]={\"self\"},[\"returns\"]={{[\"description\"]=\"Text widget supporting label, text, pending-edit and callback methods.\",[\"type\"]=\"RMConditionInput\"}}},[\"CreateConditionSlider\"]={[\"args\"]={{[\"description\"]=\"Rotation Master addon instance (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMAddon\"}},[\"bindings\"]={[\"constructor\"]=\"builtin:UI/condition_inputs.lua:constructor\"},[\"callName\"]=\"addon:CreateConditionSlider\",[\"code\"]=\"\\010    local w=addon:AcquireConditionWidget('RM-ConditionSlider',function() return constructor(true) end)\\010    ---@cast w RMConditionInput\\010    return w\\010\",[\"description\"]=\"Create a native numeric condition input with a slider and typed numeric field. Configure SetSliderValues, SetValue, SetIsPercent and SetCallback; OnValueChanged reports committed values. Add it with parent:AddChild(widget).\",[\"kind\"]=\"function\",[\"line\"]=137,[\"parameters\"]={\"self\"},[\"returns\"]={{[\"description\"]=\"Numeric widget supporting slider bounds, percent display and pending-edit validation.\",[\"type\"]=\"RMConditionInput\"}}},[\"constructor\"]={[\"bindings\"]={[\"finite\"]=\"builtin:UI/condition_inputs.lua:finite\"},[\"code\"]=\"\\010    local w={type=numeric and 'RM-ConditionSlider' or 'RM-ConditionEditBox',alive=false}\\010    local frame=CreateFrame('Frame',nil,UIParent);w.frame=frame;frame:SetSize(220,44)\\010    local caption=frame:CreateFontString(nil,'OVERLAY','GameFontHighlightSmall');w.caption=caption\\010    caption:SetPoint('TOPLEFT');caption:SetPoint('TOPRIGHT');caption:SetHeight(18);caption:SetJustifyH('LEFT')\\010    local input=addon:CreateWorkbenchEditBox(frame);w.editbox=input;input:SetMaxLetters(4096)\\010    local slider=numeric and addon:CreateWorkbenchSlider(frame,0,100,1,140) or nil;w.slider=slider\\010    local function display()\\010        local value=w.value\\010        if not numeric then return w.text or '' end\\010        if value==nil then return '' end\\010        if not finite(value) then return tostring(value) end\\010        return string.format('%.6g',value*(w.isPercent and 100 or 1))..(w.isPercent and '%' or '')\\010    end\\010    local function parse(text)\\010        text=text:match('^%s*(.-)%s*$')\\010        if w.isPercent and text:sub(-1)=='%' then text=text:sub(1,-2) end\\010        local value=tonumber(text)\\010        if not finite(value) then return end\\010        if w.isPercent then value=value/100 end\\010        if value<w.minimum or value>w.maximum then return end\\010        return value\\010    end\\010    local function paint()\\010        w.setting=true;input:SetText(display());w.confirmed=input:GetText();w.pending=false\\010        input:SetTextColor(1,1,1)\\010        if slider then slider:SetValue(finite(w.value) and w.value or w.minimum) end\\010        w.setting=false\\010    end\\010    local function pendingChanged() w:Fire('OnPendingChanged',w.pending) end\\010    function w:SetLabel(text)\\010        self.label=text or '';caption:SetText(self.label);local y=self.label~='' and -20 or 0\\010        if self.label~='' then caption:Show() else caption:Hide() end\\010        input:ClearAllPoints();input:SetPoint('TOPRIGHT',0,y);input:SetHeight(24)\\010        if slider then\\010            input:SetWidth(64);slider:ClearAllPoints();slider:SetPoint('LEFT',frame,'LEFT',0,y/2);slider:SetPoint('RIGHT',input,'LEFT',-8,0)\\010        else input:SetPoint('TOPLEFT',0,y) end\\010        self:SetHeight(self.label~='' and 44 or 24)\\010    end\\010    function w:SetText(text) self.text=text==nil and '' or tostring(text);paint() end\\010    function w:GetText() return input:GetText() end\\010    function w:SetValue(value) self.value=value;paint() end\\010    function w:GetValue() return self.value end\\010    function w:SetSliderValues(minimum,maximum,step)\\010        if not finite(minimum) or not finite(maximum) or maximum<minimum or not finite(step) or step<=0 then return end\\010        self.minimum,self.maximum,self.step=minimum,maximum,step\\010        self.setting=true;slider:SetMinMaxValues(minimum,maximum);slider:SetValueStep(step);self.setting=false;paint()\\010    end\\010    function w:SetIsPercent(value) self.isPercent=value==true;paint() end\\010    function w:IsPending() return self.alive and not self.disabled and self.pending==true end\\010    function w:CommitPending()\\010        local owner=self\\010        for _=1,128 do\\010            if not owner then break end\\010            if owner.isQueuedForRelease then return true end\\010            owner=owner.parent\\010        end\\010        if not self:IsPending() then return true end\\010        local text=input:GetText();local value=numeric and parse(text) or text\\010        if numeric and not finite(value) then input:SetTextColor(1,.35,.35);return nil end\\010        local changed=numeric and value~=self.value or not numeric and text~=self.text\\010        if numeric then self.value=value else self.text=text end\\010        paint()\\010        if changed then self:Fire(numeric and 'OnValueChanged' or 'OnEnterPressed',value) end\\010        pendingChanged();return true\\010    end\\010    function w:SetFocus() if self.alive and not self.disabled then input:SetFocus() end end\\010    function w:ClearFocus() input:ClearFocus() end\\010    function w:SetMaxLetters(value) input:SetMaxLetters(value) end\\010    function w:SetDisabled(value)\\010        self.disabled=value==true\\010        input:EnableMouse(not self.disabled);input:EnableKeyboard(not self.disabled)\\010        if slider then slider:EnableMouse(not self.disabled) end\\010        frame:SetAlpha(self.disabled and .45 or 1)\\010        if self.disabled then paint();input:ClearFocus() end\\010    end\\010    function w:OnAcquire()\\010        self.alive=true;self.minimum,self.maximum,self.step=0,100,1;self.isPercent=false;self.value=nil;self.text=''\\010        self:SetMaxLetters(4096);self:SetWidth(220);self:SetLabel('');self:SetDisabled(false)\\010        if slider then self:SetSliderValues(0,100,1) end;paint()\\010    end\\010    function w:OnRelease() self.alive=false;self.pending=false;input:ClearFocus() end\\010    addon:SetUIScript(input,'OnTextChanged',function(_,user)\\010        if w.setting or not user or not w.alive or w.disabled then return end\\010        w.pending=input:GetText()~=w.confirmed\\010        local valid=not numeric or parse(input:GetText())~=nil\\010        input:SetTextColor(1,valid and 1 or .35,valid and 1 or .35);pendingChanged()\\010    end)\\010    addon:SetUIScript(input,'OnEnterPressed',function() if w.alive and not w.disabled and w:CommitPending() then input:ClearFocus() end end)\\010    addon:SetUIScript(input,'OnEditFocusLost',function() if w.alive and not w.disabled and not w.isQueuedForRelease then w:CommitPending() end end)\\010    addon:SetUIScript(input,'OnEscapePressed',function() if w.alive then paint();input:ClearFocus();pendingChanged() end end)\\010    -- Reference popups can temporarily hide their editor. Only release\\010    -- discards pending input; ordinary hiding must retain invalid blockers too.\\010    addon:SetUIScript(frame,'OnHide',function() input:ClearFocus() end)\\010    if slider then\\010        slider:EnableMouseWheel(true)\\010        addon:SetUIScript(slider,'OnValueChanged',function(_,value)\\010            if w.setting or not w.alive or w.disabled or not finite(value) then return end\\010            value=math.max(w.minimum,math.min(w.maximum,w.minimum+math.floor((value-w.minimum)/w.step+.5)*w.step))\\010            local changed=value~=w.value;w.value=value;paint()\\010            if changed then w:Fire('OnValueChanged',value) end;pendingChanged()\\010        end)\\010        addon:SetUIScript(slider,'OnMouseWheel',function(_,direction)\\010            if w.alive and not w.disabled and direction~=0 then slider:SetValue((finite(w.value) and w.value or w.minimum)+(direction>0 and w.step or -w.step)) end\\010        end)\\010    end\\010    ---@cast w RMConditionWidget\\010    return addon:RegisterConditionWidget(w)\\010\",[\"kind\"]=\"function\",[\"line\"]=21,[\"parameters\"]={\"numeric\"}},[\"finite\"]={[\"bindings\"]={},[\"code\"]=\" return type(value)=='number' and value==value and value>-math.huge and value<math.huge \",[\"kind\"]=\"function\",[\"line\"]=2,[\"parameters\"]={\"value\"}}},[\"hash\"]=\"75864ee3bc0ce320e4146dbf07284894d411a6d0b744d6a0b8cb1e866bdec864\"},[\"UI/condition_layout.lua\"]={[\"bindings\"]={[\"CreateConditionGroup\"]={[\"args\"]={{[\"description\"]=\"Rotation Master addon instance (implicit with colon calls).\",[\"name\"]=\"self\",[\"type\"]=\"RMAddon\"}},[\"bindings\"]={[\"constructor\"]=\"builtin:UI/condition_layout.lua:constructor\"},[\"callName\"]=\"addon:CreateConditionGroup\",[\"code\"]=\"\\010    local group=addon:AcquireConditionWidget('RM-ConditionGroup',constructor)\\010    ---@cast group RMConditionGroup\\010    return group\\010\",[\"description\"]=\"Create a condition field container with RM-owned List, Table and responsive spell-field layouts. It accepts registered native condition widgets; add children with AddChild and attach the group to the callback parent.\",[\"kind\"]=\"function\",[\"line\"]=128,[\"parameters\"]={\"self\"},[\"returns\"]={{[\"description\"]=\"Condition container supporting SetLayout, AddChild, SetUserData, SetWidth and DoLayout.\",[\"type\"]=\"RMConditionGroup\"}}},[\"constructor\"]={[\"bindings\"]={[\"verticalAlignment\"]=\"builtin:UI/condition_layout.lua:verticalAlignment\"},[\"code\"]=\"\\010    local group={type='RM-ConditionGroup',children={}}\\010    local frame=CreateFrame('Frame',nil,UIParent);group.frame=frame;group.content=frame\\010    function group:OnAcquire() self.children={};self.layout='List';self.paused=false;self.layingOut=false;self:SetWidth(300);self:SetHeight(1) end\\010    function group:SetLayout(layout)\\010        if layout~='List' and layout~='Table' and layout~='RM-SpellField' then error('unsupported-condition-layout',0) end\\010        self.layout=layout;self:DoLayout()\\010    end\\010    function group:PauseLayout() self.paused=true end\\010    function group:ResumeLayout() self.paused=false;self:DoLayout() end\\010    function group:OnWidthSet() if not self.sizing then self:DoLayout() end end\\010    function group:SetWidth(width)\\010        self.sizing=true;frame:SetWidth(width);frame.width=width;self.sizing=false;self:DoLayout()\\010    end\\010    function group:LayoutFinished(_,height) self:SetHeight(height or 1) end\\010    local function validateChild(self,child,seen)\\010        if not addon:IsConditionWidget(child) or not child.rmActive or child:IsReleasing() then error('foreign-or-inactive-condition-child',0) end\\010        if not self.rmActive or self:IsReleasing() then error('inactive-condition-parent',0) end\\010        if child.parent or seen and seen[child] then error('condition-child-already-owned',0) end\\010        local current=self\\010        for _=1,128 do\\010            if not current then return end\\010            if current==child then error('condition-widget-parent-cycle',0) end\\010            current=current.parent\\010        end\\010        error('condition-widget-parent-cycle',0)\\010    end\\010    function group:AddChild(child)\\010        validateChild(self,child)\\010        self.children[#self.children+1]=child;child.parent=self\\010        child.frame:SetParent(frame);child.frame:Show();self:DoLayout()\\010    end\\010    function group:AddChildren(...)\\010        local seen={}\\010        for i=1,select('#',...) do local child=select(i,...);validateChild(self,child,seen);seen[child]=true end\\010        for i=1,select('#',...) do local child=select(i,...);self.children[#self.children+1]=child;child.parent=self;child.frame:SetParent(frame);child.frame:Show() end\\010        self:DoLayout()\\010    end\\010    function group:ReleaseChildren()\\010        local children=self.children\\010        for _,child in ipairs(children) do if not addon:IsConditionWidget(child) then error('foreign-condition-child',0) end end\\010        self.children={}\\010        local problem\\010        for _,child in ipairs(children) do local ok,why=pcall(addon.ReleaseConditionWidget,addon,child);child.parent=nil;if not ok then problem=problem or why end end\\010        if problem then error(problem,0) end\\010        self:DoLayout()\\010    end\\010    function group:DoLayout()\\010        if self.paused or self.layingOut or self.isQueuedForRelease then return end\\010        self.layingOut=true\\010        local ok,why=pcall(function()\\010        local width=math.max(1,frame:GetWidth() or 300);local padding=self:GetUserData('padding')\\010        padding=type(padding)=='number' and padding==padding and math.max(0,math.min(64,padding)) or 0\\010        width=math.max(1,width-padding*2);local y=padding;local gap=4\\010        local settings=self:GetUserData('table');local columns=self.layout=='Table' and settings and settings.columns\\010        if self.layout=='RM-SpellField' then\\010            y=addon:LayoutWorkbenchSpellGroup(frame,self.children) or 0\\010        else\\010            local widths\\010            if columns and #columns>0 then\\010                widths={};local fixed,weight=gap*(#columns-1),0\\010                for i,column in ipairs(columns) do\\010                    if type(column)=='number' and column<=0 then\\010                        local measured=0\\010                        for index=i,#self.children,#columns do local child=self.children[index];local size=type(child.width)=='number' and child.width or child.frame and child.frame:GetWidth() or 0;measured=math.max(measured,size) end\\010                        widths[i]=measured;fixed=fixed+measured\\010                    elseif type(column)=='number' and column<1 then widths[i]=width*column;fixed=fixed+widths[i]\\010                    elseif type(column)=='number' and column>=10 then widths[i]=column;fixed=fixed+column\\010                    else weight=weight+(type(column)=='number' and column or 1) end\\010                end\\010                for i,column in ipairs(columns) do if not widths[i] then widths[i]=math.max(1,(width-fixed)*(type(column)=='number' and column or 1)/math.max(1,weight)) end end\\010            end\\010            local x,rowHeight,column=padding,0,1\\010            local row={}\\010            local function finishRow()\\010          