texts[60]="    function shell:ShowHelp()\010        local heading=self.section=='ItemSets' and L['Item Sets'] or L[self.section] or L['Help']\010        if self.helpDialog and self.helpDialog.frame:IsShown() and self.helpDialog.heading==heading then self:CloseHelp();return end\010        self.helpDialog=addon:ShowWorkbenchHelp(heading,addon:WorkbenchPageHelp(self.section),addon.pretty_name)\010        self.helpPane=self.helpDialog.frame\010"
texts[61]="    shell.help=addon:CreateWorkbenchHelpButton(window,L[\"Help\"]);shell.help:SetPoint(\"TOPRIGHT\",-31,-5);shell.help:SetSize(20,20);shell.help.icon:SetSize(16,16)\010"
