texts[68]="        section(L['Window controls'],L['Drag the title bar to move. Set Scale with the top-left slider; child windows follow it. The question mark toggles Help. Close with X, Escape, or right-click in the content area.'])} end\010"
texts[69]="        local title=self:SettingsNonempty(entry.name) or entry.type=='item' and (itemInfo(entry.item) and itemInfo(entry.item).name or L['Item data loading']) or self:PlainWorkbenchName(self:SpellLabel(entry.spell))\010"
texts[70]="            end,{canReplace=selected~=nil,selectedName=selected and (self:SettingsNonempty(selected.name) or named[p.selection].name),fallbackName=L['Imported announcement'],originalName=function(input) local decoded=codec:Decode(input);local entry=decoded and type(decoded.value)=='table' and decoded.value.announcement;if type(entry)=='table' then if self:SettingsNonempty(entry.name) then return entry.name end;local info=entry.type=='item' and itemInfo(entry.item) or self.Platform:GetSpellInfo(entry.spell);return info and info.name end end})\010"
texts[71]="        {key='duplicate',text=L['Duplicate'],icon='copy',enabled=selected~=nil,action=function() local copy=self:CopySettingsData(selected);copy.id=self:uuid();values[#values+1]=copy;p.selection=#values;p:Draw() end},\010"
texts[72]="            if entry.type=='item' then local item=entry.item;local set=type(item)=='string' and ((store.profile.itemsets or {})[item] or (store.global.itemsets or {})[item]);valid=type(item)=='table' and #item>0 or set and type(set.items)=='table' and #set.items>0\010"
texts[73]="    local entries={};for i,entry in ipairs(values) do local info=entry.type=='item' and itemInfo(entry.item) or self.Platform:GetSpellInfo(entry.spell);entries[#entries+1]={value=i,text=self:SettingsNonempty(entry.name) or info and info.name or entry.type=='item' and L['Item'] or L['Unknown spell'],icon=info and (info.icon or info.iconID),search=(entry.value or '')..' '..(entry.event or '')..' '..(entry.announce or '')} end\010"
texts[74]="        local info=entry.type=='item' and itemInfo(entry.item) or self.Platform:GetSpellInfo(entry.spell)\010"
texts[75]="            end,current,{persistentOwner=true,announcement=true,title=L['Announcement conditions'],contextLabel=L['Announces']})\010"
texts[76]="                if not p:Valid(generation) or entry.conditions~=source or not self:SettingsDataEqual(source or {},baseline) then return false end\010"
texts[77]="            p:Check(prefix..'emote_target',L['Use spell recipient ({{target}})'],entry.emote_target,function(v) update(entry,'emote_target',v) end)\010"
texts[78]="        if entry.announce=='say' or entry.announce=='yell' then p:Text(L['Automatic Say and Yell are unavailable. Choose another announcement destination.']) end\010"
texts[79]="        if entry.announce=='emote' then choices={};for _,row in ipairs(channels) do choices[#choices+1]=row end;choices[#choices+1]={value='emote',text=L['Custom emote']} end\010"
texts[80]="        p:Choice(prefix..'event',L['Event'],entry.event,events,function(v) update(entry,'event',v) end)\010"
texts[81]="        p:Choice(prefix..'type',L['Action Type'],entry.type,types,function(v) entry.type=v;entry.spell=nil;entry.item=nil;entry.ranked=nil;p:Draw() end)\010        local field=entry.type=='item' and 'item' or 'spell'\010        if entry.type=='item' then p:ItemSequence(prefix..'action',entry.item,function(v) update(entry,'item',v) end)\010"
texts[82]="local types={{value='spell',text=L['Spell']},{value='pet',text=L['Pet Spell']},{value='item',text=L['Item']}}\010"
texts[83]="    local scopes={Integrations={profile={'lua_editor','lua_editor_disabled','lua_native_highlighting','lua_line_numbers','questie_enabled','preview_masque'}},Effects={global={'effects'}},ItemSets={profile={'itemsets'},global={'itemsets'}},Announces={profile={'announces'}},Conditions={profile={'condition_groups','switch_conditions','other_conditions_order','disabled_conditions'},global={'custom_conditions'}},General={profile={'enable','poll','ignore_mana','ignore_range','effect','color','magnification','setpoint','xoffs','yoffs','loglevel','detailed_profiling','disable_autoswitch','live_config_update','spell_history','combat_history','damage_history','disable_buttons','rotation_view','preview_spells','preview_vertical','preview_locked','preview_opacity','preview_icon_size','preview_window','minimap'},char={'specs'}}}\010"
texts[84]="    if p.category=='SWITCH' or p.category=='DEFAULT' or groupIndex then ordered=tags end\010    local function orderChanged(list) if p.category=='SWITCH' then profile.switch_conditions=list elseif p.category=='DEFAULT' then profile.other_conditions_order=list elseif groupIndex then groups[groupIndex].conditions=list end end\010"
texts[85]="    categories[#categories+1]={value='DEFAULT',text=L['Other'],icon=self:GetConditionCategoryIcon(nil)};if p.category~='ALL'  and p.category~='SWITCH' and p.category~='DEFAULT' and not groupIndex then p.category='ALL' end\010"
texts[86]="    local categories={{value='ALL',text=L['All'],icon=self:GetConditionCategoryIcon({id='ALL'})},{value='SWITCH',text=L['Switch'],icon=self:GetConditionCategoryIcon({id='SWITCH'})}}\010"
texts[87]="        self.builder(self);if self.DraftActions then self:DraftActions() end;if not self.creationUsedForNew then self.creationBaseline=nil;self.creationApply=nil end;self.child:SetHeight(self.y+12);self.scroll:UpdateWorkbenchScroll()\010"
texts[88]="        addon:SetUIScript(swatch,'OnEnter',self:Guard(function() swatch.art:SetColorTexture(values.r,values.g,values.b,values.a) end));addon:SetUIScript(swatch,'OnLeave',self:Guard(function() swatch.art:SetColorTexture(values.r,values.g,values.b,values.a) end))\010"
texts[89]="        addon:SetUIScript(c,'OnEnter',self:Guard(function() if selected and GameTooltip then GameTooltip:SetOwner(c,'ANCHOR_RIGHT');GameTooltip:SetHyperlink(provider.kind..':'..selected);GameTooltip:AddLine(provider.kind=='item' and L['Search or drag an item here'] or L['Search or drag a spell here']);GameTooltip:Show() elseif GameTooltip then GameTooltip:SetOwner(c,'ANCHOR_RIGHT');GameTooltip:SetText(c.dropHint:GetText()) end end))\010"
texts[90]="            end,{canReplace=selected~=nil,selectedName=selectedName,fallbackName=L['Imported profile'],originalName=function(input) local decoded=codec:Decode(input);return decoded and type(decoded.value)=='table' and decoded.value.name end})\010"
texts[91]="    d.frame:SetFrameLevel(p.frame:GetFrameLevel()+250);d.frame:Show();d.scroll.workbenchBar:SetValue(0);d.scroll:UpdateWorkbenchScroll();addon:RegisterWindowForEscape(d);if options then preview() end;return d\010"
texts[92]="    addon:SetUIScript(d.frame,'OnHide',function() d.input:ClearFocus() end)\010"
texts[93]="    function d:Hide() self.frame:Hide() end\010    function d:SetReport(title,value,context)\010        self.text=tostring(value or '');self.chrome:SetContext(title,L['Read-only'],context or addon.pretty_name)\010        self.setting=true;self.input:SetText(self.text);self.setting=false;self:Layout();self.frame:Show();addon:RegisterWindowForEscape(self)\010        self.input:SetFocus();self.input:SetCursorPosition(0);self.input:HighlightText(0,-1);self.scroll.workbenchBar:SetValue(0)\010"
texts[94]="    local options={valid=valid,canReplace=canReplace,selectedName=original and original.name or source and (source.body and source.body.name or source.nameKey or source.name),fallbackName=L['Imported rotation'],requirePreview=true}\010"
texts[95]="    p.cleanups[#p.cleanups+1]=function() if d.serial==serial then d.frame:Hide() end end;d.frame:Show();self:RegisterWindowForEscape(d);return d\010"
