rows["Core/announcement_data.lua"]={current="local _,addon=...\010function addon:IsValidAnnouncementItemReference(items)\010    if type(items)=='string' then return #items>0 and #items<=128 end\010    if type(items)~='table' or #items==0 or #items>256 then return false end\010    local count=0\010    for key,item in pairs(items) do\010        if type(key)~='number' or key<1 or key%1~=0 or key>#items or not (type(item)=='number' and item>0 and item<math.huge and item%1==0 or type(item)=='string' and #item>0 and #item<=1024) then return false end;count=count+1\010    end\010    return count==#items\010end\010function addon:IsValidMacroAnnouncementIdentifier(value)\010    return type(value)=='string' and #value<=64 and value:match('^[A-Za-z_][A-Za-z0-9_.-]*$')~=nil\010end\010-- Cold configuration/import check; no retained lookup registry or polling work.\010function addon:AreMacroAnnouncementIdentifiersUnique(entries)\010    if type(entries)~='table' then return false end\010    local seen={}\010    for _,entry in ipairs(entries) do if type(entry)=='table' and entry.type=='macro' then\010        if not self:IsValidMacroAnnouncementIdentifier(entry.identifier) or seen[entry.identifier] then return false end\010        seen[entry.identifier]=true\010    end end\010    return true\010end\010function addon:IsValidAnnouncement(value,requireIdentity)\010    if type(value)~='table' then return false end\010    if requireIdentity and (type(value.id)~='string' or not value.id:match('^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$')) then return false end\010    local allowed={name=true,id=true,type=true,spell=true,item=true,ranked=true,disabled=true,event=true,announce=true,value=true,announce_sound=true,emote=true,emote_target=true,conditions=true,identifier=true}\010    for key in pairs(value) do if not allowed[key] then return false end end\010    local macro=value.type=='macro'\010    if macro then\010        if not self:IsValidMacroAnnouncementIdentifier(value.identifier) or value.spell~=nil or value.item~=nil or value.ranked~=nil or value.event~=nil then return false end\010    elseif value.type~='spell' and value.type~='pet' and value.type~='item' then return false\010    elseif value.identifier~=nil or type(value.event)~='string' or not (self.events or {})[value.event] then return false end\010    if not ({partyraid=true,party=true,raidwarn=true,emote=true,['local']=true,audible=true,say=true,yell=true,gesture=true,whisper=macro})[value.announce] then return false end\010    for _,key in ipairs({'disabled','ranked'}) do if value[key]~=nil and type(value[key])~='boolean' then return false end end\010    if value.name~=nil and (type(value.name)~='string' or #value.name>256) then return false end\010    if value.value~=nil and (type(value.value)~='string' or #value.value>4096) then return false end\010    if value.announce_sound~=nil and (type(value.announce_sound)~='string' or #value.announce_sound>256) then return false end\010    if value.emote_target~=nil and type(value.emote_target)~='boolean' then return false end\010    if value.emote~=nil and (type(value.emote)~='string' or #value.emote>64 or not value.emote:match('^[A-Z][A-Z0-9_]*$')) then return false end\010    if value.announce=='gesture' and value.emote==nil then return false end\010    if value.announce=='audible' and (not value.announce_sound or not value.announce_sound:find('%S')) then return false end\010    if value.conditions~=nil then\010        if type(value.conditions)~='table' or not self.RotationData.CheckPortable(value.conditions) then return false end\010        local result=self.RotationData.ValidateBody({switch=value.conditions,rotation={},cooldowns={}},{conditions=self.conditionDefinitions})\010        if not result.valid or not result.supported then return false end\010    end\010    if macro then return true end\010    if value.type~='item' then return type(value.spell)=='number' and value.spell>0 and value.spell%1==0 end\010    return self:IsValidAnnouncementItemReference(value.item)\010end\010",stages={["c192"]={{at=3665,remove=34,previous=texts[1]},{at=1766,remove=627,previous=texts[2]},{at=1477,remove=212,previous=texts[3]},{at=540,remove=653,previous=texts[1]}},["macro"]={},["six"]={{at=3665,remove=34,previous=texts[1]},{at=1766,remove=627,previous=texts[2]},{at=1477,remove=212,previous=texts[3]},{at=540,remove=653,previous=texts[1]}},}}
rows["Core/condition_catalog.lua"]={current="local _,addon=...\010local pairs=pairs\010\010-- Live catalog/query/dispatch services, independent of options rendering.\010-- Load after Core/conditions.lua; retain its original registry identities.\010local conditions=addon.conditionDefinitions\010local special=addon.conditionSpecials\010\010function addon:findConditionGroup(value)\010    if not value then\010        return nil\010    end\010\010    local profile = addon.db.profile\010    for _, v in pairs(profile.condition_groups) do\010        if v.conditions then\010            for _, cond in pairs(v.conditions) do\010                if value == cond then\010                    return v.id\010                end\010            end\010        end\010    end\010\010    return \"DEFAULT\"\010end\010\010function addon:listConditions(group, nohide, store)\010    store=store or addon.db\010    local profile = store.profile\010    local global = store.global\010\010    local rv = {}\010    if group == \"SWITCH\" or group == \"ANNOUNCEMENT\" then\010        local selected=profile.switch_conditions\010        if group==\"ANNOUNCEMENT\" then selected=profile.announcement_conditions end\010        for _, cond in pairs(type(selected)==\"table\" and selected or {}) do\010            if special[cond] then\010                table.insert(rv, cond)\010            elseif conditions[cond] then\010                table.insert(rv, cond)\010            end\010        end\010        for cond,_ in pairs(special) do\010            if not addon.index(rv, cond) then\010                table.insert(rv, cond)\010            end\010        end\010    elseif group == \"CUSTOM\" then\010        for key, _ in pairs(global.custom_conditions) do\010            table.insert(rv, key)\010        end\010    else\010        local skipped = {}\010        for _, v in pairs(profile.condition_groups) do\010            if v.conditions then\010                if group == \"DEFAULT\" then\010                    for _, cond in pairs(v.conditions) do\010                        skipped[cond] = true\010                    end\010                elseif group == v.id or group == \"ALL\" then\010                    for _, cond in pairs(v.conditions) do\010                        if special[cond] then\010                            table.insert(rv, cond)\010                        elseif conditions[cond] then\010                            table.insert(rv, cond)\010                        end\010                        skipped[cond] = true\010                    end\010                end\010            end\010        end\010        if group == \"DEFAULT\" or group == \"ALL\" then\010            for _, cond in pairs(profile.other_conditions_order) do\010                if not (group == \"ALL\" and skipped[cond]) then\010                    if special[cond] then\010                        table.insert(rv, cond)\010                    elseif conditions[cond] then\010                        table.insert(rv, cond)\010                    end\010                    skipped[cond] = true\010                end\010            end\010            for cond,_ in pairs(special) do\010                if not skipped[cond] then\010                    table.insert(rv, cond)\010                end\010            end\010            for cond,_ in pairs(conditions) do\010                if not skipped[cond] and (nohide or not addon.index(profile.disabled_conditions, cond)) then\010                    table.insert(rv, cond)\010                end\010            end\010        end\010    end\010    if group == \"ALL\" or group == \"CUSTOM\" then\010        table.sort(rv, function(lhs, rhs)\010            local ldesc, rdesc\010            if special[lhs] then\010                ldesc = special[lhs].desc\010            else\010                ldesc = conditions[lhs].description\010            end\010            if special[rhs] then\010                rdesc = special[rhs].desc\010            else\010                rdesc = conditions[rhs].description\010            end\010            return ldesc < rdesc\010        end)\010    end\010\010    return rv\010end\010\010function addon:describeCondition(type)\010    if type ~= nil then\010        if special[type] then\010            return special[type].icon, special[type].desc, \"\", special[type].fields\010        end\010        if conditions[type] then\010            return conditions[type].icon, conditions[type].description, conditions[type].help, conditions[type].fields\010        end\010    end\010end\010\010function addon:widgetCondition(parent, spec, value)\010    if value ~= nil and value.type ~= nil and conditions[value.type] ~= nil and conditions[value.type].widget ~= nil then\010        conditions[value.type].widget(parent, spec, value)\010    end\010end\010",stages={["c192"]={{at=848,remove=265,previous=texts[4]}},["flag"]={},["six"]={{at=848,remove=265,previous=texts[4]}},}}
rows["Core/profile_data.lua"]={current="local _,addon=...\010local scalar={unitStateSwitchSeeded='boolean',rotationFallbackID='string',lua_editor='string',lua_native_highlighting='boolean',lua_line_numbers='boolean',questie_enabled='boolean',preview_masque='boolean',version='number',enable='boolean',poll='number',ignore_mana='boolean',ignore_range='boolean',effect='string',magnification='number',setpoint='string',xoffs='number',yoffs='number',loglevel='number',detailed_profiling='boolean',disable_autoswitch='boolean',live_config_update='number',spell_history='number',combat_history='number',damage_history='number',disable_buttons='boolean',rotation_view='string',preview_spells='number',preview_vertical='boolean',preview_locked='boolean',preview_opacity='number',preview_icon_size='number'}\010local function dense(value,validate)\010    if type(value)~='table' then return false end;local n=0;for key,item in pairs(value) do if type(key)~='number' or key<1 or key%1~=0 or key>#value or not validate(item) then return false end;n=n+1 end;return n==#value\010end\010local function fields(value,schema)\010    if type(value)~='table' then return false end;for key,item in pairs(value) do if type(item)~=schema[key] then return false end end;return true\010end\010local function specKey(key,encode)\010    local number=type(key)=='string' and not encode and key:match('^%d+$') and tonumber(key) or key\010    if type(number)~='number' or number<0 or number==math.huge or number%1~=0 then return nil end\010    local text=tostring(number)\010    if not text:match('^%d+$') or type(key)=='string' and key~=text then return nil end\010    return encode and text or number\010end\010local function specMap(map,encode)\010    if type(map)~='table' or getmetatable(map) then return nil end\010    local result={}\010    for key,value in pairs(map) do local converted=specKey(key,encode);if converted==nil or result[converted]~=nil then return nil end;result[converted]=value end\010    return result\010end\010-- Preserve the whole reference graph while converting only structural spec-map\010-- keys. A map aliased through another owner or payload must remain aliased for\010-- the pure store validator to reject it; conversion must never hide that defect.\010local function scopedStore(addon,state,encode)\010    local function plain(v) return type(v)=='table' and getmetatable(v)==nil end\010    if not plain(state) or not plain(state.classes) or not plain(state.characters) or not plain(state.legacy) then return nil end\010    if encode and not addon.RotationData.ValidateRotationStore(state) then return nil end\010    local maps={}\010    for _,map in pairs(state.classes) do if not plain(map) then return nil end;maps[map]=true end\010    for _,bucket in pairs(state.characters) do if not plain(bucket) or not plain(bucket.specs) then return nil end;maps[bucket.specs]=true end\010    for _,kind in ipairs({'rotations','origins','imports','comparisons'}) do\010        local map=state.legacy[kind];if map~=nil then if not plain(map) then return nil end;maps[map]=true end\010    end\010    local seen={};local failed=false\010    local function copy(value)\010        if type(value)~='table' then return value end\010        if not plain(value) then failed=true;return nil end\010        if seen[value] then return seen[value] end\010        local result={};seen[value]=result\010        for key,child in pairs(value) do\010            local converted=key\010            if maps[value] then converted=specKey(key,encode) end\010            if converted==nil or result[converted]~=nil then failed=true;return nil end\010            result[converted]=copy(child)\010        end\010        return result\010    end\010    local result=copy(state)\010    if failed or not encode and not addon.RotationData.ValidateRotationStore(result) then return nil end\010    return result\010end\010-- Reject malformed optional stock before generic recursive profile copying.\010local function validStockTargets(addon,profile)\010    if type(profile)~='table' then return true end\010    local plan=rawget(profile,'stockTargets')\010    return plan==nil or addon.StockTargets.Validate(plan)==true\010end\010local function validRotationChoices(owner,profile)\010    local value=type(profile)=='table' and rawget(profile,'rotationChoicePreferences')\010    return value==nil or type(owner.ValidateRotationChoicePreferences)=='function' and owner:ValidateRotationChoicePreferences(value)==true\010end\010function addon:ValidateProfileTransfer(value)\010    if type(value)~='table' then return false end\010    if not validStockTargets(self,value) or not validRotationChoices(self,value) then return false end\010    local wire=self:ProfileToPortable(value);if not wire or not self.RotationData.CheckPortable(wire) then return false end\010    local function stringValue(v) return type(v)=='string' end\010    for key,item in pairs(value) do\010        if scalar[key] then if type(item)~=scalar[key] then return false end\010        elseif key=='rotationTagColors' then\010            if type(item)~='table' then return false end;local count=0;for tag,color in pairs(item) do count=count+1;if count>4096 or not self.RotationData.NormalizeRotationTags({tag}) or tag~=tag:lower() or not fields(color,{r='number',g='number',b='number',a='number'}) then return false end;for _,channel in ipairs({'r','g','b','a'}) do local n=color[channel];if type(n)~='number' or n~=n or n<0 or n>1 then return false end end end\010        elseif key=='color' then if not fields(item,{r='number',g='number',b='number',a='number'}) then return false end;for _,v in pairs(item) do if v<0 or v>1 then return false end end\010        elseif key=='preview_window' then if not fields(item,{point='string',relpoint='string',xoffs='number',yoffs='number'}) then return false end\010        elseif key=='minimap' then if not fields(item,{hide='boolean',minimapPos='number',radius='number',lock='boolean',showInCompartment='boolean'}) then return false end\010        elseif key=='switch_conditions' or key=='announcement_conditions' or key=='disabled_conditions' or key=='other_conditions_order' then if not dense(item,stringValue) then return false end\010        elseif key=='condition_groups' then\010            if not dense(item,function(group) return type(group)=='table' and fields(group,{id='string',name='string',conditions='table',icon=type(group.icon)}) and type(group.id)=='string' and type(group.name)=='string' and dense(group.conditions,stringValue) and (group.icon==nil or self:IsCategoryIcon(group.icon)) end) then return false end\010        elseif key=='announces' then local seen={};if not self:AreMacroAnnouncementIdentifiersUnique(item) or not dense(item,function(v) if not self:IsValidAnnouncement(v,true) or seen[v.id] then return false end;seen[v.id]=true;return true end) then return false end\010        elseif key=='lua_editor_disabled' then\010            if type(item)~='table' or getmetatable(item)~=nil then return false end\010            local count=0\010            for name,disabled in pairs(item) do\010                count=count+1\010                if count>64 or type(name)~='string' or #name>128 or not name:find('%S') or name=='auto' or name=='plain' or disabled~=true then return false end\010            end\010        elseif key=='rotationChoicePreferences' then\010            -- Closed optional schema checked before generic recursive copying.\010        elseif key=='stockTargets' then\010            -- Closed optional schema was checked before copying the profile.\010        elseif key=='itemsets' then\010            if type(item)~='table' then return false end;for id,set in pairs(item) do if type(id)~='string' or not fields(set,{name='string',items='table',modified='boolean'}) or type(set.name)~='string' or not dense(set.items,function(v) return type(v)=='string' and #v>0 or type(v)=='number' and v>0 and v%1==0 end) then return false end end\010        elseif key=='rotations' then\010            if type(item)~='table' then return false end\010            for spec,rotations in pairs(item) do\010                if type(spec)~='number' or spec<0 or spec%1~=0 or type(rotations)~='table' then return false end\010                for id,body in pairs(rotations) do if type(id)~='string' then return false end;local check=self.RotationData.ValidateBody(body,{conditions=self.conditionDefinitions,itemsets=value.itemsets,effects=self.db.global.effects});if not check.valid then return false end end\010            end\010        elseif key=='rotationStore' then\010            if not self.RotationData.ValidateRotationStore(item) then return false end\010        elseif key=='rotationLibrary' then\010            if type(item)~='table' then return false end\010            -- Library preferences and clone provenance are portable data only;\010            -- no global definitions, functions or executable imports are loaded.\010            for field,rows in pairs(item) do\010                if not ({preferences=true,origins=true,comparisons=true,imports=true})[field] or type(rows)~='table' then return false end\010                if field=='preferences' then for id,preference in pairs(rows) do if type(id)~='string' or not fields(preference,{enabled='boolean'}) then return false end end\010                else for spec,records in pairs(rows) do\010                    if type(spec)~='number' or spec<0 or spec%1~=0 or type(records)~='table' then return false end\010                    for id,record in pairs(records) do\010                        if type(id)~='string' or type(record)~='table' then return false end\010                        if field=='origins' and (type(record.manifest)~='table' or type(record.lineage)~='table') then return false end\010                        if field=='imports' and (type(record.manifest)~='table' or type(record.sourceId)~='string' or type(record.stepOrigins)~='table') then return false end\010                        if field=='comparisons' and (type(record.kind)~='string' or type(record.id)~='string' or type(record.origins)~='table') then return false end\010                    end\010                end end\010            end\010        else return false end\010    end\010    if value.version~=nil and (value.version<1 or value.version>3 or value.version%1~=0) then return false end\010    if value.rotationFallbackID~=nil and (#value.rotationFallbackID==0 or #value.rotationFallbackID>128 or not value.rotationFallbackID:find('%S') or value.rotationFallbackID:find('[%z\\1-\\31\\127]')) then return false end\010    if value.lua_editor~=nil and (#value.lua_editor>128 or not value.lua_editor:find('%S')) then return false end\010    if value.rotation_view~=nil and value.rotation_view~='diagram' and value.rotation_view~='list' then return false end\010    if value.preview_spells~=nil and (value.preview_spells<0 or value.preview_spells>5 or value.preview_spells%1~=0) then return false end\010    if value.preview_opacity~=nil and (value.preview_opacity<0 or value.preview_opacity>1) then return false end\010    if value.preview_icon_size~=nil and (value.preview_icon_size<24 or value.preview_icon_size>160) then return false end\010    if value.poll~=nil and (value.poll<.01 or value.poll>5) then return false end\010    if value.magnification~=nil and (value.magnification<.1 or value.magnification>10) then return false end\010    for _,key in ipairs({'live_config_update','spell_history','combat_history','damage_history'}) do if value[key]~=nil and value[key]<0 then return false end end\010    return true\010end\010-- Profile specialization maps include spec 0. The shared rotation transport\010-- intentionally accepts only positive numeric table keys, so profile wire maps\010-- use canonical decimal strings and restore numbers only in these namespaces.\010function addon:ProfileToPortable(profile)\010    if not validStockTargets(self,profile) or not validRotationChoices(self,profile) then return nil end\010    local copy=self:CopySettingsData(profile)\010    local function encode(map) return specMap(map,true) end\010    if type(copy)=='table' then\010        if copy.rotations~=nil then copy.rotations=encode(copy.rotations);if not copy.rotations then return nil end end\010        if type(copy.rotationLibrary)=='table' then for _,key in ipairs({'origins','comparisons','imports'}) do if copy.rotationLibrary[key]~=nil then copy.rotationLibrary[key]=encode(copy.rotationLibrary[key]);if not copy.rotationLibrary[key] then return nil end end end end\010        if copy.rotationStore~=nil then copy.rotationStore=scopedStore(self,profile.rotationStore,true);if not copy.rotationStore then return nil end end\010    end\010    return copy\010end\010function addon:ProfileFromPortable(profile,options)\010    if not validStockTargets(self,profile) or not validRotationChoices(self,profile) then return nil end\010    local copy=self:CopySettingsData(profile)\010    local function decode(map) return specMap(map,false) end\010    if type(copy)~='table' then return nil end\010    if copy.rotationStore~=nil then copy.rotationStore=scopedStore(self,profile.rotationStore,false);if not copy.rotationStore then return nil end end\010    if copy.rotations~=nil then copy.rotations=decode(copy.rotations);if not copy.rotations then return nil end end\010    -- Older profile exports can retain an entirely empty default placeholder.\010    -- Materialize only its missing empty lists; malformed nonempty records still\010    -- go through normal validation and are never silently repaired or removed.\010    if not (type(options)=='table' and options.preserveLegacyBodies==true) and type(copy.rotations)=='table' then for _,rotations in pairs(copy.rotations) do\010        if type(rotations)=='table' then for _,body in pairs(rotations) do\010            if type(body)=='table' and next(body)==nil then body.rotation={};body.cooldowns={} end\010        end end\010    end end\010    if copy.rotationLibrary~=nil t