   if WOW_PROJECT_ID ~= WOW_PROJECT_MAINLINE and spec ~= BOOKTYPE_PET then\\010        local nr_button = addon:CreateConditionCheckBox()\\010        nr_button:SetLabel(L[\\\"Use this exact spell rank\\\"])\\010        nr_button:SetValue(value.ranked or false)\\010        nr_button:SetCallback(\\\"OnValueChanged\\\", function(_, _, val)\\010            value.ranked = val\\010            spell:SetUserData(\\\"norank\\\", not val)\\010            spell:SetText(value.spell and SpellData:SpellName(value.spell, not value.ranked))\\010            update()\\010        end)\\010        nr_button:SetDisabled(value.disabled)\\010        rankChoice=nr_button\\010    end\\010\\010    spell:SetFullWidth(true)\\010    spell:SetLabel('')\\010    spell:SetText(value.spell and SpellData:SpellName(value.spell, not value.ranked))\\010    spell:SetUserData(\\\"norank\\\", not value.ranked)\\010    spell:SetUserData(\\\"spec\\\", spec)\\010    spell:SetCallback(\\\"OnEnterPressed\\\", function(_, _, v)\\010        if not addon.isint(v) then\\010            v = nametoid(v)\\010        else\\010            v = tonumber(v)\\010        end\\010        if isvalid(v) then\\010            value.spell = v\\010            spell:SetText(SpellData:SpellName(value.spell, not value.ranked))\\010        else\\010            value.spell = nil\\010            spell:SetText(nil)\\010        end\\010        spellIcon:SetText(value.spell)\\010        update()\\010    end)\\010    spell:SetDisabled(value.disabled)\\010    spell_group:AddChild(spell)\\010    if rankChoice then\\010        rankChoice.frame.GetFontString=function() return rankChoice.button:GetFontString() end\\010        spell_group:AddChild(rankChoice)\\010    end\\010\\010    return spell_group\\010\",[\"description\"]=\"Create a spell input with suggestions, validation and spell-link support for custom condition widgets. The update callback owns saving a chosen value; add the returned widget to the callback parent.\",[\"kind\"]=\"function\"