rows["UI/collection_compare.lua"]={current="local addon_name,addon=...\010local L=LibStub('AceLocale-3.0'):GetLocale(addon_name)\010local function equal(a,b)\010    if type(a)~=type(b) then return false end\010    if type(a)~='table' then return a==b end\010    for key,value in pairs(a) do if not equal(value,b[key]) then return false end end\010    for key in pairs(b) do if a[key]==nil then return false end end;return true\010end\010local function scalar(value)\010    if value==nil then return L['None'] end\010    if type(value)=='boolean' then return value and L['Yes'] or L['No'] end\010    if type(value)=='number' then return string.format('%.4g',value) end\010    return tostring(value)\010end\010local function color(value)\010    if type(value)~='table' then return scalar(value) end\010    return string.format('R %.3f  G %.3f  B %.3f  A %.3f',value.r or 1,value.g or 1,value.b or 1,value.a or 1)\010end\010function addon:CollectionComparisonRows(kind,left,right,showSame)\010    local rows={};local total=0\010    local function add(label,a,b,format,icons)\010        local changed=not equal(a,b);if changed then total=total+1 end\010        if changed or showSame then rows[#rows+1]={label=label,left=(format or scalar)(a),right=(format or scalar)(b),changed=changed,leftIcon=icons and icons(a),rightIcon=icons and icons(b)} end\010    end\010    add(L['Name'],left.name,right.name)\010    if kind=='profile' then\010        local labels={lua_editor=L['Lua editor'],identifier=L['Identifier'],definition=L['Definition'],enable=L['Enable'],poll=L['Polling Interval (seconds)'],ignore_mana=L['Ignore mana'],ignore_range=L['Ignore range'],effect=L['Effect'],color=L['Highlight Color'],magnification=L['Magnification'],setpoint=L['Anchor'],xoffs=L['H'],yoffs=L['V'],loglevel=L['Log Level'],detailed_profiling=L['Detailed Profiling'],disable_autoswitch=L['Disable Auto-Switching'],live_config_update=L['Live Status Update Frequency (seconds)'],spell_history=L['Spell History Memory (second