rows["UI/condition_canvas.lua"]={current="local addon_name,addon=...\010local L=LibStub(\"AceLocale-3.0\"):GetLocale(addon_name)\010local function pathCopy(path) local result={};for i,p in ipairs(path) do result[i]=p end;return result end\010local function prefix(a,b)\010    if #a>#b then return false end\010    for i,p in ipairs(a) do if b[i]~=p then return false end end;return true\010end\010local function sibling(a,b)\010    if #a~=#b or type(a[#a])~=\"number\" or type(b[#b])~=\"number\" then return false end\010    for i=1,#a-1 do if a[i]~=b[i] then return false end end;return true\010end\010local function pendingOrFocused(widget)\010    if not widget then return false end\010    if widget.IsPending and widget:IsPending() then return true end\010    for _,input in pairs({widget.frame,widget.editbox,widget.edit}) do if input.HasFocus and input:HasFocus() then return true end end\010    for _,child in ipairs(widget.children or {}) do if pendingOrFocused(child) then return true end end\010    return false\010end\010function addon:CreateConditionCanvas(parent,owner)\010    local canvas={frame=addon:CreateWorkbenchScrollFrame(parent),cards={},lines={},zones={},generation=0,owner=owner}\010    canvas.child=CreateFrame(\"Frame\",nil,canvas.frame);canvas.frame:SetScrollChild(canvas.child)\010    function canvas:Selection()\010        local result={};if not owner.active then return result end\010        for _,row in ipairs(owner.active.session:Rows(4096)) do\010            if owner.view.selection[addon.ConditionPathKey(row.path)] then result[#result+1]=pathCopy(row.path) end\010        end\010        return result\010    end\010    function canvas:Select(path,control,shift)\010        if not owner.active or not owner:SyncWorking() then return end\010        local key=addon.ConditionPathKey(path);local selection=owner.view.selection\010        local rows=owner.active.session:Rows(4096)\010        if shift and self.anchor and sibling(path,self.anchor) then\010            if not control then selection={} end\010            local low,high=math.min(path[#path],self.anchor[#path]),math.max(path[#path],self.anchor[#path])\010            local parent=pathCopy(path);table.remove(parent)\010            local added={}\010            for _,row in ipairs(rows) do\010                local key=addon.ConditionPathKey(row.path);local index=row.path[#path]\010                local within=prefix(parent,row.path) and type(index)=='number' and index>=low and index<=high\010                if prefix(row.path,parent) or within then selection[key]=nil end\010                if sibling(path,row.path) and within then added[key]=true end\010            end\010            for key in pairs(added) do selection[key]=true end\010        elseif control then\010            if selection[key] then selection[key]=nil else\010                for _,row in ipairs(rows) do\010                    if prefix(row.path,path) or prefix(path,row.path) then selection[addon.ConditionPathKey(row.path)]=nil end\010                end\010                selection[key]=true\010            end\010        else selection={[key]=true} end\010        owner.view.selection=selection;owner.active.selected=pathCopy(path);self.anchor=pathCopy(path)\010        if (#self:Selection()>1)~=owner.selectionStrip then owner:Layout() else self:Reflow() end\010    end\010    local ghost=addon:CreateWorkbenchDragCard();canvas.ghost=ghost\010    function canvas:CancelDrag()\010        local moving=self.drag\010        self.drag=nil;ghost:Hide();addon:SetUIScript(self.frame,\"OnUpdate\",nil)\010        for _,zone in ipairs(self.zones) do zone.marker:Hide();zone:Hide() end\010        if moving and self.RefreshVisibleCards and not self.rendering and not self.releasing then\010            if self.deferredMeasure then self.deferredMeasure=nil;self.needsMeasure=nil;self:Reflow() else self:RefreshVisibleCards() end\010        end\010    end\010    function canvas:CanDrop(target)\010        local drag=self.drag\01