rows["UI/controls.lua"]={current="local addon_name,addon=...\010-- Native controls with the compact flat-button conventions used by modern\010-- addon workbenches. No dependency on another installed addon's frames.\010---@class RMWorkbenchButton: Button\010---@field art Texture\010---@field SetSelected fun(self: RMWorkbenchButton, value: boolean)\010---@return RMWorkbenchButton\010function addon:CreateWorkbenchButton(parent,label,width)\010    local button=CreateFrame(\"Button\",nil,parent);button:SetSize(width or 28,20);button:EnableMouse(true)\010    local caption=button:CreateFontString(nil,\"OVERLAY\",\"GameFontHighlightSmall\");caption:SetPoint(\"CENTER\")\010    button:SetFontString(caption);button:SetText(label or \"\")\010    local background=button:CreateTexture(nil,\"BACKGROUND\");background:SetAllPoints(button);button.art=background\010    local function rest()\010        if button.selected then background:SetColorTexture(.24,.24,.24,.8) else background:SetColorTexture(.16,.16,.16,.5) end\010    end\010    function button:SetSelected(value) self.selected=value==true;rest() end\010    addon:SetUIScript(button,\"OnEnter\",function()\010        background:SetColorTexture(.27,.27,.27,.8)\010        if button.tooltip and GameTooltip then GameTooltip:SetOwner(button,\"ANCHOR_RIGHT\");GameTooltip:SetText(button.tooltip,1,1,1,1,true) end\010    end)\010    addon:SetUIScript(button,\"OnLeave\",function() rest();if GameTooltip and GameTooltip:IsOwned(button) then GameTooltip:Hide() end end)\010    addon:SetUIScript(button,\"OnEnable\",function() button:SetAlpha(1) end)\010    addon:SetUIScript(button,\"OnDisable\",function() button:SetAlpha(.35) end)\010    rest();\010    ---@cast button RMWorkbenchButton\010    return button\010end\010function addon:ControlTexture(name)\010    return \"Interface\\\\AddOns\\\\\"..addon_name..\"\\\\Assets\\\\Controls\\\\\"..name..\".tga\"\010end\010---@class RMIconButton: RMWorkbenchButton\010---@field icon Texture\010---@return RMIconButton\010function addon:CreateWorkbenchIconButton(parent,name,tooltip)\010    local button=self:CreateWorkbenchButton(parent,\"\",20);button:SetSize(20,20);button.tooltip=tooltip\010    button.icon=button:CreateTexture(nil,\"ARTWORK\");button.icon:SetPoint(\"CENTER\");button.icon:SetSize(16,16)\010    button.icon:SetTexture(self:ControlTexture(name));if name=='trash' then button.icon:SetVertexColor(1,.25,.25,1) end;button.art:Hide()\010    ---@cast button RMIconButton\010    return button\010end\010---@return RMIconButton\010function addon:CreateWorkbenchHelpButton(parent,tooltip)\010    local button=self:CreateWorkbenchIconButton(parent,'help',tooltip);button:SetSize(20,20);button.icon:SetSize(18,18);button.icon:SetVertexColor(1,.82,.25,1);return button\010end\010function addon:CreateWorkbenchHistoryButton(parent,direction,label)\010    local button=self:CreateWorkbenchIconButton(parent,direction,label);button:SetSize(68,20);button:SetText(label);button.art:Show()\010    button.icon:ClearAllPoints();button.icon:SetPoint('LEFT',3,0)\010    local caption=button:GetFontString();caption:ClearAllPoints();caption:SetPoint('LEFT',24,0);return button\010end\010function addon:CreateWorkbenchLabeledIconButton(parent,icon,label,width)\010    local button=self:CreateWorkbenchHistoryButton(parent,icon,label);button:SetWidth(width or 100);return button\010end\010function addon:PaintSelectorSelection(button,entry,caption)\010    button:SetText(caption or entry and entry.text or '')\010    if entry and entry.icon then\010        button.valueIcon=button.valueIcon or button:CreateTexture(nil,'ARTWORK');button.valueIcon:ClearAllPoints();button.valueIcon:SetPoint('LEFT',25,0);button.valueIcon:SetSize(18,18);button.valueIcon:SetTexture(entry.icon);button.valueIcon:Show();self:AlignWorkbenchTextLeft(button,48)\010    else if button.valueIcon then button.valueIcon:Hide() end;self:AlignWorkbenchTextLeft(button,26) end\010end\010function addon:AlignWorkbenchTextLeft(button,inset)\010    local label=button:GetFontString();label:ClearAllPoints();label:SetPoint('LEFT',inset or 4,0);label:SetJustifyH('LEFT');label:SetWidth(math.max(1,button:GetWidth()-(inset or 4)-4))\010end\010---@class RMWorkbenchPill: RMWorkbenchButton\010---@field SetAccent fun(self: RMWorkbenchPill, r: number, g: number, b: number, alpha?: number)\010---@return RMWorkbenchPill\010function addon:CreateWorkbenchPill(parent,label,width)\010    local button=self:CreateWorkbenchButton(parent,label,width);button:SetSize(width or 56,18);button.art:Hide()\010    button.pillDecoration=self:CreateRoundedCardDecoration(button)\010    local accent={.35,.65,.4};local accentAlpha=.7\010    local function paint(hover)\010        local color=button.selected and accent or {.48,.48,.48}\010        button.pillDecoration:SetColors(color[1],color[2],color[3],hover and 1 or button.selected and accentAlpha or .7,button.selected and .6 or .25)\010    end\010    function button:SetSelected(value) self.selected=value==true;paint(false) end\010    function button:SetAccent(r,g,b,a) accent={r,g,b};accentAlpha=a or .7;paint(false) end\010    addon:SetUIScript(button,'OnEnter',function() paint(true);if button.tooltip and GameTooltip then GameTooltip:SetOwner(button,'ANCHOR_RIGHT');GameTooltip:SetText(button.tooltip,1,1,1,1,true) end end)\010    addon:SetUIScript(button,'OnLeave',function() paint(false);if GameTooltip and GameTooltip:IsOwned(button) then GameTooltip:Hide() end end)\010    paint(false);\010    ---@cast button RMWorkbenchPill\010    return button\010end\010---@class RMWorkbenchCheckBox: RMWorkbenchButton\010---@field SetChecked fun(self: RMWorkbenchCheckBox, value: boolean)\010---@field GetChecked fun(self: RMWorkbenchCheckBox): boolean\010---@return RMWorkbenchCheckBox\010function addon:CreateWorkbenchCheckBox(parent,label,width)\010    local button=self:CreateWorkbenchButton(parent,label,width);button.art:Hide()\010    local box=button:CreateTexture(nil,'BACKGROUND');box:SetPoint('LEFT',0,0);box:SetSize(16,16);box:SetColorTexture(.1,.1,.1,1)\010    local check=button:CreateTexture(nil,'ARTWORK');check:SetPoint('LEFT',0,0);check:SetSize(16,16);check:SetTexture(self:ControlTexture('check'));check:SetVertexColor(1,.82,.2,1);button.check=check\010    local text=button:GetFontString();text:ClearAllPoints();text:SetPoint('LEFT',22,0);text:SetWidth(math.max(1,(width or 150)-22));text:SetJustifyH('LEFT')\010    function button:SetChecked(value) self.checked=value==true;if self.checked then check:Show() else check:Hide() end end\010    function button:GetChecked() return self.checked end\010    button:SetChecked(false)\010    ---@cast button RMWorkbenchCheckBox\010    return button\010end\010function addon:GetConditionIcon(tag)\010    local replacement=self.conditionIcons and self.conditionIcons[tag]\010    local definition=(self.conditionDefinitions or {})[tag] or (self.conditionSpecials or {})[tag]\010    local icon=replacement or definition and definition.icon\010    return (type(icon)==\"string\" or type(icon)==\"number\") and icon or \"Interface\\\\Icons\\\\INV_Misc_QuestionMark\"\010end\010function addon:CreateRoundedCardDecoration(frame)\010    local decoration={fill={},border={}}\010    for _,layer in ipairs({{key=\"fill\",texture=\"card-fill\",draw=\"BACKGROUND\"},{key=\"border\",texture=\"card-border\",draw=\"BORDER\"}}) do\010        for row=1,3 do for column=1,3 do\010            local texture=frame:CreateTexture(nil,layer.draw);texture:SetTexture(self:ControlTexture(layer.texture))\010            local coords={0,.125,.875,1};texture:SetTexCoord(coords[column],coords[column+1],coords[row],coords[row+1])\010            local top=row==1 and \"TOP\" or row==3 and \"BOTTOM\" or \"\"\010            local side=column==1 and \"LEFT\" or column==3 and \"RIGHT\" or \"\"\010            if row==2 and column==2 then\010                texture:SetPoint(\"TOPLEFT\",frame,\"TOPLEFT\",8,-8);texture:SetPoint(\"BOTTOMRIGHT\",frame,\"BOTTOMRIGHT\",-8,8)\010            elseif row==2 then\010                texture:SetPoint(\"TOP\"..side,frame,\"TOP\"..side,0,-8);texture:SetPoint(\"BOTTOM\"..side,frame,\"BOTTOM\"..side,0,8);texture:SetWidth(8)\010            elseif column==2 then\010                texture:SetPoint(top..\"LEFT\",frame,top..\"LEFT\",8,0);texture:SetPoint(top..\"RIGHT\",frame,top..\"RIGHT\",-8,0);texture:SetHeight(8)\010            else texture:SetPoint(top..side,frame,top..side,0,0);texture:SetSize(8,8) end\010            decoration[layer.key][#decoration[layer.key]+1]=texture\010        end end\010    end\010    function decoration:SetColors(r,g,b,alpha,fillAlpha)\010        for _,part in ipairs(self.border) do part:SetVertexColor(r,g,b,alpha) end\010        for _,part in ipairs(self.fill) do part:SetVertexColor(.15,.15,.15,fillAlpha) end\010    end\010    return decoration\010end\010---@class RMConditionChevron: RMIconButton\010---@field PointDown fun(self: RMConditionChevron, down: boolean)\010---@field PointState fun(self: RMConditionChevron, state: string)\010---@return RMConditionChevron\010function addon:CreateConditionChevron(parent)\010    local button=self:CreateWorkbenchIconButton(parent,\"chevron-right\");button:SetSize(18,18)\010    function button:PointDown(down) self.icon:SetTexture(addon:ControlTexture(down and \"chevron-down\" or \"chevron-right\")) end\010    function button:PointState(state)\010        self.icon:SetRotation(state=='compact' and math.pi or 0)\010        self.icon:SetTexture(addon:ControlTexture(state=='compact' and 'chevron-down' or state=='expanded' and 'chevron-double-down' or 'chevron-down'))\010    end\010    button:PointDown(false)\010    ---@cast button RMConditionChevron\010    return button\010end\010\010-- Names are editable labels; spell hyperlinks belong in action summaries.\010function addon:PlainWorkbenchName(value)\010    if type(value)~='string' then return '' end\010    return (value:gsub('|H.-|h%[(.-)%]|h','%1'):gsub('|H.-|h(.-)|h','%1'):gsub('|c%x%x%x%x%x%x%x%x',''):gsub('|r',''):gsub('|T.-|t',''))\010end\010function addon:BindWorkbenchInlineName(input,finish)\010    local function down() return IsMouseButtonDown and (IsMouseButtonDown('LeftButton') or IsMouseButtonDown('RightButton')) or false end\010    input.rmNameMouseDown=down()\010    addon:SetUIScript(input,'OnEditFocusGained',function() input.rmNameMouseDown=down() end)\010    addon:SetUIScript(input,'OnEditFocusLost',finish)\010    addon:SetUIScript(input,'OnUpdate',function()\010        local pressed=down()\010        if pressed and not input.rmNameMouseDown and not addon:IsWorkbenchDropZoneUnderPointer(input,input) then input:ClearFocus();finish() end\010        input.rmNameMouseDown=pressed\010    end)\010end\010function addon:CreateWorkbenchListRow(parent,width,height)\010    local row=self:CreateWorkbenchButton(parent,'',width)\010    row:SetHeight(height or 32)\010    return row\010end\010function addon:SetWorkbenchListSelection(control,selected)\010    if control.SetSelected then control:SetSelected(selected) end\010    if not control.selection then control.selection=control:CreateTexture(nil,'BACKGROUND');control.selection:SetAllPoints(control) end\010    control.selection:SetColorTexture(.1,.25,.3,.8)\010    if selected then control.selection:Show() else control.selection:Hide() end\010end\010function addon:CreateWorkbenchEditBox(parent)\010    local input=CreateFrame(\"EditBox\",nil,parent);input:SetFontObject(\"GameFontHighlightSmall\");input:SetAutoFocus(false)\010    input:SetTextInsets(6,6,0,0);input:SetHeight(24)\010    local background=input:CreateTexture(nil,\"BACKGROUND\");background:SetAllPoints(input);background:SetColorTexture(.08,.09,.10,.95)\010    local line=input:CreateTexture(nil,\"BORDER\");line:SetPoint(\"BOTTOMLEFT\");line:SetPoint(\"BOTTOMRIGHT\");line:SetHeight(1);line:SetColorTexture(.38,.43,.48,.8)\010    input.art=background;return input\010end\010function addon:AttachWorkbenchSearchHint(input,text)\010    if input.searchHint then return input.searchHint end\010    local hint=input:CreateFontString(nil,'OVERLAY','GameFontDisableSmall');input.searchHint=hint\010    hint:SetPoint('LEFT',6,0);hint:SetJustifyH('LEFT');hint:SetText(text or LibStub('AceLocale-3.0'):GetLocale(addon_name)['Search...'])\010    local focused=false\010    local function refresh()\010        hint:SetWidth(math.max(1,input:GetWidth()-12))\010        if not focused and (input:GetText() or '')=='' then hint:Show() else hint:Hide() end\010    end\010    input:HookScript('OnEditFocusGained',function() focused=true;refresh() end)\010    input:HookScript('OnEditFocusLost',function() focused=false;refresh() end)\010    input:HookScript('OnTextChanged',refresh);input:HookScript('OnSizeChanged',refresh)\010    input:HookScript('OnHide',function() focused=false;refresh() end);input.RefreshWorkbenchSearchHint=refresh;refresh();return hint\010end\010function addon:CreateWorkbenchSlider(parent,minimum,maximum,step,width)\010    local slider=CreateFrame(\"Slider\",nil,parent);slider:SetOrientation(\"HORIZONTAL\");slider:SetSize(width or 112,12)\010    slider:SetMinMaxValues(minimum,maximum);slider:SetValueStep(step);if slider.SetObeyStepOnDrag then slider:SetObeyStepOnDrag(true) end\010    local track=slider:CreateTexture(nil,\"BACKGROUND\");track:SetPoint(\"LEFT\",0,0);track:SetPoint(\"RIGHT\",0,0);track:SetHeight(3);track:SetColorTexture(.3,.32,.34,1)\010    local thumb=slider:CreateTexture(nil,\"ARTWORK\");thumb:SetSize(7,12);thumb:SetColorTexture(.78,.8,.82,1);slider:SetThumbTexture(thumb)\010    return slider\010end\010\010-- Flat, narrow tracks and proportional rectangular thumbs follow the modern\010-- Details/Plater convention. These frames belong to RM, without a provider.\010function addon:CreateWorkbenchScrollBar(parent,orientation)\010    local horizontal=orientation=='HORIZONTAL'\010    local bar=CreateFrame('Slider',nil,parent);bar:SetOrientation(orientation or 'VERTICAL');bar:SetSize(horizontal and 160 or 10,horizontal and 10 or 160)\010    bar:SetMinMaxValues(0,0);bar:SetValueStep(1);bar:EnableMouseWheel(true)\010    local track=bar:CreateTexture(nil,'BACKGROUND');track:SetAllPoints(bar);track:SetColorTexture(.08,.08,.08,.85)\010    local thumb=bar:CreateTexture(nil,'ARTWORK');thumb:SetSize(horizontal and 30 or 8,horizontal and 8 or 30);thumb:SetColorTexture(.48,.48,.48,.9);bar.thumbTexture=thumb\010    for _,entry in ipairs({{'back','up',-1},{'forward','down',1}}) do\010        local direction=entry[3];local control=self:CreateWorkbenchIconButton(bar,entry[2]);control:SetSize(10,10);control.icon:SetSize(9,9);bar[entry[1]]=control;if horizontal then control.icon:SetRotation(math.pi/2) end\010        control:SetPoint(horizontal and (direction<0 and 'RIGHT' or 'LEFT') or (direction<0 and 'BOTTOM' or 'TOP'),bar,\010            horizontal and (direction<0 and 'LEFT' or 'RIGHT') or (direction<0 and 'TOP' or 'BOTTOM'),0,0)\010        addon:SetUIScript(control,'OnClick',function() bar:SetValue((bar:GetValue() or 0)+direction*40) end)\010    end\010    local function placeThumb()\010        local length=horizontal and bar:GetWidth() or bar:GetHeight()\010        local travel=math.max(0,length-(bar.thumbLength or 18))\010        local fraction=(bar.scrollRange or 0)>0 and bar:GetValue()/bar.scrollRange or 0\010        thumb:ClearAllPoints();thumb:SetPoint(horizontal and 'LEFT' or 'TOP',horizontal and travel*fraction or 0,horizontal and 0 or -travel*fraction)\010    end\010    -- Keep repaint owned by this control, independently of consumer callbacks.\010    -- Reflow can clamp the native value before its value-change hook runs.\010    local nativeSetValue=bar.SetValue\010    function bar:SetValue(value)\010        nativeSetValue(self,value)\010        placeThumb()\010    end\010    local drag=CreateFrame('Button',nil,bar);bar.thumbButton=drag;drag:SetAllPoints(thumb)\010    addon:SetUIScript(drag,'OnMouseDown',function(_,button)\010        if button~='LeftButton' or not GetCursorPosition then return end\010        local x,y=GetCursorPosition();bar.dragStart={position=horizontal and x or y,value=bar:GetValue()}\010    end)\010    local function stop() bar.dragStart=nil end\010    addon:SetUIScript(drag,'OnMouseUp',stop);addon:SetUIScript(drag,'OnHide',stop)\010    addon:SetUIScript(drag,'OnUpdate',function()\010        local start=bar.dragStart;if not start then return end\010        if IsMouseButtonDown and not IsMouseButtonDown('LeftButton') then stop();return end\010        local x,y=GetCursorPosition();local delta=((horizontal and x or y)-start.position)/bar:GetEffectiveScale()\010        local length=horizontal and bar:GetWidth() or bar:GetHeight();local travel=math.max(1,length-(bar.thumbLength or 18))\010        bar:SetValue(start.value+(horizontal and delta or -delta)*(bar.scrollRange or 0)/travel)\010    end)\010    drag:EnableMouseWheel(true);addon:SetUIScript(drag,'OnMouseWheel',function(_,delta) bar:SetValue(bar:GetValue()-delta*40) end)\010    -- These regions cover only the empty track around the owned thumb.\010\010    for _,entry in ipairs({{'pageBack',-1},{'pageForward',1}}) do\010        local control=CreateFrame('Button',nil,bar);bar[entry[1]]=control\010        if horizontal then\010            control:SetPoint('TOP',bar,'TOP');control:SetPoint('BOTTOM',bar,'BOTTOM')\010            control:SetPoint('LEFT',entry[2]<0 and bar or thumb,entry[2]<0 and 'LEFT' or 'RIGHT')\010            control:SetPoint('RIGHT',entry[2]<0 and thumb or bar,entry[2]<0 and 'LEFT' or 'RIGHT')\010        else\010            control:SetPoint('LEFT',bar,'LEFT');control:SetPoint('RIGHT',bar,'RIGHT')\010            control:SetPoint('TOP',entry[2]<0 and bar or thumb,entry[2]<0 and 'TOP' or 'BOTTOM')\010            control:SetPoint('BOTTOM',entry[2]<0 and thumb or bar,entry[2]<0 and 'TOP' or 'BOTTOM')\010        end\010        local direction=entry[2]\010        addon:SetUIScript(control,'OnMouseDown',function(_,button)\010            if button=='LeftButton' then bar:SetValue((bar:GetValue() or 0)+direction*(bar.pageSize or 1)) end\010        end)\010        control:EnableMouseWheel(true);addon:SetUIScript(control,'OnMouseWheel',function(_,delta) bar:SetValue((bar:GetValue() or 0)-delta*40) end)\010    end\010    addon:SetUIScript(bar,'OnMouseWheel',function(_,delta) bar:SetValue((bar:GetValue() or 0)-delta*40) end)\010    addon:SetUIScript(bar,'OnEnter',function() thumb:SetColorTexture(.7,.7,.7,1) end)\010    addon:SetUIScript(bar,'OnLeave',function() thumb:SetColorTexture(.48,.48,.48,.9) end)\010    function bar:UpdateExtent(content,visible)\010        self.extentRevision=(self.extentRevision or 0)+1;local revision=self.extentRevision\010        self.pageSize=math.max(1,visible)\010        local range=math.max(0,content-visible);self.scrollRange=range;self:SetMinMaxValues(0,range)\010        if self.extentRevision~=revision then return end\010        self:SetValue(math.min(self:GetValue() or 0,range))\010        if self.extentRevision~=revision then return end\010        local length=horizontal and self:GetWidth() or self:GetHeight()\010        local size=math.min(length,math.max(18,length*math.min(1,visible/math.max(1,content))))\010        if size~=self.thumbLength then\010            self.thumbLength=size;if horizontal then thumb:SetWidth(size) else thumb:SetHeight(size) end\010        end\010        placeThumb();if range>0 then self:Show() else self.dragStart=nil;self:Hide() end\010    end\010    return bar\010end\010function addon:CreateWorkbenchScrollFrame(parent)\010    local scroll=CreateFrame('ScrollFrame',nil,parent)\010    local bar=self:CreateWorkbenchScrollBar(scroll,'VERTICAL');scroll.workbenchBar=bar\010    bar:SetPoint('TOPLEFT',scroll,'TOPRIGHT',4,-10);bar:SetPoint('BOTTOMLEFT',scroll,'BOTTOMRIGHT',4,10)\010    addon:SetUIScript(bar,'OnValueChanged',function(_,value)\010        local current=scroll.GetVerticalScroll and scroll:GetVerticalScroll() or scroll.lastAppliedOffset\010        if current==nil or math.abs(current-value)>.001 then scroll.lastAppliedOffset=value;scroll:SetVerticalScroll(value) end\010    end)\010    function scroll:UpdateWorkbenchScroll()\010        local child=self:GetScrollChild();if not child then return end\010        bar:UpdateExtent(child:GetHeight(),self:GetHeight())\010    end\010    addon:SetUIScript(scroll,'OnScrollRangeChanged',function() scroll:UpdateWorkbenchScroll() end)\010    addon:SetUIScript(scroll,'OnSizeChanged',function() scroll:UpdateWorkbenchScroll() end)\010    scroll:EnableMouseWheel(true);addon:SetUIScript(scroll,'OnMouseWheel',function(_,delta) bar:SetValue((bar:GetValue() or 0)-delta*40) end)\010    return scroll\010end\010\010-- A single native scroll host for measured RM groups. Content ownership and\010-- its callback lease are detached before recycling, so old windows cannot\010-- resize a root that has already been borrowed by another editor.\010function addon:CreateWorkbenchGroupViewport(parent)\010    local scroll=self:CreateWorkbenchScrollFrame(parent)\010    local empty=CreateFrame('Frame',nil,scroll);empty:SetSize(1,1);scroll:SetScrollChild(empty)\010    function scroll:ReleaseConditionContent()\010        local root,lease,finish=self.contentWidget,self.contentLease,self.originalLayoutFinished\010        self.contentWidget=nil;self.contentLease=nil;self.originalLayoutFinished=nil;self:SetScrollChild(empty)\010        if root and root.rmLease==lease and root.rmActive then root.LayoutFinished=finish;addon:ReleaseConditionWidget(root) end\010        self:UpdateWorkbenchScroll()\010    end\010    function scroll:SetConditionContent(root)\010        if root then assert(root.rmWidget and root.rmActive and root.DoLayout,'native-condition-group-required') end\010        if self.contentWidget==root and (not root or self.contentLease==root.rmLease) then if root then root:SetWidth(self:GetWidth()) end;return end\010        self:ReleaseConditionContent();if not root then return end\010        self.contentWidget=root;local