oint('TOPLEFT',12,-66);d.scroll:SetSize(852,152)\010        d.input:SetMaxLetters(1048576);d.input:SetSize(828,152)\010        d.review=self:CreateWorkbenchButton(d.frame,L['Review import'],116);d.review:SetPoint('TOPLEFT',12,-226)\010        d.copy:ClearAllPoints();d.copy:SetPoint('LEFT',d.review,'RIGHT',8,0);d.clear:ClearAllPoints();d.clear:SetPoint('LEFT',d.copy,'RIGHT',6,0)\010        d.status=d.frame:CreateFontString(nil,'OVERLAY','GameFontHighlightSmall');d.status:SetPoint('TOPLEFT',12,-258);d.status:SetSize(852,44);d.status:SetJustifyH('LEFT');d.status:SetWordWrap(true)\010        d.body=CreateFrame('Frame',nil,d.frame);d.body:SetPoint('TOPLEFT',4,-306);d.body:SetSize(872,344);d.form=self:CreateSettingsForm(d.body)\010        d.apply:SetText(L['Apply import']);d.apply:SetWidth(116);d.apply:ClearAllPoints();d.apply:SetPoint('BOTTOMRIGHT',-124,28)\010        d.cancel:SetWidth(104);d.cancel:ClearAllPoints();d.cancel:SetPoint('BOTTOMRIGHT',-12,28)\010    end\010    d.serial=(d.serial or 0)+1;local serial=d.serial;local token=p.generation;d.choices={};d.plan=nil;d.bundle=nil;d.lastRows={};d.lastRequirements={};d.exportSource=source;d.include=true;d.includeDependencies:SetChecked(true);if source and id then d.includeDependencies:Enable() else d.includeDependencies:Disable() end\010    local profile,global=self.db.profile,self.db.global\010    local function valid() return d.serial==serial and d.frame:IsShown() and p.active and self.db.profile==profile and self.db.global==global and (options.valid and options.valid() or not options.valid and p:Valid(token)) end\010    d.OwnerValid=valid\010    d.chrome:SetContext(L['Function dependency bundle'],L['Import/Export'],source and source.name or id or L['Functions'])\010    local function status(message) d.status:SetText(message or '');d.status:SetTextColor(1,.75,.35) end\010    function d:Invalidate()\010        self.plan=nil;self.apply:Disable();status(L['Review the complete bundle before applying an import. Imported Lua