m.width=math.max(240,d.body:GetWidth()-34);form.child:SetWidth(form.width)\010        for index,row in ipairs(d.lastRows) do\010            form:Heading((row.kind=='condition' and L['Condition'] or L['Function'])..': '..row.originalName)\010            form:Text(L['Original identifier']..': '..row.originalID)\010            local choiceKey=row.choiceKey or row.kind..':'..row.originalID\010            local choice=d.choices[choiceKey] or {};d.choices[choiceKey]=choice\010            local function changed() d:Invalidate() end\010            form:Choice('action_'..index,L['Conflict action'],choice.action or row.action,actions,function(value) choice.action=value;changed();d:Review() end)\010            form:Edit('destination_'..index,L['Destination identifier'],choice.id or row.destinationID,nil,function(value) choice.id=value;changed() end)\010            if row.kind=='function' then form:Edit('name_'..index,L['Imported name'],choice.name or row.source.name or row.originalName,nil,function(value) choice.name=value;changed() end) end\010            form:Button('review_source_'..index,L['Review source'],function() addon:ShowFunctionBundleSource(d,row,valid) end)\010            if row.existing then form:Button('compare_'..index,L['View Changes'],function() addon:ShowWorkbenchDraftChanges(d,'profile',row.existing,row.source,valid) end) end\010            if #row.effects>0 then form:Text(L['Existing dependents']..': '..table.concat(row.effects,', ')) end\010            if row.source.disabled then form:Text(L['This imported definition is disabled. Its dependents remain unavailable.']) end\010        end\010        if #d.lastRequirements>0 then form:Heading(L['Required functions']) end\010        for _,requirement in ipairs(d.lastRequirements) do local text=form:Text((requirement.name or requirement.id)..' ['..requirement.id..'] \226\128\148 '..requirement.status);if requirement.status~='available' and requirement.status~='included' then text:SetTextColor(1,.35,.35) end end\010        if #d.lastRows==0 then form:Text(L['Paste a bundle above, then review its original names, destinations and required functions.']) end\010    end)\010    addon:SetUIScript(d.includeDependencies,'OnClick',function() if valid() then d.include=not d.include;d.includeDependencies:SetChecked(d.include);d:Export() end end)\010    addon:SetUIScript(d.input,'OnTextChanged',function(_,user) if user and valid() then d:Invalidate() end;d.scroll:UpdateWorkbenchScroll() end)\010    addon:SetUIScript(d.input,'OnSizeChanged',function() d.scroll:UpdateWorkbenchScroll() end)\010    addon:SetUIScript(d.input,'OnCursorChanged',function(_,_,y,_,height) local top=-y;local bar=d.scroll.workbenchBar;d.scroll:UpdateWorkbenchScroll();if top<bar:GetValue() then bar:SetValue(top) elseif top+height>bar:GetValue()+d.scroll:GetHeight() then bar:SetValue(top+height-d.scroll:GetHeight()) end end)\010    d.input:EnableMouseWheel(true);addon:SetUIScript(d.input,'OnMouseWheel',function(_,delta) local bar=d.scroll.workbenchBar;bar:SetValue(bar:GetValue()-delta*40) end)\010    addon:SetUIScript(d.review,'OnClick',function() d:Review() end)\010    addon:SetUIScript(d.copy,'OnClick',function() if valid() then d.input:SetFocus();d.input:HighlightText(0,-1) end end)\010    addon:SetUIScript(d.clear,'OnClick',function() if valid() then d.input:SetText('');d.input:SetFocus();d.input:SetCursorPosition(0);d.scroll.workbenchBar:SetValue(0);d.choices={};d.plan=nil;d.bundle=nil;d.lastRows={};d.lastRequirements={};d:Invalidate();d.form:Draw() end end)\010    function d:Hide() self.frame:Hide() end\010    addon:SetUIScript(d.cancel,'OnClick',function() d:Hide() end);addon:SetUIScript(d.close,'OnClick',function() d:Hide() end)\010    addon:SetUIScript(d.frame,'OnHide',function() d.input:ClearFocus();if d.sourceReview then d.sourceReview:Hide() end;d.form:Release();if options.onClose then options.onClose() end end)\010    addon:SetUIScript(d.apply,'OnClick',function()\010        if not valid() then return end\010        local pending=false;for _,record in ipairs(d.form.edits) do if record.dirty then pending=true end end\010        if pending or d.reviewedText~=d.input:GetText() then d:Review();return end\010        if not d.plan or not d.plan.valid then return end\010        if InCombatLockdown and InCombatLockdown() then status(L['Leave combat before applying these settings.']);return end\010        local plan=d.plan;local ok,why=addon:ApplyFunctionBundleImport(plan)\010        if not ok then d:Invalidate();status(problemText(why));return end\010        local root;for _,row in ipairs(plan.rows) do if row.originalID==plan.bundle.root.id and row.kind==plan.bundle.root.kind then root=row.destinationID end end\010        d.frame:Hide();if options.onApplied then options.onApplied(root) else if p.inlineFunction then p.inlineFunction:Close() end;p:DiscardSettingsDraft();p.newFunctionID=nil;p.newFunctionSource=nil;p.functionID=root;p.functionSource='custom';p:Draw() end\010    end)\010    p.cleanups[#p.cleanups+1]=function() if d.serial==serial then d.frame:Hide() end end\010    addon:SetUIScript(d.frame,'OnUpdate',function(...) if d.chromeUpdate then d.chromeUpdate(...) end;if d.frame:IsShown() and not valid() then d.frame:Hide() end end)\010    d.frame:SetFrameLevel(p.frame:GetFrameLevel()+250);d.frame:Show();d:Export();if options.text then d.input:SetText(options.text);d:Review() end;addon:RegisterWindowForEscape(d)\010    local briefs=self:TransferHelpBriefs();briefs.review=L['Help.Transfers.bundle_review'];briefs.includeDependencies=L['Help.Transfers.bundle_dependencies']\010    local sourceEvidence=self:CopySettingsData(source)\010    self:BindTransferHelp(d,{heading=L['Function dependency bundle'],owner=source and source.name or id,brief=L['Help.Transfers.bundle_brief'],sections={{title=L['Import/Export'],text=L['Help.Transfers.bundle']},{title=L['Review source'],text=L['Help.Transfers.source_review']}},briefs=briefs,valid=function() return d.exportSource==source and addon:SettingsDataEqual(source,sourceEvidence) end},valid)\010    return d\010end\010function addon:ShowConditionFunctionBundleTransfer(parent,update,key,source,incomingText)\010    local owner=parent.rmConditionOwner;if not owner or not parent.form then return end\010    local function valid() return addon:CanResumeCustomConditionDialog(parent,owner) end\010    local dialog\010    dialog=self:ShowFunctionBundleTransfer(parent.form,key and key~='' and key or 'IMPORTED_CONDITION',source,{\010        kind='condition',text=incomingText,valid=valid,\010        onClose=function()\010            if dialog then owner.widgets[dialog]=nil;dialog.rmConditionOwner=nil end\010            if valid() then parent:Show() end\010        end,\010        onApplied=function(identifier) if valid() then parent:Close();update(identifier) end end})\010    if not dialog then return end\010    dialog.rmConditionOwner=owner;owner.widgets[dialog]=true;parent:HideForChild();return dialog\010end\010",stages={["c192"]={{at=14770,remove=809,previous=texts[63]},{at=4792,remove=424,previous=texts[64]},{at=3897,remove=619,previous=texts[1]}},["help"]={},["six"]={{at=14770,remove=809,previous=texts[63]},{at=4792,remove=424,previous=texts[64]},{at=3897,remove=619,previous=texts[1]}},}}
rows["UI/help.lua"]={current="local addon_name,addon=...\010local L=LibStub('AceLocale-3.0'):GetLocale(addon_name)\010local function section(title,text) return {title=title,text=text} end\010-- Help owns a document lease, never an edit/history transaction.\010local helpRequest=0\010---@return boolean, any\010local function callHelpContext(context,callback,...)\010    if addon.Diagnostics then return addon.Diagnostics:Call(context or {module='help',operation='render'},callback,...) end\010    return pcall(callback,...)\010end\010local function callHelp(callback,...) return callHelpContext(nil,callback,...) end\010local function validHelp(valid)\010    if not valid then return true end\010    local ok,current=callHelp(valid);return ok and current==true\010end\010function addon:GuardWorkbenchHelp(valid,callback)\010    return function(...) if validHelp(valid) then return callback(...) end end\010end\010function addon:OpenWorkbenchHelp(request)\010    local valid=request.valid;local previous=helpRequest\010    if not validHelp(valid) or previous~=helpRequest then return end\010    helpRequest=helpRequest+1;local token=helpRequest\010    local function current()\010        if token~=helpRequest then return false end\010        local live=validHelp(valid);return live and token==helpRequest\010    end\010    local function failed()\010        local d=self.helpWindow\010        if token==helpRequest and d then d:ReleaseMount();if token==helpRequest then d.frame:Hide() end end\010    end\010    if not current() then failed();return end\010    local sections=request.sections or {}\010    if type(sections)=='function' then local ok,value=callHelp(sections);if not ok or not current() then failed();return end;sections=value end\010    if type(sections)~='table' or not current() then failed();return end\010    local heading=request.heading or L['Help']\010    -- Capture only diagnostic scalars from the accepted subject, per request.\010    local metadata=request.renderContext\010    local context={module='help',operation='render',customCode=type(metadata)=='table' and rawget(metadata,'customCode')==true,\010        conditionTag=type(metadata)=='table' and rawget(metadata,'conditionTag') or nil}\010    local document=self:ShowWorkbenchHelp(heading,sections,request.owner,{current=current,render=request.render,renderContext=context})\010    if not document or not current() then return end\010    local handle={frame=document.frame,heading=heading,sections=sections}\010    function handle:Hide()if token==helpRequest then document:Hide()end end\010    return handle\010end\010function addon:WorkbenchWindowHelp()\010    return {\010        section(L['Navigation'],L['Help.Window.navigation']),\010        section(L['Scale'],L['Help.Window.scale']),\010        section(L['Window controls'],L['Help.Window.controls']),\010        section(L['Apply / Discard'],L['Help.Window.drafts']),\010        section(L['Help'],L['Help.Window.help']),\010    }\010end\010-- Descriptors are held only by their owning control and retired on pool reuse.\010function addon:BindWorkbenchHelp(control,descriptor)\010    if control.rmHelpBinding then control.rmHelpBinding.clear() end\010    local binding={};control.rmHelpBinding=binding\010    local enter,leave=control:GetScript('OnEnter'),control:GetScript('OnLeave')\010    local function current()return control.rmHelpBinding==binding and validHelp(descriptor.valid) and control.rmHelpBinding==binding end\010    local function onEnter(...)\010        if not current() then return end\010        if enter then enter(...) end\010        if not current() or not descriptor.brief or not GameTooltip then return end\010        if GameTooltip:IsOwned(control) then if descriptor.brief~=control.tooltip then GameTooltip:AddLine(descriptor.brief,1,1,1,true) end\010        else GameTooltip:SetOwner(control,'ANCHOR_RIGHT');GameTooltip:SetText(descriptor.brief,1,1,1,1,true) end\010        GameTooltip:Show()\010    end\010    local function onLeave(...)\010        if not current() then return end\010        if leave then leave(...) end\010        if current() and GameTooltip and GameTooltip:IsOwned(control) then GameTooltip:Hide() end\010    end\010    addon:SetUIScript(control,'OnEnter',onEnter);local installedEnter=control:GetScript('OnEnter')\010    addon:SetUIScript(control,'OnLeave',onLeave);local installedLeave=control:GetScript('OnLeave')\010    function binding.clear()\010        if control.rmHelpBinding~=binding then return end\010        control.rmHelpBinding=nil\010        if control:GetScript('OnEnter')==installedEnter then control:SetScript('OnEnter',enter) end\010        if control:GetScript('OnLeave')==installedLeave then control:SetScript('OnLeave',leave) end\010        if GameTooltip and GameTooltip:IsOwned(control) then GameTooltip:Hide() end\010    end\010    return binding.clear\010end\010function addon:GetProfileOptionHelp()\010    return {\010        {id='activate',title=L['Activate profile'],text=L['Help.Profiles.activate']},\010        {id='copy',title=L['Copy from profile'],text=L['Help.Profiles.copy']},\010        {id='reset',title=L['Reset current profile'],text=L['Help.Profiles.reset']},\010        {id='delete',title=L['Delete'],text=L['Help.Profiles.delete']},\010        {id='new_name',title=L['New profile name'],text=L['Help.Profiles.new_name']},\010        {id='collections',title=L['New / Duplicate / Import / Compare'],text=L['Help.Profiles.collections']},\010    }\010end\010function addon:GetIntegrationOptionHelp()\010    return {\010        {id='lua_editor',title=L['Editor'],text=L['Help.Integrations.lua_editor']},\010        {id='lua_line_numbers',title=L['Show line numbers'],text=L['Help.Integrations.lua_line_numbers']},\010        {id='optional_addons',title=L['Optional addons'],text=L['Help.Integrations.optional_addons']},\010        {id='preview_masque',title=L['Skin preview buttons with Masque'],text=L['Help.Integrations.preview_masque']},\010        {id='questie_enabled',title=L['Enable Questie integration'],text=L['Help.Integrations.questie_enabled']},\010        {id='native_highlighting',title=L['Syntax highlighting'],text=L['Help.Integrations.native_highlighting']},\010    }\010end\010function addon:WorkbenchInteractionHelp(kind)\010    local result={section(L['Names and details'],L['Click a name to rename it. Clear a custom step name to restore its action name. Click a collapsed title to show its summary. Click action or condition text to open its details; the double chevron returns from fields to the summary.'])}\010    if kind=='condition' then\010        result={section(L['Choose and edit'],L['Click a condition type to search or browse categories. Dismissing the picker or choosing the same type keeps its fields. Click the condition summary to edit its fields. The chevron switches between name only and summary; the double chevron closes the fields.']),\010            section(L['Groups and toggles'],L['If / Unless toggles negation. Enabled / Disabled keeps the saved fields while skipping evaluation. All / Any changes AND / OR. Click a group name to rename it; the branch icon hides or shows its children. Gray descendants cannot be reached.']),\010            section(L['Move, copy and remove'],L['Drag a card into one highlighted gap, or use the left-side Up / Down arrows. Hold Ctrl when starting a drag to carry the card and all following siblings. Groups always carry their children. Unavailable moves are gray. Ctrl-click or Shift-click selects several cards for grouping; dragging an existing selection moves that selection. Duplicate copies a card; Split group removes its wrapper; the red trash can deletes it. Add condition and Add group append when clicked or insert where dropped.'])}\010    else\010        result[#result+1]=section(L['Move, copy and remove'],L['Drag one card into a highlighted gap; hold Ctrl when starting the drag to carry that card and all following siblings. A branch always carries its children. Use Up / Down on the left to move one card. Duplicate copies the card and the red trash can deletes it. Cooldowns are independent, so they have no move arrows.'])\010        result[#result+1]=section(L['Conditions and state'],kind=='branch' and L['Click the guard text to edit the branch condition. Evaluate uses that condition; Always true / Always false skips it. False is left and red; True is right and green. The branch icon hides both arms without changing them. Click True or False to fold only that arm; its hidden count remains visible. Gray cards in a forced arm are unreachable.'] or L['Click condition text to edit when this card can run. Enabled / Disabled preserves the card while switching its participation. Actions also require known or carried actions, usable resources, cooldown readiness and valid range.'])\010        if kind=='cooldown' then result[#result+1]=section(L['Highlight effects'],L['Click the action to edit its type, spell or item. The leading icon previews the effect. Effect selects a style; Magnification changes its size. Click the swatch or edit RGBA on the 0\226\128\1471 scale. Arrows adjust position; V / H show offsets. Default restores profile values. Sound selection and Play preview an audible reminder.']) end\010    end\010    result[#result+1]=section(L['Help and saving'],L['The question mark explains the visible controls. With condition fields open, it adds that condition\226\128\153s help below the fields. Undo / Redo affect the draft. Apply saves; Discard or Cancel abandons draft changes. Red borders mark invalid or incomplete data.'])\010    return result\010end\010function addon:WorkbenchPageHelp(topic)\010    if topic=='Functions' then return {\010        section(L['Using this page'],L['Search helpers by name or description, then filter Built In / Custom and namespace. Packaged helpers use the same read-only pane. Duplicate creates an editable custom copy.']),\010        section(L['Namespace'],L['Choose an existing namespace from the suggestions or type a new dotted namespace. Built In namespaces follow source files; custom namespaces are implied by saved functions and need no separate maintenance.']),\010        section(L['Name'],L['Function names use letters, numbers and underscores, beginning with a letter or underscore. The code signature shows the qualified namespace.name used by callers.']),\010        section(L['Arguments and returns'],L['Click an Arguments or Returns heading to collapse or expand it. + Argument and + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and Nullable document accepted values; Description explains each input or result. Lua can return several ordered results. Return rows describe those results; moving them does not rewrite return statements. Reordering a saved function warns because positional callers may need changes; RM does not rewrite call sites.']),\010        section(L['Editing code'],L['Undo and Redo edit the Lua body. Reset restores the saved body or new-function template and can be undone. Check syntax executes no custom Lua. Apply saves the body and metadata together; Discard abandons the draft. Leaving with changes offers Apply, Discard or Cancel.']),\010        section(L['Function dependencies'],L['Help.Functions.bindings']),\010        section(L['Import/Export'],L['Include custom function dependencies exports their source with the selected definition. Without it, the bundle records required helper identities and versions. Review source shows every imported Lua body. Resolve each original name and destination with Reuse, Replace or a new identifier. Apply import saves the complete reviewed bundle and can register imported Lua. Only apply code you trust.']),\010        section(L['Window controls'],L['Help.Window.controls'])} end\010    local description={\010        General=L['Configure recommendation timing, automatic switching, history, preview and profile highlight defaults. Labels are on the left. Checkboxes toggle options, sliders show numeric values, and fields validate before saving.'],\010        Conditions=L['Choose a category and search for a condition. Hidden removes it from pickers without deleting its definition. Switch Condition controls its availability for automatic rotation switching. Move To stages a category destination; its Apply button confirms the move. The assigned category opens category management. Sidebar arrows and dragging order entries. Page Apply saves the draft; Discard abandons edits to a saved entry. Custom conditions can be edited, duplicated or deleted.'],\010        Effects=L['Select an effect to edit its name, type and type-specific settings. The icon previews it live. Sequence sections edit animation, color, pulse or custom frames in order. Duplicate creates an independent effect. Drag a sequence card surface to reorder it; fields remain editable. New effects can be configured before naming. Apply saves the draft; Discard abandons edits to a saved entry. Import stages a validated replacement.'],\010        ItemSets=L['Choose an item set and edit its priority list. Global shares the set across profiles. Move arrows change item priority. Bind item set picks up an available item for placement on an action bar; The binding pill removes matching bound bar actions when unbinding, outside combat. Reset restores a packaged set. Search or drag items into reference fields. Apply saves settings; Discard abandons edits to a saved entry. Binding changes are explicit action-bar operations.'],\010        Announces=L['Expand an announcement to choose its action, event, channel and text. Spell fields search the catalog; exact rank limits matching to that rank. Enabled toggles the announcement. New opens a draft with Apply and Cancel. Audible replaces text with sound selection and Play. Duplicate, Import/Export and Compare are below the list; imports are validated and never execute code. Apply saves changes.'],\010        Profiles=L['Select a profile in the sidebar to inspect it, then Activate profile to switch. New and Duplicate open a named draft with Apply and Cancel. Import stages a validated new profile; Compare shows setting differences. Copy and Reset replace the active profile after confirmation; the red trash deletes an inactive profile.'],\010        About=L['Version, author, credits and project links are shown here. Click a link field to select its text for copying.'],\010        Rotations=L['Search or filter the rotation roster, then select a rotation. Blue Built In rotations use the same editor but remain read-only; Duplicate makes an editable copy. The name and Metadata describe the rotation. Switch condition selects when it applies. Use the Rotation and Cooldowns tabs to select the content below the switch condition. Cooldowns highlight independently of the ordered rotation.']}\010    description.Integrations=L['Help.Integrations.overview']\010    local result={section(L['Using this page'],description[topic] or L['Optional addon settings.'])}\010    if topic~='Profiles' and topic~='Rotations' and topic~='About' then result[#result+1]=section(L['Apply / Discard'],L['Edits stay in a draft until Apply. Discard abandons pending changes. Leaving with changes offers Apply, Discard or Cancel; Cancel keeps the page and draft open. Effect previews do not save changes. Action-bar binding operations are explicit and immediate.']) end\010    if topic=='General' and self.GetGeneralOptionHelp then for _,entry in ipairs(self:GetGeneralOptionHelp()) do result[#result+1]=entry end end\010    local authored={Conditions=self.GetDocument_layout_conditions_options_help,Effects=self.GetDocument_layout_effects_options_help,ItemSets=self.GetDocument_layout_itemsets_options_help,Announces=self.GetDocument_layout_announce_options_help,Profiles=self.GetProfileOptionHelp,Integrations=self.GetIntegrationOptionHelp}\010    if authored[topic] then for _,entry in ipairs(authored[topic](self)) do result[#result+1]=entry end end\010    if topic=='Rotations' then\010        result[#result+1]=section(L['Applies to'],L['Rotations belong to the active settings profile. New copies use Class, shared by your characters of that class; Metadata can change this to This character. Built In rotations show only for their declared class or universal use. Equal identifiers in different owners remain separate entries.'])\010        result[#result+1]=section(L['Recover unassigned rotations'],L['Older rotations without a recorded owner stay in an archive. Recover unassigned rotations opens the current profile and character archives for inspection or copying. Choose Class or This character to adopt one. Adoption preserves its identifier and evidence, refuses an existing destination, and leaves incomplete records unavailable until repaired.'])\010        result[#result+1]=section(L['Navigating rotations'],L['Diagram / List changes only the rotation view; General settings choose the default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms, False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in every view. Valid rotation bodies can contain up to 2,000 total steps; large workspaces reuse nearby card controls as you navigate. Folded branches intentionally hide their children.'])\010        for _,entry in ipairs(self:WorkbenchInteractionHelp('rotation')) do result[#result+1]=entry end\010    elseif topic=='Announces' then result[#result+1]=section(L['Editing settings'],L['Help.Announces.editing'])\010    elseif topic~='Profiles' and topic~='About' then result[#result+1]=section(L['Editing settings'],L['Press Enter or leave a text field to stage its value; Apply saves the draft. Inval