rows["UI/settings_announces.lua"]={current="local addon_name,addon=...\010local L=LibStub('AceLocale-3.0'):GetLocale(addon_name)\010local channels={{value='audible',text=L['Audible']},{value='partyraid',text=L['Raid or Party']},{value='party',text=L['Party Only']},{value='raidwarn',text=L['Raid Warning']},{value='gesture',text=L['Emote']},{value='local',text=L['Local Only']}}\010local types={{value='spell',text=L['Spell']},{value='pet',text=L['Pet Spell']},{value='item',text=L['Item']},{value='macro',text=L['Via Macro']}}\010function addon:BuildAnnounceSettings(p)\010    local store=p:SettingsData()\010    local values=store.profile.announces or {};local events={};for id,text in pairs(self.events or {}) do events[#events+1]={value=id,text=text} end;table.sort(events,function(a,b) return a.text<b.text end)\010    local refreshRoster\010    local function identifierFree(value,except)\010        if not self:IsValidMacroAnnouncementIdentifier(value) then return false end\010        for _,entry in ipairs(values) do if entry~=except and entry.type=='macro' and entry.identifier==value then return false end end\010        return true\010    end\010    local function nextIdentifier(seed)\010        seed=self:IsValidMacroAnnouncementIdentifier(seed) and seed or 'ANNOUNCE'\010        if identifierFree(seed) then return seed end\010        seed=seed:sub(1,48)\010        for i=2,#values+2 do local value=seed..'_'..i;if identifierFree(value) then return value end end\010    end\010    local function update(entry,key,value) entry[key]=value;if refreshRoster then refreshRoster(entry) end end\010    local function drawAction(prefix,entry)\010        p:Choice(prefix..'type',L['Action Type'],entry.type,types,function(v)\010            entry.type=v;entry.spell=nil;entry.item=nil;entry.ranked=nil\010            if v=='macro' then entry.event=nil;entry.identifier=nextIdentifier(entry.identifier)\010            else entry.identifier=nil;entry.event=entry.event or 'SUCCEEDED' end\010            p:Draw()\010        end)\010        if entry.type=='macro' then\010            p:Edit(prefix..'identifier',L['Identifier'],entry.identifier or '',function(value)if identifierFree(value,entry) then return value end end,function(v)update(entry,'identifier',v)end)\010            p:Text(L['Help.Announces.macro.brief'])\010            p:Text(string.format(L['Macro call: %s'],string.format('/run RM_Annouce(%q,\"mouseover\",nil)',entry.identifier or 'FOO')))\010        elseif entry.type=='item' then p:ItemSequence(prefix..'action',entry.item,function(v) update(entry,'item',v) end)\010        else p:Spell(prefix..'action',L['Spell'],entry.spell,entry.type=='pet' and BOOKTYPE_PET or addon.currentSpec,function(v) update(entry,'spell',v) end);p:InlineCheck(prefix..'action',prefix..'ranked',L['Use this exact spell rank'],entry.ranked,function(v) update(entry,'ranked',v) end) end\010        if entry.type~='macro' then p:Choice(prefix..'event',L['Event'],entry.event,events,function(v) update(entry,'event',v) end) end\010        local choices=channels\010        if entry.type=='macro' then choices={};for _,row in ipairs(channels)do choices[#choices+1]=row end;for _,row in ipairs({{value='say',text=L['Say']},{value='yell',text=L['Yell']},{value='whisper',text=L['Whisper']}})do choices[#choices+1]=row end end\010        if entry.announce=='emote' then local old=choices;choices={};for _,row in ipairs(old) do choices[#choices+1]=row end;choices[#choices+1]={value='emote',text=L['Custom emote']} end\010        p:Choice(prefix..'channel',L['Announce'],entry.announce,choices,function(v) update(entry,'announce',v);p:Draw() end)\010        if entry.type~='macro' and (entry.announce=='say' or entry.announce=='yell') then p:Text(L['Automatic Say and Yell are unavailable. Choose another announcement destination.']) end\010        if entry.announce=='gesture' then\010            p:Choice(prefix..'emote',L['Emote'],entry.emote,self.Platform:GetAnnouncementEmotes(),function(v) update(entry,'emote',v) end)\010            p:Check(prefix..'emote_target',entry.type=='macro' and L['Use supplied macro target ({{target}})'] or L['Use spell recipient ({{target}})'],entry.emote_target,function(v) update(entry,'emote_target',v) end)\010        elseif entry.announce=='audible' then p:Sound(prefix,L['Sound'],entry.announce_sound,function(v) update(entry,'announce_sound',v) end) else p:Edit(prefix..'text',L['Text'],entry.value or '',nil,function(v) update(entry,'value',v) end) end\010        p:Text(self:DescribeCondition(entry.conditions or {},self.currentSpec))\010        p:Button(prefix..'conditions',L['Edit announcement conditions'],function()\010            local generation=p.generation\010            local source=entry.conditions\010            local entryType=entry.type\010            local draft=self:CopySettingsData(source or {})\010            local baseline=self:CopySettingsData(draft)\010            local function current()\010                if not p:Valid(generation) or entry.type~=entryType or entry.conditions~=source or not self:SettingsDataEqual(source or {},baseline) then return false end\010                if p.newAnnounce==entry then return true end\010                for _,candidate in ipairs(store.profile.announces or {}) do if candidate==entry then return true end end\010                return false\010            end\010            self:ShowConditionEditor(nil,self.currentSpec,draft,function(applied)\010                if applied and current() then entry.conditions=next(draft) and draft or nil;p:Draw() end\010            end,current,{persistentOwner=true,announcement=true,announcementTarget=entry.type=='macro',title=L['Announcement conditions'],contextLabel=L['Announces']})\010        end)\010    end\010    local function itemInfo(value)\010        if type(value)=='string' then local set=(store.profile.itemsets or {})[value] or (store.global.itemsets or {})[value];local info=set and set.items and self:GetReferenceProvider('item').info(tonumber(set.items[1]) or self:GetReferenceProvider('item').resolve(set.items[1]));return {name=set and set.name or L['Item Set'],icon=info and info.icon} end\010        local id=type(value)=='table' and value[1] or value;return self:GetReferenceProvider('item').info(tonumber(id) or self:GetReferenceProvider('item').resolve(id))\010    end\010    local function entryInfo(entry)\010        if entry.type=='macro' then return {name=entry.identifier or L['Via Macro']} end\010        return entry.type=='item' and itemInfo(entry.item) or self.Platform:GetSpellInfo(entry.spell)\010    end\010    refreshRoster=function(entry)\010        local info=entryInfo(entry)\010        for i,value in ipairs(values) do if value==entry then p:UpdateRosterEntry(i,{text=self:SettingsNonempty(entry.name) or info and info.name or entry.type=='item' and L['Item data loading'] or L['Unknown spell'],icon=info and (info.icon or info.iconID),search=(entry.value or '')..' '..(entry.event or '')..' '..(entry.announce or '')});break end end\010    end\010    local entries={};for i,entry in ipairs(values) do local info=entryInfo(entry);entries[#entries+1]={value=i,text=self:SettingsNonempty(entry.name) or info and info.name or entry.type=='item' and L['Item'] or L['Unknown spell'],icon=info and (info.icon or info.iconID),search=(entry.value or '')..' '..(entry.event or '')..' '..(entry.announce or '')} end\010    if not values[p.selection] and not p.creating then p.selection=entries[1] and entries[1].value end\010    local function addAnnouncement()\010            local entry=p.newAnnounce;local field=entry.type=='item' and 'item' or 'spell'\010            local valid\010            if entry.type=='macro' then valid=identifierFree(entry.identifier,entry)\010            elseif entry.type=='item' then local item=entry.item;local set=type(item)=='string' and ((store.profile.itemsets or {})[item] or (store.global.itemsets or {})[item]);valid=type(item)=='table' and #item>0 or set and type(set.items)=='table'