rows["UI/settings_collections.lua"]={current="local addon_name,addon=...\010local invalidateDependencies=addon.InvalidateRotationDependencies\010if type(invalidateDependencies)~='function' then invalidateDependencies=nil end\010local L=LibStub('AceLocale-3.0'):GetLocale(addon_name)\010function addon:SettingsEntries(values)\010    local entries={};for id,value in pairs(values or {}) do if type(value)=='table' then entries[#entries+1]={value=id,text=type(value.name)=='string' and value.name or tostring(id)} end end\010    table.sort(entries,function(a,b) if a.text==b.text then return tostring(a.value)<tostring(b.value) end;return a.text<b.text end);return entries\010end\010function addon:SettingsNonempty(text) if type(text)=='string' and text:find('%S') then return text end end\010function addon:SettingsPositiveID(text) local n=tonumber(text);if n and n>0 and n==math.floor(n) then return n end end\010function addon:SettingsFlag(list,value,enabled)\010    for i=#list,1,-1 do if list[i]==value then table.remove(list,i) end end\010    if enabled then list[#list+1]=value end\010end\010function addon:SettingsContains(list,value) for _,entry in ipairs(list or {}) do if entry==value then return true end end;return false end\010function addon:SettingsOrderControls(p,prefix,list,i,changed)\010    local function move(destination) local value=table.remove(list,i);table.insert(list,destination,value);changed();p:Draw() end\010    p:Actions({{key=prefix..'top',text=L['Move to Top'],icon='chevron-double-down',enabled=i>1,action=function() move(1) end},\010        {key=prefix..'up',text=L['Move Up'],icon='up',enabled=i>1,action=function() move(i-1) end},\010        {key=prefix..'down',text=L['Move Down'],icon='down',enabled=i<#list,action=function() move(i+1) end},\010        {key=prefix..'bottom',text=L['Move to Bottom'],icon='chevron-double-down',enabled=i<#list,action=function() move(#list) end},\010        {key=prefix..'remove',text=L['Delete'],icon='trash',action=function() tab