rows["UI/settings_conditions.lua"]={current="local addon_name,addon=...\010local L=LibStub('AceLocale-3.0'):GetLocale(addon_name)\010local normalColor={.4,.7,1}\010local switchColor={1,.82,.25}\010function addon:BuildConditionSettings(p)\010    local store=p:SettingsData()\010    if p.mode=='categories' then return self:BuildConditionCategorySettings(p) end\010    local profile=store.profile;local groups=profile.condition_groups or {};local definitions=self:CopySettingsData(self.conditionDefinitions or {});local custom=store.global.custom_conditions or {}\010    for tag,definition in pairs(custom) do if not definitions[tag] then definitions[tag]={description=definition.description,icon=definition.icon} end end\010    local categories={{value='ALL',text=L['All'],icon=self:GetConditionCategoryIcon({id='ALL'})},{value='SWITCH',text=L['Switch'],icon=self:GetConditionCategoryIcon({id='SWITCH'})},{value='ANNOUNCEMENT',text=L['Announcement'],icon=self:GetConditionCategoryIcon({id='SWITCH'})}}\010    if p.category=='CUSTOM' or p.category=='BUILTIN' then p.conditionSource=p.category=='CUSTOM' and 'custom' or 'builtin';p.category='ALL' end\010    p.conditionSource=p.conditionSource or 'all'\010    local groupIndex\010    for i,group in ipairs(groups) do categories[#categories+1]={value=group.id,text=group.name or group.id,icon=self:GetConditionCategoryIcon(group)};if group.id==p.category then groupIndex=i end end\010    categories[#categories+1]={value='DEFAULT',text=L['Other'],icon=self:GetConditionCategoryIcon(nil)};if p.category~='ALL'  and p.category~='SWITCH' and p.category~='ANNOUNCEMENT' and p.category~='DEFAULT' and not groupIndex then p.category='ALL' end\010    local tags=self:listConditions(p.category,true,store);local entries={};local seen={}\010    if p.category=='ALL' then for tag in pairs(custom) do local exists=false;for _,value in ipairs(tags) do if value==tag then exists=true end end;if not exists then tags[#tags+1]=tag end end end\010    for _,tag in ipairs