rows["UI/settings_draft.lua"]={current="local addon_name,addon=...\010local invalidateDependencies=addon.InvalidateRotationDependencies\010if type(invalidateDependencies)~='function' then invalidateDependencies=nil end\010local L=LibStub('AceLocale-3.0'):GetLocale(addon_name)\010local function equal(a,b)\010    if type(a)~=type(b) then return false end;if type(a)~='table' then return a==b end\010    for key,value in pairs(a) do if not equal(value,b[key]) then return false end end;for key in pairs(b) do if a[key]==nil then return false end end;return true\010end\010function addon:SettingsDataEqual(a,b) return equal(a,b) end\010function addon:CopySettingsData(value,seen)\010    if type(value)~='table' then return value end;seen=seen or {};if seen[value] then return seen[value] end\010    local copy={};seen[value]=copy;for key,child in pairs(value) do copy[key]=self:CopySettingsData(child,seen) end;return copy\010end\010function addon:InstallSettingsDraft(p)\010    function p:CanAutoCreateCollection(scope,key)\010        return not self.emptyDismissed and not (self.draftBaseline and self.draftBaseline[scope] and next(self.draftBaseline[scope][key] or {}))\010    end\010    function p:CreationState()\010        return {effect=self.newEffect,announcement=self.newAnnounce,profileName=self.newProfileName,profileSource=self.profileSource,importProfile=self.importProfile,stockTarget=self.newStockTarget,itemSetName=self.newItemSetName,categoryName=self.newGroupName}\010    end\010    function p:IsCreationDirty()\010        if not self.creationUsedForNew then return false end\010        for _,record in ipairs(self.edits) do if record.dirty then return true end end\010        return not equal(self:CreationState(),self.creationBaseline or {})\010    end\010    function p:DiscardSettingsDraft()\010        if self.ClearSettingsHistory then self:ClearSettingsHistory() end\010        self.draft=nil;self.draftBaseline=nil;self.draftEffects=nil;self.newEffect=nil;self.newAnnounce=nil;