      for _,record in ipairs(self.edits) do if record.dirty then return true end end\010        for scope,keys in pairs(self.transactionKeys) do for _,key in ipairs(keys) do if not equal(self.draft[scope][key],self.draftBaseline[scope][key]) then return true end end end;return false\010    end\010    function p:SaveSettingsDraft()\010        if not self.draft then return true end\010        if not self:Valid(self.generation) then return false end\010        local stockUnchanged=false\010        for _,key in ipairs(self.transactionKeys.profile or {}) do if key=='stockTargets' then\010            if not addon.StockTargets.Validate(self.draft.profile.stockTargets) then self:Message(L['Complete the stock target settings before applying.']);return false end\010            stockUnchanged=equal(self.draft.profile.stockTargets,self.draftBaseline.profile.stockTargets)\010            if not stockUnchanged and not addon.StockSettings.CheckProfile(addon.db.profile) then self:Message(L['Invalid stock targets; data preserved.']);return false end\010        end end\010        for scope,keys in pairs(self.transactionKeys) do for _,key in ipairs(keys) do\010            if not (scope=='profile' and key=='stockTargets' and stockUnchanged) and not equal(addon.db[scope] and addon.db[scope][key],self.draftBaseline[scope][key]) then self:Message(L['Settings changed elsewhere. Cancel to reload them before applying.']);return false end\010        end end\010        local ownsEffects=false;for _,key in ipairs(self.transactionKeys.global or {}) do if key=='effects' then ownsEffects=true end end\010        if ownsEffects and self.draft.global.effects then\010            local names={};for id,effect in pairs(self.draft.global.effects) do\010                if not equal(effect,self.draftBaseline.global.effects and self.draftBaseline.global.effects[id]) and addon.IsValidEffectDefinition and not addon:IsValidEffectDefinition(effect) then self:Message(L['Complete the effect settings before applying