       if addon.ButtonFetch then addon:ButtonFetch() end\010        return true\010    end\010    function p:DraftActions()\010        if not self.transactionKeys or self.creationUsed then return end\010        self:CreationActions(function() if self:SaveSettingsDraft() then self:Draw() end end,function() self:DiscardSettingsDraft();self:Draw() end,true)\010        if self:IsSettingsDraftDirty() then self.fields.apply:Enable() else self.fields.apply:Disable() end;self.creationUsedForNew=false\010    end\010end\010",stages={["c192"]={{at=6090,remove=175,previous=texts[1]}},["macro"]={},["six"]={{at=6090,remove=175,previous=texts[1]}},}}
