not p:Valid(generation) or addon.db.profile~=profile or addon:GetScopedRotationCoordinator()~=coordinator or not coordinator or not coordinator:CheckReady() then return false end\010        local now=addon:GetRotationOwnerContext()\010        if not now or not context or now.class~=context.class or now.character~=context.character then return false end\010        return not recordToken or coordinator:TokenCurrent(recordToken)\010    end\010    local canReplace=reference and reference.kind=='custom' and recordToken~=nil\010    local options={valid=valid,canReplace=canReplace,selectedName=original and original.name or source and (source.body and source.body.name or source.nameKey or source.name),fallbackName=L['Imported rotation'],requirePreview=true,\010        help={heading=L['Import/Export Rotation'],brief=L['Help.Transfers.rotation_brief'],briefs=self:TransferHelpBriefs(),sections={{title=L['Import/Export'],text=L['Help.Transfers.rotation']},{title=L['Preview import'],text=L['Help.Transfers.rotation_preview']},{title=L['Applies to'],text=L['Copies belong to your Class unless This character is selected. Replacement keeps its original owner.']}}}}\010    options.originalName=function(text) local decoded=codec:Decode(text);local value=decoded and decoded.value;if type(value)=='table' then return value.body and value.body.name or value.nameKey or value.name end end\010    options.invalidate=function(d) if not valid() or dialog and (d~=dialog or d.options~=options) then return end;candidate=nil;session:Clear();d.apply:Disable();d.inspect:Disable();d.status:SetText(L['Text changed. Preview again before importing.']);if p.importPreview then p.importPreview.frame:Hide() end end\010    options.preview=function(d)\010        if not valid() then return end\010        local why;candidate,why=session:Stage(d.input:GetText());d.apply:Disable();d.inspect:Disable()\010        if not candidate then d.status:SetText(string.format(L['Import preview unavailable: %s'],why));return end