rows["UI/window.lua"]={current="local addon_name,addon=...\010local scaledWindows=setmetatable({}, {__mode='k'})\010local function scaleValue(value)\010    if type(value)~='number' or value~=value or value<.7 or value>1.3 then return 1 end\010    return math.floor(value*100+.5)/100\010end\010function addon:ApplyWorkbenchScale(frame)\010    if frame and frame.GetParent and frame:GetParent()==UIParent and frame.SetScale then\010        scaledWindows[frame]=true\010        frame:SetScale(scaleValue(self.db and self.db.global and self.db.global.uiScale))\010    end\010end\010function addon:ScaleWorkbenchWindows(value)\010    for frame in pairs(scaledWindows) do frame:SetScale(scaleValue(value)) end\010end\010\010-- Apply only to RM-owned dialogs. An opaque layer beneath their native art\010-- keeps overlapping configuration windows readable.\010function addon:MakeWindowOpaque(widget)\010    local frame=widget and (widget.frame or widget)\010    if not frame or not frame.CreateTexture then return end\010    if not frame.rmOpaqueBackground then\010        local background=frame:CreateTexture(nil,\"BACKGROUND\",nil,-8)\010        background:SetPoint(\"TOPLEFT\",frame,\"TOPLEFT\",8,-8)\010        background:SetPoint(\"BOTTOMRIGHT\",frame,\"BOTTOMRIGHT\",-8,8)\010        background:SetColorTexture(0.035,0.045,0.055,1)\010        frame.rmOpaqueBackground=background\010    end\010    if not widget.rmOpaqueActive and widget.frame then\010        local original=widget.OnRelease\010        local alpha=frame.GetAlpha and frame:GetAlpha() or 1\010        local previousScale=frame.GetScale and frame:GetScale() or 1\010        widget.rmOpaqueActive=true\010        widget.OnRelease=function(control,...)\010            frame.rmOpaqueBackground:Hide()\010            if frame.SetAlpha then frame:SetAlpha(alpha) end\010            if scaledWindows[frame] then scaledWindows[frame]=nil;frame:SetScale(previousScale) end\010            control.rmOpaqueActive=nil;control.OnRelease=original\010            if original then return original(control,...) end\010        end\010    end\010    if frame.SetAlpha then frame:SetAlpha(1) end\010    self:ApplyWorkbenchScale(frame)\010    frame.rmOpaqueBackground:Show()\010end\010\010-- One standard Escape target closes the frontmost RM window. Registering every\010-- dialog separately would let one Escape close its underlying configuration too.\010-- Frames remain private to their owners; pooled controls leave this registry.\010local escapeName=\"RotationMasterFrontmostDialog\"\010local escapeProxyName=\"RotationMasterEscapeTarget\"\010local dialogs={}\010local watcher\010local escapeProxy\010local function updateEscapeTarget()\010    local target,level,selected\010    for _,entry in ipairs(dialogs) do\010        if entry.frame:IsShown() then\010            local current=entry.frame:GetFrameLevel()\010            if not level or current>=level then target,level,selected=entry.frame,current,entry end\010        end\010    end\010    _G[escapeName]=target\010    if escapeProxy then\010        escapeProxy.target=selected;escapeProxy.syncing=true\010        if target then escapeProxy:Show() else escapeProxy:Hide() end\010        escapeProxy.syncing=false\010    end\010    if watcher then\010        if target then watcher:Show() else watcher:Hide() end\010    end\010end\010local function remove(entry)\010    for index,current in ipairs(dialogs) do\010        if current==entry then table.remove(dialogs,index);break end\010    end\010end\010local function present(entry)\010    remove(entry)\010    local level=entry.level\010    for _,current in ipairs(dialogs) do\010        if current.frame:IsShown() then level=math.max(level,current.frame:GetFrameLevel()+100) end\010    end\010    dialogs[#dialogs+1]=entry\010    entry.frame:SetFrameStrata(\"FULLSCREEN_DIALOG\")\010    entry.frame:SetFrameLevel(level)\010    entry.frame:Raise()\010    updateEscapeTarget()\010end\010function addon:RegisterWindowForEscape(widget)\010    local frame=widget and (widget.frame or widget);if frame then frame.rmEscapeOwner=widget end\010    if type(UISpecialFrames)~=\"table\" or not frame or not frame.GetScript or not frame.IsShown then return false end\010    if widget.rmEscapeEntry then present(widget.rmEscapeEntry);return true end\010    local registered=false\010    for _,name in pairs(UISpecialFrames) do if name==escapeProxyName then registered=true;break end end\010    if not registered then UISpecialFrames[#UISpecialFrames+1]=escapeProxyName end\010    if not escapeProxy then\010        -- CloseSpecialWindows hides its registered Frame directly. A private\010        -- proxy routes that request through the owner's guarded Hide method.\010        escapeProxy=CreateFrame('Frame',escapeProxyName,UIParent);_G[escapeProxyName]=escapeProxy\010        escapeProxy:EnableMouse(false);escapeProxy.syncing=true;escapeProxy:Hide();escapeProxy.syncing=false\010        escapeProxy:SetScript('OnHide',function()\010            if escapeProxy.syncing or escapeProxy.closing then return end\010            local target=escapeProxy.target\010            escapeProxy.closing=true\010            if target then\010                if type(target.widget.Hide)=='function' then target.widget:Hide() else target.frame:Hide() end\010            end\010            escapeProxy.closing=false;updateEscapeTarget()\010        end)\010    end\010    if not watcher then\010        watcher=CreateFrame(\"Frame\",nil,UIParent)\010        -- Native SetToplevel can raise any already-shown window on a child\010        -- click without OnShow. Observe only RM roots while they are open.\010        watcher:SetScript(\"OnUpdate\",updateEscapeTarget)\010    end\010    local entry={frame=frame,widget=widget,level=frame:GetFrameLevel(),strata=frame:GetFrameStrata()}\010    widget.rmEscapeEntry=entry\010    local onShow,onHide=frame:GetScript(\"OnShow\"),frame:GetScript(\"OnHide\")\010    local show=function(self,...)\010        addon:ApplyWorkbenchScale(self)\010        if onShow then onShow(self,...) end\010        if widget.rmEscapeEntry==entry then present(entry) end\010    end\010    local hide=function(self,...)\010        if onHide then onHide(self,...) end\010        updateEscapeTarget()\010    end\010    frame:SetScript(\"OnShow\",show);frame:SetScript(\"OnHide\",hide)\010    local release=widget.OnRelease\010    widget.OnRelease=function(control,...)\010        remove(entry);control.rmEscapeEntry=nil;control.OnRelease=release\010        if frame:GetScript(\"OnShow\")==show then frame:SetScript(\"OnShow\",onShow) end\010        if frame:GetScript(\"OnHide\")==hide then frame:SetScript(\"OnHide\",onHide) end\010        frame:SetFrameLevel(entry.level);frame:SetFrameStrata(entry.strata)\010        updateEscapeTarget()\010        if release then return release(control,...) end\010    end\010    present(entry)\010    return true\010end\010\010-- Child editors share the main workbench chrome without navigation tabs.\010function addon:EnableWorkbenchRightClickClose(frame)\010    if frame.rmRightClickWatcher then return end\010    local watcher=CreateFrame('Frame',nil,frame);frame.rmRightClickWatcher=watcher;watcher:EnableMouse(false)\010    local rightDown=IsMouseButtonDown and IsMouseButtonDown('RightButton') or false\010    local onShow=frame:GetScript('OnShow')\010    addon:SetUIScript(frame,'OnShow',function(...) rightDown=IsMouseButtonDown and IsMouseButtonDown('RightButton') or false;if onShow then onShow(...) end end)\010    addon:SetUIScript(watcher,'OnUpdate',function()\010        -- The existing visible-dialog observer also retires owner-bound Help.\010        local current=frame.rmHelpCurrent\010        if current then\010            local ok,live=pcall(current)\010            if (not ok or not live) and frame.rmHelpCurrent==current then frame:Hide();return end\010        end\010        local down=IsMouseButtonDown and IsMouseButtonDown('RightButton') or false\010        if down and not rightDown and frame:IsShown() then\010            local top=_G.RotationMasterFrontmostDialog;local focus\010            if GetMouseFoci then focus=GetMouseFoci()[1] elseif GetMouseFocus then focus=GetMouseFocus() end\010            local inside=false\010            for _=1,100 do if focus==frame then inside=true;break end;if not focus or type(focus.GetParent)~='function' then break end;focus=focus:GetParent() end\010            if inside and (not top or top==frame) then local owner=frame.rmEscapeOwner;if owner and type(owner.Hide)=='function' then owner:Hide() else frame:Hide() end end\010        end\010        rightDown=down\010    end)\010end\010-- Only the header receives movement gestures. Body EditBoxes and controls keep\010-- their native mouse selection, dragging and right-click behavior.\010function addon:EnableWorkbenchTitleDrag(frame)\010    if frame.rmWorkbenchTitleDrag then return frame.rmWorkbenchTitleDrag end\010    frame:SetMovable(true);frame:SetClampedToScreen(true)\010    local drag=CreateFrame('Frame',nil,frame);frame.rmWorkbenchTitleDrag=drag\010    drag:SetPoint('TOPLEFT',1,-1);drag:SetPoint('TOPRIGHT',-58,-1);drag:SetHeight(28)\010    drag:EnableMouse(true);drag:RegisterForDrag('LeftButton')\010    local function stop() drag.moving=nil;frame:StopMovingOrSizing() end\010    addon:SetUIScript(drag,'OnDragStart',function(_,button)\010        if button and button~='LeftButton' or not frame:IsShown() then return end\010        drag.moving=true;frame:StartMoving()\010    end)\010    addon:SetUIScript(drag,'OnDragStop',stop)\010    addon:SetUIScript(drag,'OnMouseUp',function(_,button) if button=='LeftButton' and drag.moving then stop() end end)\010    addon:SetUIScript(drag,'OnHide',stop)\010    return drag\010end\010function addon:CreateWorkbenchDialogChrome(frame,title,help)\010    local L=LibStub('AceLocale-3.0'):GetLocale(addon_name)\010    local chrome={};self:EnableWorkbenchRightClickClose(frame);chrome.drag=self:EnableWorkbenchTitleDrag(frame)\010    local function fill(parent,r,g,b)\010        local art=parent:CreateTexture(nil,'BACKGROUND');art:SetAllPoints(parent);art:SetColorTexture(r,g,b,1);return art\010    end\010    chrome.background=fill(frame,.075,.08,.085)\010    chrome.header=frame:CreateTexture(nil,'BACKGROUND');chrome.header:SetPoint('TOPLEFT',1,-1);chrome.header:SetPoint('TOPRIGHT',-1,-1);chrome.header:SetHeight(28);chrome.header:SetColorTexture(.12,.125,.13,1)\010    chrome.footer=CreateFrame('Frame',nil,frame);chrome.footer:SetPoint('BOTTOMLEFT',1,1);chrome.footer:SetPoint('BOTTOMRIGHT',-1,1);chrome.footer:SetHeight(20);fill(chrome.footer,.09,.10,.11)\010    for _,edge in ipairs({{'TOPLEFT','TOPRIGHT',true},{'BOTTOMLEFT','BOTTOMRIGHT',true},{'TOPLEFT','BOTTOMLEFT'},{'TOPRIGHT','BOTTOMRIGHT'}}) do\010        local art=frame:CreateTexture(nil,'BORDER');art:SetColorTexture(.33,.35,.37,1);art:SetPoint(edge[1],frame,edge[1]);art:SetPoint(edge[2],frame,edge[2]);if edge[3] then art:SetHeight(1) else art:SetWidth(1) end\010    end\010    local function text(parent,point,x,y,value)\010        local label=parent:CreateFontString(nil,'OVERLAY','GameFontHighlightSmall');label:SetPoint(point,x,y);label:SetText(value);return label\010    end\010    chrome.icon=frame:CreateTexture(nil,'ARTWORK');chrome.icon:SetSize(18,18);chrome.icon:SetPoint('TOPLEFT',12,-5);chrome.icon:SetTexture(addon.logoTexture)\010    title:ClearAllPoints();title:SetPoint('TOPLEFT',36,-5);title:SetHeight(18);title:SetJustifyV('MIDDLE');title:SetJustifyH('LEFT');title:SetWordWrap(false);title:SetMaxLines(1);title:SetTextColor(.94,.95,.96)\010\010    local getter=C_AddOns and C_AddOns.GetAddOnMetadata or GetAddOnMetadata\010    local version=type(getter)=='function' and getter(addon_name,'Version') or L['Development']\010    if not version or version:find('@',1,true) then version=L['Development'] end\010\010    local client=addon.Platform and addon.Platform.GetClientInfo and addon.Platform:GetClientInfo() or {}\010    local edition=({tbc=L['TBC'],