e end\010    end\010    assert(noop and valid)\010    f.env.MouseIsOver=function(frame) return frame==noop or frame==canvas.frame end\010    assert(not canvas:HoverTarget() and not noop.marker:IsShown(),'unchanged move was offered')\010    f.env.MouseIsOver=function(frame) return frame==valid or frame==canvas.frame end\010    assert(canvas:HoverTarget()==valid and valid.marker:IsShown())\010    canvas:Drop(noop.target);assert(shell.active.working.value[1].number==1 and not shell.active.session:HistoryState().canUndo)\010end)\010test('outside picker click dismisses without changing data while category clicks remain inside',function()\010    local f=fixture();local shell=f.addon:EditCondition(1,0,{type='NUMBER',number=4},function() end)\010    shell.canvas.cards[1].typeButton:Click();local picker=shell.canvas.cards[1].picker\010    local down=false;f.env.IsMouseButtonDown=function() return down end\010    f.env.MouseIsOver=function(frame) return frame==picker.host end\010    picker.host.scripts.OnUpdate();down=true;picker.host.scripts.OnUpdate();assert(picker.host:IsShown())\010    down=false;picker.host.scripts.OnUpdate();f.env.MouseIsOver=function() return false end;down=true;picker.host.scripts.OnUpdate()\010    assert(not picker.host:IsShown() and shell.active.working.number==4 and not shell.active.session:HistoryState().canUndo)\010end)\010test('named negated leaves keep the collapsed field summary as well as the editable wrapper label',function()\010    local f=fixture();local root={type='AND',value={{type='NOT',name='Emergency',value={type='NUMBER',number=37}}}}\010    local shell=f.addon:EditCondition(1,0,root,function() end);local card=shell.canvas.cards[2]\010    assert(card.model.negated and card.nameButton:GetText()=='Emergency' and card.typeButton:IsShown())\010    assert(card.summary:GetText():find('37',1,true),'named NOT replaced field details with another copy of its title')\010end)\010test('readonly condition view keeps common cards expandable while m