',value={}};for i=1,600 do root.value[i]={type='NUMBER',number=i} end\010    root.value[301]={type='AND',value={{type='NUMBER',number=1}}}\010    local shell=f.addon:EditCondition(1,0,root,function() end);local c=shell.canvas\010    c:Select({'value',301,'value',1},false,false);c.anchor={'value',1};c:Select({'value',600},true,true)\010    local selected=c:Selection();assert(#selected==600 and #selected[301]==2,'range kept a hidden descendant or lost an offscreen sibling')\010    assert(#c.cards<80 and #root.value==600)\010end)\010test('viewport reflow pins a focused offscreen name and retired Escape cannot affect its recycled control',function()\010    local f=fixture();local a=f.addon\010    local root={type='AND',value={}};for i=1,350 do root.value[i]={type='AND',value={},name='Entry '..i} end\010    local shell=a:EditCondition(1,0,root,function() end);local c=shell.canvas;c.frame.workbenchBar:SetValue(c.scene.cards[2].y)\010    local first=assert(viewportCard(shell,{'value',1}));first.nameButton:Click();first.name:SetText('Still typing');first.name.scripts.OnTextChanged(first.name,true)\010    local escape=first.name.scripts.OnEscapePressed;c.frame.workbenchBar:SetValue(c.frame.workbenchBar.scrollRange)\010    assert(first.token and first.name:HasFocus() and first.name:IsShown() and first.name:GetText()=='Still typing','scroll reflow hid a focused name')\010    first.name:ClearFocus();c.frame.workbenchBar:SetValue(c.frame.workbenchBar.scrollRange/2)\010    assert(first.token and first.model.path[2]~=1,'released name slot was not recycled')\010    first.nameButton:Click();assert(first.name:HasFocus());escape();assert(first.name:HasFocus(),'retired Escape cleared the newly leased name input')\010    assert(root.value[1].name=='Entry 1' and shell.active.working.value[1].name=='Still typing');shell.cancel:Click()\010end)\010test('offscreen child popup ownership pins its source fields until the original draft resumes',function()\010    local f=fixture();local a=f.addon;local root={type='AND',value={}};for i=1,350 do root.value[i]={type='NUMBER',number=i} end\010    local shell=a:EditCondition(1,0,root,function() end);local c=shell.canvas;c.frame.workbenchBar:SetValue(c.scene.cards[2].y)\010    local first=assert(viewportCard(shell,{'value',1}));first.header:Click();first=assert(viewportCard(shell,{'value',1}));local top=first.proxy;local pane=first.pane\010    top:SetCallback('OnClose',function() end);top:Hide();assert(not shell.frame:IsShown() and shell.closeOverride)\010    c.frame.workbenchBar:SetValue(c.frame.workbenchBar.scrollRange);assert(first.token and first.proxy==top and first.pane==pane,'scroll retired a child-owned field pane')\010    top:GetUserData('root').value[1].number=8;a.LayoutConditionFrame(top);top:Show()\010    assert(shell.frame:IsShown() and shell.active.working.value[1].number==8 and root.value[1].number==1)\010    shell.apply:Click();assert(root.value[1].number==8 and not shell.active)\010end)\010test('large viewport height changes retain a visible scroll anchor and invalid pending input',function()\010    local f=fixture();local a=f.addon\010    a:RegisterCondition('NATIVE',{description='Native',fields={number='number'},valid=function() return true end,print=function() return 'Native' end,\010        widget=function(parent,_,value) local w=a:CreateConditionSlider();w:SetValue(value.number);parent:AddChild(w) end})\010    local root={type='AND',value={}};for i=1,350 do root.value[i]={type='NATIVE',number=1} end\010    local shell=a:EditCondition(1,0,root,function() end);local c=shell.canvas;c.frame.workbenchBar:SetValue(c.scene.cards[2].y)\010    local first=assert(viewportCard(shell,{'value',1}));first.header:Click();first=assert(viewportCard(shell,{'value',1}))\010    c.frame.workbenchBar:SetValue(first.model.y+7);local before=c.frame.workbenchBar:GetValue()-first.model.y\010    local input=first.pane.children[1];input.editbox:SetText('invalid');input.editbox.scripts.OnTextChanged(input.editbox,true)