rows["tests/fixtures/restore_stock_targets_observation.lua"]={current="-- Exact complete-module inverse for the reviewed Unit3 observation/report slice.\010local sources={\010 ['UI/settings_stock.lua']={old=[====[-- Profile desired-stock editing only; inventory observations belong to a later view session.\010local addon_name,addon=...\010local L=LibStub('AceLocale-3.0'):GetLocale(addon_name)\010local function integer(n)return type(n)=='number'and n==n and n~=math.huge and n~=-math.huge and n%1==0 end\010local function quantity(text)local n=tonumber(text);if integer(n)and n>=0 and n<=1000000 then return n end end\010function addon:ItemSettingsSourceOptions(p,options)\010 if p.stockProfile~=self.db.profile or p.stockGlobal~=self.db.global or p.stockChar~=self.db.char then\010  p.stockProfile,p.stockGlobal,p.stockChar=self.db.profile,self.db.global,self.db.char\010  p.itemSettingsSource='itemsets';p.stockSelection=nil;p.newStockTarget=nil\010 end\010 options.sources={{value='itemsets',text=L['Item Sets']},{value='stock',text=L['Stock']}};options.source=p.itemSettingsSource\010 local function choose(value)p.itemSettingsSource=value;p.creating=false;p.newStockTarget=nil;p.newItemSetName=nil;p:Draw()end\010 options.chooseSource=choose\010 options.requestSource=function(value)\010  if value==p.itemSettingsSource then return end\010  if p.creationUsedForNew then p:RequestLeave(function()choose(value)end)\010  elseif p:FlushEdits()then choose(value)end\010 end\010 return options\010end\010function addon:BuildStockSettings(p)\010 local store=p:SettingsData();local raw=rawget(self.db.profile,'stockTargets');local valid,reason=self.StockTargets.Validate(raw)\010 local options=self:ItemSettingsSourceOptions(p,{})\010 if not valid then\010  p:UseRoster({},nil,function()end,options);p:Heading(L['Stock targets']);p:Text(L['Invalid stock targets; data preserved.']);p:Text(reason)\010  p:Button('stock_reset',L['Reset targets'],function()\010   local profile,global,char=self.db.profile,self.db.global,self.db.char;local expected=rawget(profile,'stockTargets')\010   p:RequestLeave(function()\010    if not p.active or self.db.profile~=profile or self.db.global~=global or self.db.char~=char then return end\010    p:Confirm(L['Reset invalid stock targets? This cannot be undone.'],function()\010     if InCombatLockdown and InCombatLockdown()then p:Message(L['Leave combat before applying these settings.']);return end\010     if self.db.profile~=profile or self.db.global~=global or self.db.char~=char or not rawequal(rawget(profile,'stockTargets'),expected) then p:Message(L['Settings changed elsewhere. Cancel to reload them before applying.']);return end\010     profile.stockTargets=nil;p:DiscardSettingsDraft();p:Draw()\010    end)\010   end)\010  end)\010  return\010 end\010 local plan=store.profile.stockTargets or {};local entries={}\010 for id,row in pairs(plan)do entries[#entries+1]={value=id,text=string.format('%.0f',row.itemID),icon='Interface\\\\Icons\\\\INV_Misc_QuestionMark'}end\010 table.sort(entries,function(a,b)return plan[a.value].itemID<plan[b.value].itemID end)\010 if not plan[p.stockSelection]and not p.creating then p.stockSelection=entries[1]and entries[1].value end\010 local function create()p.previousStockSelection=p.stockSelection;p.stockSelection=nil;p.creating=true;p.newStockTarget={minimum=0,target=0,enabled=true};p:Draw()end\010 options.new=create;options.newText=L['Add stock target']\010 p:UseRoster(entries,p.stockSelection,function(id)p.stockSelection=id;p.creating=false;p.newStockTarget=nil;p:Draw()end,options)\010 p:SetRosterActions({{key='new_collection',text=L['New'],icon='plus',enabled=#entries<128,action=create}})\010 p:Heading(L['Stock targets']);p:HistoryActions()\010 local row=p.creating and p.newStockTarget or plan[p.stockSelection]\010 if not row then p:Text(L['No stock targets.']);return end\010 local id=p.stockSelection\010 local function accepted(value)\010  if not integer(value)or value<=0 then return false end\010  for key,other in pairs(plan)do if key~=id and other.itemID==value then return false end end\010  return true\010 end\010 local itemLabel\010 local function itemText()return row.itemID and string.format(L['Item ID: %s'],string.format('%.0f',row.itemID))or L['Choose an item first.']end\010 p:Reference('itemID',L['Item'],row.itemID,'Item_EditBox',{accept=accepted},function(value)row.itemID=value;if itemLabel then itemLabel:SetText(itemText())end;if id then p:UpdateRosterEntry(id,{text=string.format('%.0f',value)})end end)\010 itemLabel=p:Text(itemText());p.fields.stock_item_id=itemLabel\010 p:Check('enabled',L['Enabled'],row.enabled,function(value)row.enabled=value end)\010 local function parseMinimum(text)local n=quantity(text);local other=p.fields.target and quantity(p.fields.target:GetText())or row.target;if n and other and n<=other then return n end end\010 local function parseTarget(text)local n=quantity(text);local other=p.fields.minimum and quantity(p.fields.minimum:GetText())or row.minimum;if n and other and other<=n then return n end end\010 p:Edit('minimum',L['Minimum'],row.minimum,parseMinimum,function(value)row.minimum=value end)\010 p:Edit('target',L['Target'],row.target,parseTarget,function(value)row.target=value end)\010 if p.creating then\010  p:CreationActions(function()\010   if #entries>=128 or not accepted(row.itemID)or not self.StockTargets.Validate({candidate=row})then p:Message(L['Complete the highlighted input fields before applying.']);return end\010   local new=self:uuid();if plan[new]then p:Message(L['This name is already in use.']);return end\010   store.profile.stockTargets=plan;plan[new]=row;p.stockSelection=new;p.creating=false;p.newStockTarget=nil;p:Draw()\010  end,function()p.creating=false;p.newStockTarget=nil;p.stockSelection=p.previousStockSelection;p:Draw()end)\010 else\010  self:SettingsTopDelete(p,function()if p:FlushEdits()then plan[id]=nil;p.stockSelection=nil;p:Draw()end end)\010 end\010end\010]====],current=[====[-- Profile desired-stock editing and a private visible-only inventory observation session.\010local addon_name,addon=...\010local L=LibStub('AceLocale-3.0'):GetLocale(addon_name)\010local function integer(n)return type(n)=='number'and n==n and n~=math.huge and n~=-math.huge and n%1==0 end\010local function quantity(text)local n=tonumber(text);if integer(n)and n>=0 and n<=1000000 then return n end end\010-- Observations belong to one visible pane/owner lease and never enter desired data.\010local sessions={}\010local paint,request\010local function stockClearReport(d,expected)\010 if d.stockLease and d.stockLease~=expected then return end\010 d.stockLease=nil\010 if d.chrome and d.chrome.drag then d.chrome.drag.moving=nil;d.frame:StopMovingOrSizing()end\010 if d.stockLease then return end\010 d.text='';d.input:ClearFocus()\010 if d.stockLease then return end\010 d.setting=true;d.input:SetText('')\010 if d.stockLease then return end\010 d.setting=false;d.measure:SetText('')\010 if d.stockOriginalHide then d.stockOriginalHide(d)else d:Hide()end\010 if not d.stockLease and d.stockOriginalFrameHide then d.stockOriginalFrameHide(d.frame)end\010end\010local function stockStop(p,expected)\010 local s=sessions[p];if not s or expected and s~=expected then return end\010 sessions[p]=nil;s.retired=true;s.refs=nil;s.counts=nil;s.reason=nil;s.profile=nil;s.global=nil;s.char=nil\010 local pending=s.pending;s.pending=nil\010 s.events:UnregisterAllEvents();s.events:SetScript('OnEvent',nil)\010 if s.report then stockClearReport(s.report,s);s.report=nil end\010 if pending and pending.handle then pcall(addon.CancelTimer,addon,pending.handle)end\010end\010local function stockLive(s)\010 local p=s.p\010 return not s.retired and sessions[p]==s and p.active and p.settingsKey=='ItemSets'and p.itemSettingsSource=='stock'and p.frame:IsVisible()\010 and rawequal(p.profile,addon.db.profile)and rawequal(p.global,addon.db.global)and rawequal(p.char,addon.db.char)\010 and rawequal(s.profile,addon.db.profile)and rawequal(s.global,addon.db.global)and rawequal(s.char,addon.db.char)\010end\010local function stockSaved(s)\010 if not stockLive(s)then return end\010 local raw=rawget(s.profile,'stockTargets');if not addon.StockTargets.Validate(raw)then return end\010 return true,raw\010end\010local function stockReport(s,plan)\010 if s.pending then return end\010 local platform=addon.Platform;local counts=s.counts\010 local ok,report=pcall(function()\010  if not platform:CanReadValue(counts)or type(counts)~='table'or getmetatable(counts)~=nil then return addon.StockTargets.BuildReport(plan,nil,'inventory-unavailable')end\010  local selected={}\010  for _,row in pairs(plan or{})do\010   local count=rawget(counts,row.itemID)\010   if not platform:CanReadValue(count)then return addon.StockTargets.BuildReport(plan,nil,'inventory-unavailable')end\010   if count~=nil then selected[row.itemID]=count end\010  end\010  return addon.StockTargets.BuildReport(plan,selected,s.reason)\010 end)\010 if ok then return report end\010end\010local function copyReady(s)\010 local ok,raw=stockSaved(s);if not ok or s.p.creating then return end\010 local p=s.p\010 if not p.draft or not p.draftBaseline or not addon.StockTargets.Validate(p.draft.profile.stockTargets)or not addon.StockTargets.Validate(p.draftBaseline.profile.stockTargets)then return end\010 if p:IsSettingsDraftDirty()or not addon:SettingsDataEqual(raw,p.draftBaseline.profile.stockTargets)then return end\010 local report=stockReport(s,raw)\010 if report and report.complete then return report,raw end\010end\010paint=function(s)\010 if not stockLive(s)then stockStop(s.p,s);return end\010 local refs=s.refs;if not refs or not s.p:Valid(refs.generation)then return end\010 local saved=stockSaved(s)\010 if not saved then s.ready=false;s.counts=nil end\010 local plan=s.p.draft and s.p.draft.profile.stockTargets\010 local report=saved and addon.StockTargets.Validate(plan)and stockReport(s,plan)\010 local selected=refs.row and addon.StockTargets.