rows["validate.lua"]={current="local addon_name, addon = ...\010local invalidateDependencies=addon.InvalidateRotationDependencies\010if type(invalidateDependencies)~='function' then invalidateDependencies=nil end\010\010local L = LibStub(\"AceLocale-3.0\"):GetLocale(addon_name)\010\010local function mark_for_remove(toremove, key)\010    if type(key) ~= \"number\" or key < 1 then\010        toremove.not_array = true\010    end\010    if not toremove.data then\010        toremove.data = {}\010    end\010    table.insert(toremove.data, key)\010end\010\010local function apply_remove(toremove, tbl, fix)\010    if fix and toremove.data then\010        if toremove.not_array then\010            for _, key in pairs(toremove.data) do\010                tbl[key] = nil\010            end\010        else\010            local offs = 0\010            for idx=1,#toremove.data do\010                table.remove(tbl, toremove.data[idx] - offs)\010                offs = offs + 1\010            end\010        end\010    end\010\010    if fix and toremove.data and invalidateDependencies then invalidateDependencies(addon,'all',nil) end\010    addon.Functions.collections.cleanArray(toremove)\010end\010\010local function validate_basic(prefix, data, template, fix, preserved)\010    local toremove = {}\010    for k,v in pairs(data) do\010        if preserved and preserved[k] then\010            -- Semantic source metadata has its own non-destructive validator.\010        elseif template[k] == nil then\010            addon:warn(\"Extra Field %s:%s\", prefix, tostring(k))\010            mark_for_remove(toremove, k)\010        elseif type(v) ~= type(template[k]) then\010            addon:warn(\"Incorrect type for %s:%s (was %s, expected %s)\", prefix, tostring(k), type(v), type(template[k]))\010            mark_for_remove(toremove, k)\010        elseif type(v) == \"table\" then\010            if addon.Functions.collections.tablelength(template[k]) > 0 and #template[k] == 0 then\010                validate_basic(prefix .. \":\" .. k, v, template[k], fix)\010            end\010        end\010    end\010    apply_remove(toremove, data, fix)\010end\010\010local function validate_itemset_items(prefix, name, items, fix)\010    local toremove = {}\010    for idx, item in pairs(items) do\010        if type(item) ~= \"string\" and type(item) ~= \"number\" then\010            addon:warn(\"Invalid item in itemset %s:%s\", prefix, name)\010            mark_for_remove(toremove, idx)\010        end\010    end\010    apply_remove(toremove, items, fix)\010end\010\010local function is_uuid(uuid)\010    return type(uuid) == \"string\" and uuid:match(\"(%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x)\") ~= nil\010end\010\010function addon:validate_itemset(prefix, name, itemset, fix)\010    if not is_uuid(name) then\010        addon:warn(\"Invalid ID for itemset %s:%s\", prefix, name)\010        if fix then\010            addon.Functions.collections.cleanArray(itemset)\010            if invalidateDependencies then invalidateDependencies(addon,'itemset',name) end\010            return\010        end\010    end\010    local template = {\010        modified = false,\010        name = \"test\",\010        items = {}\010    }\010    validate_basic(prefix .. \":\" .. name, itemset, template, fix)\010    validate_itemset_items(prefix, name, itemset.items, fix)\010end\010\010function addon:validate_effect(prefix, name, effect, fix)\010    if not is_uuid(name) then\010        addon:warn(\"Invalid ID for effect %s:%s\", prefix, name)\010        if fix then\010            addon.Functions.collections.cleanArray(effect)\010            if invalidateDependencies then invalidateDependencies(addon,'effect',name) end\010            return\010        end\010    end\010    if not effect[\"type\"] then\010        addon:warn(\"No effect type for %s:%s\", prefix, name)\010        if fix then\010            addon.Functions.collections.cleanArray(effect)\010            if invalidateDependencies then invalidateDependencies(addon,'effect',name) end\010        end\010        return\010    end\010\010    local function get_effect_template(type)\010        if type == \"texture\" then\010            return {\010                texture = \"some_texture\"\010            }\010        elseif type == \"pixel\" then\010            return {\010                lines = 8,\010                frequency = 0.25,\010                length = 2,\010                thickness = 2\010            }\010        elseif type == \"autocast\" then\010            return {\010                particles = 4,\010                frequency = 0.25,\010                scale = 1.0\010            }\010        elseif type == \"proc\" then\010            return {duration=1,startAnim=false}\010        elseif type == \"blizzard\" then\010            return {\010                frequency = 0.125\010            }\010        elseif type == \"dazzle\" then\010            return {\010                texture = \"some_texture\",\010                frequency = 0.25,\010                sequence = {},\010            }\010        elseif type == \"animate\" then\010            return {\010                frequency = 0.25,\010                sequence = {},\010            }\010        elseif type == \"pulse\" then\010            return {\010                texture = \"some_texture\",\010                frequency = 0.25,\010                sequence = {},\010            }\010        elseif type == \"custom\" then\010            return {\010                frequency = 0.25,\010                sequence = {},\010            }\010        elseif type == \"rotate\" then\010            return {\010                texture = \"some_texture\",\010                frequency = 0.25,\010                steps = 4,\010                reverse = false\010            }\010        end\010    end\010\010    local template = get_effect_template(effect[\"type\"])\010    if not template then\010        addon:warn(L[\"Unknown effect type for %s:%s (%s); record preserved.\"], prefix, name, tostring(effect.type))\010        return\010    end\010    if template.texture~=nil and type(effect.texture)==\"number\" then template.texture=1 end\010    template[\"type\"] = \"texture\"\010    template[\"name\"] = \"some name\"\010    validate_basic(prefix .. \":\" .. name, effect, template, fix)\010\010    if effect[\"sequence\"] then\010        local toremove = {}\010        for idx, seq in pairs(effect[\"sequence\"]) do\010            if effect[\"type\"] == \"dazzle\" then\010                if type(seq) == \"table\" then\010                    local template = { r = 1.0, g = 1.0, b = 1.0, a = 1.0 }\010                    validate_basic(prefix .. \":\" .. name .. \":\" .. idx, seq, template, fix)\010                else\010                    addon:warn(\"Invalid type on %s effect sequence %s:%s:%d\", effect[\"type\"], prefix, name, idx)\010                    mark_for_remove(toremove, idx)\010                end\010            elseif effect[\"type\"] == \"animate\" then\010                if type(seq) ~= \"string\" and type(seq) ~= \"number\" then\010                    addon:warn(\"Invalid type on %s effect sequence %s:%s:%d\", effect[\"type\"], prefix, name, idx)\010                    mark_for_remove(toremove, idx)\010                end\010            elseif effect[\"type\"] == \"pulse\" then\010                if type(seq) ~= \"number\" then\010                    addon:warn(\"Invalid type on %s effect sequence %s:%s:%d\", effect[\"type\"], prefix, name, idx)\010                    mark_for_remove(toremove, idx)\010                end\010            elseif effect[\"type\"] == \"custom\" then\010                if type(seq) == \"table\" then\010                    local template = {\010                        texture = type(seq.texture)==\"number\" and 1 or \"some_texture\",\010                        angle = 0.0,\010                        color = { r = 1.0, g = 1.0, b = 1.0, a = 1.0 },\010                        magnification = 0.0,\010                    }\010                    validate_basic(prefix .. \":\" .. name .. \":\" .. idx, seq, template, fix)\010                else\010                    addon:warn(\"Invalid type on %s effect sequence %s:%s:%d\", effect[\"type\"], prefix, name, idx)\010                    mark_for_remove(toremove, idx)\010                end\010            end\010        end\010        apply_remove(toremove, effect[\"sequence\"], fix)\010    end\010end\010\010function addon:validate_announce(prefix, idx, announce, fix)\010    if not announce[\"type\"] then\010        addon:warn(\"No announce type for %s:%s\", prefix, idx)\010        if fix then\010            addon.Functions.collections.cleanArray(announce)\010        end\010        return\010    end\010\010    local template = {\010        type = \"spell\",\010        disabled = false,\010        announce = \"party\",\010        event = \"SUCCEEDED\",\010        id = \"61b36ed1-fa31-4656-ad71-f3d50f193a85\",\010        name = \"Announcement\",\010        value = \"Some Announce\",\010        announce_sound = \"Sound\"\010    }\010\010    if announce[\"type\"] == \"spell\" or announce[\"type\"] == \"petspell\" or announce[\"type\"] == \"pet\" then\010        template[\"spell\"] = 12345\010        template[\"ranked\"] = false\010    elseif announce[\"type\"] == \"item\" then\010        template[\"item\"] = {}\010    else\010        addon:warn(\"Invalid type for announce %s:%s\", prefix, tostring(announce[\"id\"]))\010        if fix then\010            addon.Functions.collections.cleanArray(announce)\010            return\010        end\010    end\010\010    validate_basic(prefix, announce, template, fix, announce.type==\"item\" and {item=true} or nil)\010\010    if not announce[\"id\"] or not is_uuid(announce[\"id\"]) then\010        addon:warn(\"Invalid ID for announce %s:%s\", prefix, tostring(announce[\"id\"]))\010        if fix then\010            addon.Functions.collections.cleanArray(announce)\010            return\010        end\010    end\010\010    if announce.type==\"item\" and not addon:IsValidAnnouncementItemReference(announce.item) then\010        local message=fix and L[\"Invalid item reference for announce %s:%s; reference preserved; announcement disabled.\"]\010            or L[\"Invalid item reference for announce %s:%s; explicit repair will preserve the reference and disable the announcement.\"]\010        addon:warn(message, prefix, tostring(announce.id))\010        if fix then announce.disabled=true end\010    end\010end\010\010function addon:validate_condition_group(prefix, idx, group, fix)\010    local template = {\010        id = \"61b36ed1-fa31-4656-ad71-f3d50f193a85\",\010        name = \"Some Group\",\010        conditions = {},\010        icon = type(group.icon)==\"number\" and 1 or \"Interface\\\\Icons\\\\INV_Misc_Book_09\"\010    }\010\010    validate_basic(prefix .. \":\" .. idx, group, template, fix)\010    if group.icon~=nil and not (type(group.icon)==\"string\" and #group.icon>0 and #group.icon<=1024 or type(group.icon)==\"number\" and group.icon>0 and group.icon<math.huge and group.icon%1==0) then\010        addon:warn(\"Invalid category icon %s:%s\",prefix,tostring(idx));if fix then group.icon=nil end\010    end\010end\010\010function addon:validate_custom_condition(prefix, name, custom_condition, fix)\010    local semantic={fields=true,icon=true,disabled=true,fieldOrder=true,bindings=true,parameters=true,requiredFields=true}\010    local template={disabled=false,fieldOrder={},bindings={},parameters={},requiredFields={}}\010    for key,value in pairs(addon.empty_condition) do template[key]=value end\010    validate_basic(prefix .. \":\" .. name, custom_condition, template, fix, semantic)\010\010    local function invalid(field,reason)\010        local message=fix and L[\"Invalid custom condition %s:%s field %s (%s); source preserved; condition disabled.\"]\010            or L[\"Invalid custom condition %s:%s field %s (%s); explicit repair will preserve source and disable the condition.\"]\010        addon:warn(message, prefix, name, field, reason or \"invalid-data\")\010        if fix then\010            custom_condition.disabled=true\010            local saved=addon.db and addon.db.global and addon.db.global.custom_conditions\010            local definition=addon.conditionDefinitions and addon.conditionDefinitions[name]\010            if type(saved)==\"table\" and saved[name]==custom_condition and definition and definition.customCode==true and definition.disabled~=true then\010                -- Do not invoke lifecycle hooks or recompile user source from\010                -- repair. Selection notices this registry version next pass.\010                definition.disabled=true\010                addon.conditionRegistryVersion=(addon.conditionRegistryVersion or 0)+1\010                if invalidateDependencies then invalidateDependencies(addon,'condition',name) end\010            end\010        end\010    end\010    -- Check data contracts only. Repair must not compile callback text, resolve\010    -- currently unavailable helper bindings, or execute registration hooks.\010    local fields,fieldReason=addon:NormalizeCustomFieldSchema(custom_condition.fields,true)\010    if not fields then invalid(\"fields\",fieldReason) end\010    if not addon:IsCategoryIcon(custom_condition.icon) then invalid(\"icon\",\"invalid-icon\") end\010    if custom_condition.disabled~=nil and type(custom_condition.disabled)~=\"boolean\" then invalid(\"disabled\",\"invalid-disabled-flag\") end\010    local parameters,parameterReason=addon:NormalizeCustomConditionParameters(custom_condition.parameters)\010    if not parameters then invalid(\"parameters\",parameterReason) end\010    if custom_condition.bindings~=nil then\010        local arguments={{name=\"value\"},{name=\"cache\"},{name=\"evalStart\"},{name=\"spec\"},{name=\"parent\"},{name=\"frame\"},{name=\"tag\"}}\010        for _,aliases in pairs(parameters or {}) do for _,alias in ipairs(aliases) do arguments[#arguments+1]={name=alias} end end\010        local bindings,reason=addon:NormalizeFunctionBindings(custom_condition.bindings,arguments)\010        if not bindings then invalid(\"bindings\",reason) end\010    end\010    if custom_condition.requiredFields~=nil and not addon:NormalizeCustomConditionRequiredFields(custom_condition.requiredFields,fields or {}) then invalid(\"requiredFields\",\"invalid-required-fields\") end\010    if custom_condition.fieldOrder~=nil and not addon:NormalizeCustomFieldOrder(custom_condition.fieldOrder,fields or {}) then invalid(\"fieldOrder\",\"invalid-field-order\") end\010end\010\010local function validate_rotation_condition(prefix, condition, fix)\010    if addon.Functions.collections.tablelength(condition) == 0 then\010        return\010    end\010\010    if type(condition[\"type\"]) ~= \"string\" then\010        addon:warn(\"Invalid type for %s\", prefix)\010        if fix then\010            addon.Functions.collections.cleanArray(condition)\010        end\010        return\010    end\010\010    local full_id = prefix .. \":\" .. condition[\"type\"]\010    local fields = addon.Functions.collections.deepcopy(select(4, addon:describeCondition(condition[\"type\"])))\010    -- The condition might not exist if you're not playing a class where it is active.\010    if not fields then\010        return\010    end\010    fields[\"type\"] = \"string\"\010    fields[\"disabled\"] = \"boolean\"\010    if condition.type==\"AND\" or condition.type==\"OR\" or condition.type==\"NOT\" then fields.name=\"string\" end\010\010    local function handle_array_field(cond, field)\010        if type(cond) == \"table\" then\010            for i=1,#field do\010                if type(field[i]) == \"table\" then\010                    local allfound = true\010                    for j=1,#cond do\010                        local subfound = handle_array_field(cond[j], field[i])\010                        if not subfound then\010                            allfound = false\010                            break\010                        end\010                    end\010                    if allfound then\010                        return true\010                    end\010                end\010            end\010        else\010            for i=1,#field do\010                if type(field[i]) ~= \"table\" and type(cond) == field[i] then\010                    return true\010                end\010            end\010        end\010        return false\010    end\010\010    local function handle_fields(cond, f, subtree)\010        local keyremove = {}\010        for key, data in pairs(cond) do\010            local newsubtree = (subtree and (subtree .. \".\") or \"\") .. key\010            local field = f[key]\010            if field == nil then\010                addon:warn(\"Extra Field %s.%s\", full_id, newsubtree)\010                mark_for_remove(keyremove, key)\010            elseif type(field) == \"table\" then\010                -- The #field specifies this is an array, specifically.\010                if #field > 0 then\010                    local found = handle_array_field(data, field)\010                    if not found then\010                        addon:warn(\"Condition %s.%s has data of the wrong type (got %s)\", full_id, newsubtree, type(data))\010                        if fix then\010                            mark_for_remove(keyremove, key)\010                        end\010                    end\010                elseif type(data) == \"table\" then\010                    handle_fields(data, field, newsubtree)\010                else\010                    addon:warn(\"Condition %s.%s has data of the wrong type (got %s)\", full_id, newsubtree, type(data))\010                    mark_for_remove(keyremove, key)\010                end\010            elseif field == \"condition\" then\010                validate_rotation_condition(full_id, data, fix)\010            elseif type(field) == \"string\" and type(data) == \"table\" then\010                if addon.Functions.collections.tablelength(data) ~= #data then\010                    addon:warn(\"Condition %s.%s provides a table where an array is required\", full_id, subtree)\010                    mark_for_remove(keyremove, key)\010                elseif #data > 0 then\010                    local basetype = field:match(\"^(.*)%[%]$\")\010                    if basetype == \"condition\" then\010                        local toremove = {}\010                        for i=1,#data do\010                            if type(data[i]) == \"table\" then\010                                validate_rotation_condition(full_id .. \"[\" .. i .. \"]\", data[i], fix)\010                            else\010                                addon:warn(\"Condition %s.%s[%d] has data of the wrong type (expected %s, got %s)\", full_id, newsubtree, i, \"table\", type(data[i]))\010                                mark_for_remove(toremove, i)\010                            end\010                        end\010                        apply_remove(toremove, data, fix)\010                    elseif basetype then\010                        local toremove = {}\010                        for i=1,#data do\010                            if type(data[i]) ~= basetype then\010                                addon:warn(\"Condition %s.%s[%d] has data of the wrong type (expected %s, got %s)\", full_id, newsubtree, i, basetype, type(data[i]))\010                                mark_for_remove(toremove, i)\010                            end\010                        end\010                        apply_remove(toremove, data, fix)\010                    else\010                        addon:error(\"Unknown field type used in field spec for array on %s:%s\", full_id, newsubtree)\010                    end\010                end\010            elseif type(data) ~= field then\010                addon:warn(\"Condition %s.%s has data of the wrong type (expected %s, got %s)\", full_id, newsubtree, field, type(data))\010                mark_for_remove(keyremove, key)\010            end\010        end\010        apply_remove(keyremove, cond, fix)\010    end\010\010    handle_fields(condition, fields)\010end\010\010function addon:validate_rotation(prefix, id, rotation, fix)\010    if type(rotation)=='table' and rotation.priority~=nil and not self.RotationData.GetRotationPriority(rotation.priority) then\010        self:warn(L['Invalid switch priority for %s:%s; explicit repair resets it to zero.'],prefix,id)\010        if fix then rotation.priority=nil end\010    end\010    -- The old template fixer knows only flat actions. Use the non-destructive\010    -- schema for branch bodies; never strip their arms or future metadata.\010    if type(rotation)==\"table\" and type(rotation.rotation)==\"table\" then\010        for _,step in pairs(rotation.rotation) do\010            if type(step)==\"table\" and step.type==\"branch\" then\010                local settings=self.GetImportValidationOptions and self:GetImportValidationOptions() or {conditions=self.conditionDefinitions}\010                local result=self.RotationData.ValidateBody(rotation,settings)\010                for _,diagnostic in ipairs(result.diagnostics) do self:warn(\"%s:%s %s\",prefix,id,diagnostic.code..\" \"..diagnostic.path) end\010                return\010            end\010        end\010    end\010    if id ~= DEFAULT and not is_uuid(id) then\010        addon:warn(\"Invalid ID for rotation %s:%s\", prefix, id)\010        if fix then\010            addon.Functions.collections.cleanArray(rotation)\010            return\010        end\010    end\010\010    local template = {\010        name = \"Some Name\",\010        revision = 1,\010        description = \"Rotation description\",\010        metadata = {},\010        tags = {},\010        priority = 0,\010        disabled = 