local targets,catalogs={},{}
local function target(row,stage)
 local cache=targets[row];if not cache then cache={};targets[row]=cache end
 if cache[stage]then return cache[stage]end
 local changes=assert(row.stages[stage],'unknown composition stage');local text=row.current
 for _,c in ipairs(changes)do assert(c.at>=1 and c.at+c.remove<=#text+1,'outer composition hunk bounds differ');text=text:sub(1,c.at-1)..c.previous..text:sub(c.at+c.remove)end
 cache[stage]=text;return text
end
local function same(a,b)
 if type(a)~=type(b)then return false end;if type(a)~='table'then return a==b end
 if getmetatable(a)~=nil or getmetatable(b)~=nil then return false end
 for k,v in pairs(a)do if not same(v,b[k])then return false end end
 for k in pairs(b)do if a[k]==nil then return false end end;return true
end
local function copy(value)if type(value)~='table'then return value end;local result={};for k,v in pairs(value)do result[k]=copy(v)end;return result end
local function catalog(source)
 if not catalogs[source]then
  local addon={};assert(loadstring(source,'@pinned-literal-built-in-catalog'))('rotationmaster',addon)
  catalogs[source]=assert(addon.BuiltinSourceCatalog)
 end
 return catalogs[source]
end
return function(value,path,stage,mode)
