 if mode=='catalog'then
  local row=rows['Data/builtin_sources.lua'];local wanted=catalog(target(row,stage))
  if same(value,catalog(row.current))then return copy(wanted)end
  for known in pairs(row.stages)do if same(value,catalog(target(row,known)))then return value end end
  error('unrelated complete composition catalog')
